const KIDS4 = [{"id":"K4","name":"Family and Friends 4","cefr":"Kids","weeks":14,"focus":"Two lessons per unit · stories every week · big-screen grammar games · American English","kids":true,"units":[{"n":1,"title":"Week 1","icon":"Globe","lessons":[{"n":1,"subtopic":"Starter + Unit 1A · The food here is great!","kd":{"kind":"A","label":"Starter + Unit 1A · The food here is great!","goal":"Starter (back together: like + -ing, can for permission, a / an / some, be going to, the time, comparing) and Unit 1: restaurant words, present simple and present continuous.","tr":[["Мы часто ходим в этот ресторан.","We often come to this restaurant."],["Еда здесь отличная!","The food here is great!"],["Официанты обычно носят синюю форму.","The waiters usually wear blue uniforms."],["Сегодня они носят зелёную форму.","Today they're wearing green uniforms."],["Мы обычно едим пасту, но сейчас мы едим пиццу.","We usually have pasta, but now we're having pizza."],["Можно мне миску супа и тарелку салата?","Can I have a bowl of soup and a plate of salad?"],["К сожалению, у нас нет пасты.","Sorry, we don't have any pasta."],["Вы наши первые клиенты.","You're our first customers."],["Я никогда не пью кофе.","I never drink coffee."],["Мама пьёт чашку кофе прямо сейчас.","Mom is drinking a cup of coffee right now."]],"ch":[["Обычно я завтракаю дома, но сегодня я завтракаю в кафе с друзьями.","I usually have breakfast at home, but today I'm having breakfast in a café with my friends."],["Моя сестра редко ест суп, но сейчас она ест большую миску супа.","My sister rarely eats soup, but she's eating a big bowl of soup now."]],"us":[["Mum","Mom"],["favourite","favorite"],["chilli","chili"],["biscuits","cookies"],["we haven't got any pasta","we don't have any pasta"],["we've got a selection of pizzas","we have a selection of pizzas"]],"copy":["waiter","waitress","uniform","menu","customer","bottle of water","cup of coffee","glass of milk","bowl of soup","plate of salad","breakfast","lunch","dinner","restaurant","cook","delicious"],"rwords":[],"retell":[],"rule":{"title":"Present simple and present continuous","lines":["Present simple = a habit, things we do many times: I have pasta. She wears a uniform.","Present continuous = now, at the moment of speaking: I'm having pizza. She's wearing green today.","Time words — habit: always · usually · sometimes · rarely · never   |   now: now · today · right now · at the moment","Always / usually / sometimes / rarely / never go BEFORE the verb, but AFTER am / is / are: He usually has pasta. He is usually happy."],"signal":"usually / every day → present simple.  now / today / right now / at the moment → present continuous (am / is / are + -ing).","ru":"In Russian the same verb is used for both: «Я ем суп» (always or now). In English we must choose: I eat soup (always) or I'm eating soup (now).","oops":["I eating soup now. → I'm eating soup now.","She is drink milk. → She is drinking milk.","He is usually have lunch at school. → He usually has lunch at school.","They usually are late. → They are usually late."]},"hasBig":true,"big":[["r","Starter: What's the time? (9:10)","It's ten past nine."],["c","I'd like ___ pasta, please.",["a","some"],1,"pasta = uncountable → some"],["c","Max is ___ than Holly.",["tall","taller"],1,"than → taller"],["c","Leo is the ___ cousin.",["taller","tallest"],1,"the → tallest"],["r","What is Max going to do this weekend? (read a comic)","He's going to read a comic."],["c","We usually ___ pasta.",["have","are having"],0,"usually → habit → present simple"],["c","Look! They ___ pizza now.",["have","are having"],1,"now → present continuous"],["c","She ___ a sandwich every day.",["eats","is eating"],0,"every day → present simple"],["c","Mom is ___ coffee right now.",["drinks","drinking"],1,"right now → -ing"],["c","He never ___ soup.",["has","having"],0,"never → present simple"],["c","I ___ my homework at the moment.",["do","am doing"],1,"at the moment → present continuous"],["r","Find the mistake: She is drink water now.","She is drinking water now."],["r","Find the mistake: They usually are wearing blue.","They usually wear blue uniforms."],["r","Put the words in order: on time / is / always / She","She is always on time."],["p","g-waiter","Who is he? What does he do?","He's a waiter. He works in a restaurant."],["p","g-k-glass-of-milk","Ask for it politely.","Can I have a glass of milk, please?"],["p","g-k-bowl-of-soup","Ask for it politely.","Can I have a bowl of soup, please?"],["p","g-k-plate-of-salad","Ask for it politely.","Can I have a plate of salad, please?"],["p","g-k-cup-of-coffee","Ask for it politely.","Can I have a cup of coffee, please?"],["p","g-k-bottle-of-water","Ask for it politely.","Can I have a bottle of water, please?"]],"cb":[[4,"Starter · Back together"],[5,"Starter · Grammar 1"],[6,"Starter · Grammar 2"],[7,"Starter · Time and comparing"],[8,"Words and story"],[9,"Grammar"],[10,"Grammar and song"]],"wb":"Workbook pp. 4–7 (Starter) and pp. 8–10, Grammar Time p. 124","steps":["Warm-up: hello, names, and a quick chat: Who is in your family? What do you like doing?","Starter (p. 4): sing 'We're all back together', read the story: the kids talk about their families and hobbies","Starter (p. 5): like + -ing (What does Max like doing? He likes reading.), can / can't for permission (Can I play some games? No, you can't), a / an / some (I'd like some bread)","Starter (p. 6): be going to (What is he going to do this weekend?), spelling endings (lamp, tent, field, sand, plant, pond, bed, quilt, children, adults)","Starter (p. 7): the time (it's ten past nine, quarter to six), comparing with -er / -est (taller, the tallest), alphabetical order","Words (p. 8): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 8): listen, read in roles, act it out","Grammar (p. 9): Present simple and present continuous. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 10): Think of a girl. Look at the table and say: She usually has a bowl of salad. She's having a plate of rice right now.. Song: At my friend's house","Grammar Time (Workbook p. 124): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Unit 1B · The food here is great!","kd":{"kind":"B","label":"Unit 1B · The food here is great!","goal":"Long a and long e. Read about breakfast around the world. Talk about what you eat.","tr":[["Что ты обычно ешь на завтрак?","What do you usually eat for breakfast?"],["Абд Аллах из Египта.","Abd Allah is from Egypt."],["Он иногда ест хлеб с вареньем.","He sometimes eats bread with jam."],["Пит из Шотландии. Он обычно ест тост с маслом.","Pete is from Scotland. He usually has toast with butter."],["Моя любимая еда — кукурузные хлопья.","My favorite food is cornflakes."],["Мариана из Мексики. Она всегда ест большой завтрак.","Mariana is from Mexico. She always eats a big breakfast."],["У них нет обеда в школе.","They don't have lunch at school."],["Хыонг из Вьетнама. Она ест суп с лапшой.","Huong is from Vietnam. She has noodle soup."],["Её бабушка готовит его каждое утро.","Her grandma makes it every morning."],["Какой твой любимый напиток?","What's your favorite drink?"]],"ch":[["Кто готовит у вас дома? Я умею готовить блины.","Who cooks in your family? I can cook pancakes."],["Пит не ест большой завтрак, потому что он рано обедает в школе.","Pete doesn't have a big breakfast because he eats lunch early at school."]],"us":[["Mum","Mom"],["favourite","favorite"],["chilli","chili"],["biscuits","cookies"],["we haven't got any pasta","we don't have any pasta"],["we've got a selection of pizzas","we have a selection of pizzas"]],"copy":["beans","olive oil","toast","noodles","coconut","chili","corn","pancake"],"rwords":["beans","olive oil","toast","noodles","coconut","chili","corn","pancake"],"retell":["Egypt","Scotland","Mexico","Vietnam","mashed beans","cornflakes","huevos rancheros","rice balls"],"rule":{"title":"Present simple and present continuous","lines":["Present simple = a habit, things we do many times: I have pasta. She wears a uniform.","Present continuous = now, at the moment of speaking: I'm having pizza. She's wearing green today.","Time words — habit: always · usually · sometimes · rarely · never   |   now: now · today · right now · at the moment","Always / usually / sometimes / rarely / never go BEFORE the verb, but AFTER am / is / are: He usually has pasta. He is usually happy."],"signal":"usually / every day → present simple.  now / today / right now / at the moment → present continuous (am / is / are + -ing).","ru":"In Russian the same verb is used for both: «Я ем суп» (always or now). In English we must choose: I eat soup (always) or I'm eating soup (now).","oops":["I eating soup now. → I'm eating soup now.","She is drink milk. → She is drinking milk.","He is usually have lunch at school. → He usually has lunch at school.","They usually are late. → They are usually late."]},"hasBig":true,"big":[["c","My dad ___ to work by bus every day.",["goes","is going"],0,"every day → goes"],["c","Be quiet! The baby ___.",["sleeps","is sleeping"],1,"now → is sleeping"],["c","We ___ breakfast at seven o'clock.",["have","are having"],0,"a habit → have"],["c","It ___ today.",["rains","is raining"],1,"today → is raining"],["c","Pete ___ cereal for breakfast.",["usually has","is usually having"],0,"usually → present simple"],["r","Find the mistake: Mariana always is eating a big breakfast.","Mariana always eats a big breakfast."],["r","Put the words in order: you / eat / do / What / usually","What do you usually eat?"],["r","Put the words in order: is / lunch / having / She / now","She is having lunch now."],["r","Find the mistake: I eat a pancake right now.","I'm eating a pancake right now."],["r","Ask a friend about breakfast.","What do you usually eat for breakfast?"],["r","Say what your family is doing right now.","My mom is cooking. My brother is reading."],["r","Say something you rarely do.","I rarely eat soup."],["p","g-k-pancake","What is it?","It's a pancake."],["p","noodles","What is it?","It's a bowl of noodles."],["p","g-k-toast","What is it?","It's toast."]],"cb":[[11,"Phonics and spelling"],[12,"Skills time: reading"],[13,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 11–13 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 11): long a (train, tray, cake) and long e (tree, leaves, key)","Reading words (p. 12): read the English and the Russian, say and repeat","Reading (p. 12): What do you like for breakfast? (a magazine article): listen, read aloud in pairs, answer the questions","Retell with these words: Egypt, Scotland, Mexico, Vietnam, mashed beans, cornflakes, huevos rancheros, rice balls","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 13): Listening: dinner or lunch, Saturdays or Sundays, chicken or salad. Ask and answer: What do you usually eat for breakfast? What's your favorite meal? Who cooks in your family?","Writing preparation (p. 13): Syllables: clap and count (dinner = 2, restaurant = 3, tomato = 3). The writing task is about my eating habits. The writing task is homework.","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":3,"subtopic":"Unit 2A · We had a concert","kd":{"kind":"A","label":"Unit 2A · We had a concert","goal":"Music words. Past simple: was / were, had, and regular verbs (+ed). Time words: yesterday, last night, last week, two weeks ago.","tr":[["У нас был концерт дома.","We had a concert at our house."],["Все наши друзья были там.","All our friends were there."],["Лео играл на барабанах.","Leo played the drums."],["Эми играла на скрипке.","Amy played the violin."],["Публика хлопала и кричала «ура».","The audience clapped and cheered."],["Мой день рождения был вчера.","My birthday was yesterday."],["Вчера вечером я играл на барабанах.","Last night I played my drums."],["Две недели назад у них была вечеринка.","Two weeks ago, they had a party."],["На прошлой неделе мы были на концерте.","We were at a concert last week."],["Я не играл на гитаре.","I didn't play the guitar."]],"ch":[["Два года назад у нас был концерт в Австралии, и все мои друзья были там.","Two years ago, we had a concert in Australia, and all my friends were there."],["Вчера мой брат убрал свою комнату, а потом мы играли на компьютере.","Yesterday my brother tidied his room, and then we played on the computer."]],"us":[["programme","program"],["Mum","Mom"],["favourite","favorite"],["practises","practices"],["brilliant","great / wonderful"],["for ages","for a long time"],["We've got a picnic blanket.","We have a picnic blanket."]],"copy":["concert","drums","instruments","violin","audience","recorder","cheer","stage","program","trumpet","guitar","piano","flute","clap","enjoy","practice"],"rwords":[],"retell":[],"rule":{"title":"Past simple: was / were, had, and regular verbs","lines":["be → was / were:  I / he / she / it WAS · we / you / they WERE   (Everyone was great. The friends were there.)","have → had:  We had a concert.","Regular verbs + -ed: play → played · clap → clapped · cheer → cheered · tidy → tidied","Past time words: yesterday · last night · last week · two weeks ago. They go at the beginning or at the end: We had a concert last week. / Last week, we had a concert.","No: wasn't · weren't · didn't have · didn't + verb (I didn't play the guitar)."],"signal":"yesterday · last night · last week · two weeks ago → the verb is in the past.","ru":"In Russian the past ends in -л (играл). In English regular verbs end in -ed. Be careful: was / were and had are different forms.","oops":["We have a concert yesterday. → We had a concert yesterday.","They was at the concert. → They were at the concert.","I play the drums last week. → I played the drums last week.","She didn't played. → She didn't play."]},"hasBig":true,"big":[["c","We ___ a concert last week.",["have","had"],1,"last week → past → had"],["c","All our friends ___ there.",["was","were"],1,"friends = they → were"],["c","Everyone ___ great.",["was","were"],0,"everyone = one person → was"],["c","Amy ___ the violin two years ago.",["play","played"],1,"two years ago → -ed"],["c","The audience ___ and cheered.",["clapped","clap"],0,"past: clapped (double p)"],["c","My birthday ___ yesterday.",["is","was"],1,"yesterday → was"],["r","Find the mistake: We have a concert yesterday.","We had a concert yesterday."],["r","Find the mistake: They was at the concert.","They were at the concert."],["r","Find the mistake: I didn't played the guitar.","I didn't play the guitar."],["r","Say: yesterday / my birthday","Yesterday was my birthday."],["r","Put the words in order: week / We / a concert / had / last","We had a concert last week."],["p","g-k-drums","What are they?","They're drums."],["p","violin","What is it?","It's a violin."],["p","trumpet","What is it?","It's a trumpet."],["p","g-k-recorder","What is it?","It's a recorder."],["p","g-k-stage","Where do the musicians play?","They play on the stage."]],"cb":[[14,"Words and story"],[15,"Grammar"],[16,"Grammar and song"]],"wb":"Workbook pp. 14–16 and Grammar Time p. 124","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 14): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 14): listen, read in roles, act it out","Grammar (p. 15): Past simple: was / were, had, and regular verbs. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 16): Look at Lucy's calendar and write: Yesterday was Lucy's birthday. She was ten. Two days ago she had a party.. Song: What a busy week it is!","Grammar Time (Workbook p. 124): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}}],"goal":"Starter + Unit 1A · Unit 1B · Unit 2A"},{"n":2,"title":"Week 2","icon":"Gamepad2","lessons":[{"n":1,"subtopic":"Unit 2B · We had a concert","kd":{"kind":"B","label":"Unit 2B · We had a concert","goal":"Long i, long o, long u. Read the poem The Concert. Talk about music. Spelling: double the last letter.","tr":[["Парк был полон людей.","The park was full of people."],["Сегодня особенный день.","Today is a special day."],["Знаменитый оркестр играет в парке.","A famous orchestra is playing in the park."],["У нас есть одеяло для пикника.","We have a picnic blanket."],["Мы слышим трубы и барабаны.","We hear the trumpets and the drums."],["Когда музыка заканчивается, люди хлопают.","When the music ends, the people clap."],["Небо становится тёмным.","The sky is getting dark."],["Фейерверк взлетает в небо.","Fireworks shoot into the sky."],["Мы собираем вещи и идём домой.","We pack up and go home."],["Я засыпаю, но всё ещё слышу музыку.","I fall asleep, but I still hear the music."]],"ch":[["Ты умеешь играть на каком-нибудь инструменте? — Нет, но я хочу играть на гитаре.","Can you play an instrument? — No, but I want to play the guitar."],["Я хочу стать знаменитым музыкантом, поэтому я тренируюсь каждый день.","I want to be a famous musician, so I practice every day."]],"us":[["programme","program"],["Mum","Mom"],["favourite","favorite"],["practises","practices"],["brilliant","great / wonderful"],["for ages","for a long time"],["We've got a picnic blanket.","We have a picnic blanket."]],"copy":["orchestra","treat","cymbals","piece","shining","burst","pack up"],"rwords":["orchestra","treat","cymbals","piece","shining","burst","pack up"],"retell":["park","orchestra","picnic","trumpets and drums","fireworks","go home"],"rule":{"title":"Past simple: was / were, had, and regular verbs","lines":["be → was / were:  I / he / she / it WAS · we / you / they WERE   (Everyone was great. The friends were there.)","have → had:  We had a concert.","Regular verbs + -ed: play → played · clap → clapped · cheer → cheered · tidy → tidied","Past time words: yesterday · last night · last week · two weeks ago. They go at the beginning or at the end: We had a concert last week. / Last week, we had a concert.","No: wasn't · weren't · didn't have · didn't + verb (I didn't play the guitar)."],"signal":"yesterday · last night · last week · two weeks ago → the verb is in the past.","ru":"In Russian the past ends in -л (играл). In English regular verbs end in -ed. Be careful: was / were and had are different forms.","oops":["We have a concert yesterday. → We had a concert yesterday.","They was at the concert. → They were at the concert.","I play the drums last week. → I played the drums last week.","She didn't played. → She didn't play."]},"hasBig":true,"big":[["c","Look at the picture: they ___ the drums now.",["played","are playing"],1,"now → present continuous"],["c","They ___ the drums every Saturday.",["play","are playing"],0,"every Saturday → present simple"],["c","They ___ the drums last night.",["play","played"],1,"last night → past"],["c","Which word has a long o sound?",["boat","room","bike"],0,"boat = long o"],["c","Which word has a long u sound?",["light","blue","bone"],1,"blue = long u"],["c","Which word has a long i sound?",["cry","flute","boat"],0,"cry = long i"],["c","clap → ___",["claping","clapping"],1,"one short vowel + one consonant → double the consonant"],["c","play → ___",["plaing","playing"],1,"play ends in y → just add -ing"],["r","Ask about a girl: play the piano?","Can she play the piano? Yes, she can. / No, she can't."],["r","Ask about a girl: like pop music?","Does she like pop music? Yes, she does. / No, she doesn't."],["r","Say what you did last weekend.","Last weekend I played soccer."],["r","Ask a friend about an instrument.","Can you play an instrument?"],["p","g-k-fireworks","What can you see in the sky?","I can see fireworks."],["p","g-k-orchestra","Who is playing?","An orchestra is playing."]],"cb":[[17,"Phonics and spelling"],[18,"Skills time: reading"],[19,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 17–19 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 17): long i (light, cry, bike), long o (boat, blow, bone), long u (room, blue, flute)","Reading words (p. 18): read the English and the Russian, say and repeat","Reading (p. 18): The Concert (a poem): listen, read aloud in pairs, answer the questions","Retell with these words: park, orchestra, picnic, trumpets and drums, fireworks, go home","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 19): Listening: who plays what, who wants to be a famous musician. Ask and answer about Fiona, Susan, Pam and Liz: Can she play the piano? Does she like pop music? Then about you.","Writing preparation (p. 19): The double consonant rule: stop → stopping, clap → clapping, but play → playing, open → opening. The writing task is about describing a picture. The writing task is homework.","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Unit 3A · The dinosaur museum","kd":{"kind":"A","label":"Unit 3A · The dinosaur museum","goal":"Museum and dinosaur words. Past simple: irregular verbs, negatives (didn't go) and questions (Did you go? What did you see?).","tr":[["Сегодня мы не ходили в школу.","We didn't go to school today."],["Мы ходили в музей динозавров.","We went to the dinosaur museum."],["Я купил модель динозавра.","I bought a dinosaur model."],["Мы видели скелеты и кости.","We saw skeletons and bones."],["Мы узнали, как жили динозавры.","We learned how dinosaurs lived."],["Вдруг динозавр зарычал.","Suddenly, a dinosaur roared."],["Мы все закричали.","We all screamed."],["Ты ходил в музей? — Да, ходил.","Did you go to a museum? — Yes, I did."],["Что ты там видел?","What did you see there?"],["Она не купила открытку. Она купила модель.","She didn't buy a postcard. She bought a model."]],"ch":[["В какой музей вы ходили? — Мы ходили в музей динозавров.","Which museum did you go to? — We went to the dinosaur museum."],["Мы не ели бутерброды в музее, потому что там нельзя есть.","We didn't eat our sandwiches in the museum because you can't eat there."]],"us":[["Mum","Mom"],["learnt","learned"],["brilliant fun","great fun"],["metres","meters"],["centimetres","centimeters"],["colour","color"],["litter","trash"]],"copy":["dinosaur","museum","model","skeleton","scary","scream","roar","alive","dead","robot","bone","tail","teeth","huge","trip","badge"],"rwords":[],"retell":[],"rule":{"title":"Past simple: irregular verbs, negatives and questions","lines":["Irregular verbs change: go → went · see → saw · buy → bought · eat → ate · make → made · hear → heard · think → thought · wear → wore · write → wrote · learn → learned","No: didn't + the BASE verb: We went to the museum. We didn't go to school. (not 'didn't went')","Question: Did + subject + the BASE verb? Did they go? Yes, they did. / No, they didn't.","Wh- questions: Where did you go? What did you see? Who did you see? Which museum did you go to?"],"signal":"yesterday · last week · two years ago + went / saw / bought … → past simple. In questions and negatives the verb goes back to the base form (go, see, buy).","ru":"In Russian we say «Ты ходил?» with the past form of the verb. In English the past is shown ONCE: in did. Did you go? (not 'Did you went?').","oops":["We didn't went to school. → We didn't go to school.","Did you saw the skeleton? → Did you see the skeleton?","I buyed a model. → I bought a model.","She goed to the zoo. → She went to the zoo."]},"hasBig":true,"big":[["c","We ___ to the museum yesterday.",["go","went"],1,"yesterday → went"],["c","I ___ a postcard. (not buy)",["didn't buy","didn't bought"],0,"didn't + base verb"],["c","___ you see the skeleton?",["Did","Do"],0,"past question → Did"],["c","Did she ___ a model?",["bought","buy"],1,"after Did → base verb"],["c","Yes, they ___.",["did","went"],0,"short answer → did"],["c","What did you ___?",["saw","see"],1,"after did → see"],["r","Find the mistake: We didn't went to school.","We didn't go to school."],["r","Find the mistake: Did you saw it?","Did you see it?"],["r","Find the mistake: I buyed a badge.","I bought a badge."],["r","Past of: eat, make, write, wear","ate, made, wrote, wore"],["r","Past of: see, hear, think, learn","saw, heard, thought, learned"],["r","Put the words in order: go / you / Where / did","Where did you go?"],["p","dinosaur","What is it?","It's a dinosaur."],["p","g-k-skeleton","What is it?","It's a skeleton."],["p","g-k-robot","What is it?","It's a robot."],["p","g-museum","Where did we go?","We went to the museum."]],"cb":[[20,"Words and story"],[21,"Grammar"],[22,"Grammar and song"]],"wb":"Workbook pp. 20–22 and Grammar Time p. 125","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 20): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 20): listen, read in roles, act it out","Grammar (p. 21): Past simple: irregular verbs, negatives and questions. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 22): Write notes about you and ask a friend: Where did you go on Saturday? What did you see? What did you eat? Did you buy anything?. Song: My school trip","Grammar Time (Workbook p. 125): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":3,"subtopic":"Unit 3B · The dinosaur museum","kd":{"kind":"B","label":"Unit 3B · The dinosaur museum","goal":"f and ph spellings. Read Dinosaur data. Talk about a school trip. Exclamation marks.","tr":[["Что ты знаешь о динозаврах?","What do you know about dinosaurs?"],["Динозавры жили на Земле миллионы лет.","Dinosaurs lived on Earth for millions of years."],["Учёные изучают кости динозавров.","Scientists study dinosaur bones."],["Было более семисот разных видов динозавров.","There were more than 700 different types of dinosaur."],["Некоторые динозавры ели растения, а другие ели мясо.","Some dinosaurs ate plants and others ate meat."],["Никто не знает, какого они были цвета.","No one knows what color they were."],["Динозавры исчезли 65 миллионов лет назад.","Dinosaurs disappeared 65 million years ago."],["Большой астероид упал на Землю.","A large asteroid fell to Earth."],["Стало очень холодно, и еды не было.","It became very cold and there was no food."],["Тираннозавр был больше, чем дом.","The T-Rex was bigger than a house."]],"ch":[["Скелеты тираннозавра можно увидеть в некоторых музеях.","You can see T-Rex skeletons in some museums."],["Учёные думают, что динозавры исчезли, потому что стало слишком холодно.","Scientists think the dinosaurs disappeared because it became too cold."]],"us":[["Mum","Mom"],["learnt","learned"],["brilliant fun","great fun"],["metres","meters"],["centimetres","centimeters"],["colour","color"],["litter","trash"]],"copy":["Earth","scientist","pattern","skin","disappear","rock","asteroid","fall (fell)","poor","smell","shout","angry","pay","coin","crowd","judge","shake","fair"],"rwords":["Earth","scientist","pattern","skin","disappear","rock","asteroid","fall (fell)"],"retell":["asteroid","fall","colder","no food","disappear","T-Rex"],"rule":{"title":"Past simple: irregular verbs, negatives and questions","lines":["Irregular verbs change: go → went · see → saw · buy → bought · eat → ate · make → made · hear → heard · think → thought · wear → wore · write → wrote · learn → learned","No: didn't + the BASE verb: We went to the museum. We didn't go to school. (not 'didn't went')","Question: Did + subject + the BASE verb? Did they go? Yes, they did. / No, they didn't.","Wh- questions: Where did you go? What did you see? Who did you see? Which museum did you go to?"],"signal":"yesterday · last week · two years ago + went / saw / bought … → past simple. In questions and negatives the verb goes back to the base form (go, see, buy).","ru":"In Russian we say «Ты ходил?» with the past form of the verb. In English the past is shown ONCE: in did. Did you go? (not 'Did you went?').","oops":["We didn't went to school. → We didn't go to school.","Did you saw the skeleton? → Did you see the skeleton?","I buyed a model. → I bought a model.","She goed to the zoo. → She went to the zoo."]},"hasBig":true,"big":[["c","Which word has the sound f?",["phone","scarf","nephew"],1,"scarf = f; phone and nephew have ph"],["c","al___abet",["f","ph"],1,"alphabet = ph"],["c","___lamingo",["f","ph"],0,"flamingo = f"],["c","Dinosaurs ___ 65 million years ago.",["disappear","disappeared"],1,"ago → past"],["c","A large rock ___ to Earth.",["fall","fell"],1,"fall → fell"],["c","Scientists ___ dinosaur bones every day.",["study","studied"],0,"every day → present"],["c","What is an asteroid?",["a large rock from space","a big skeleton"],0,"asteroid = a large rock from space"],["r","Why did the dinosaurs disappear?","A large asteroid fell and the Earth became very cold. There was no food."],["r","How long was the T-Rex?","It was 14 meters long."],["r","Ask a friend about a trip: where / go","Where did you go?"],["r","Ask about a trip: see / what","What did you see?"],["r","Find the mistake: The dinosaur move!","The dinosaur moved!"],["r","Say one thing you did on a school trip.","We went to a museum. / We saw a skeleton."]],"cb":[[23,"Phonics and spelling"],[24,"Skills time: reading"],[25,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 23–25 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 23): f (flamingo, scarf, feet) and ph (phone, nephew, alphabet)","Reading words (p. 24): read the English and the Russian, say and repeat","Reading (p. 24): Dinosaur data (a non-fiction text): listen, read aloud in pairs, answer the questions","Retell with these words: asteroid, fall, colder, no food, disappear, T-Rex","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 25): Listening: favorite things on a school trip (a museum, a zoo, a farm, the beach). Ask and answer about the children: Where did Jane go? What did she see? What did she like?","Writing preparation (p. 25): Exclamation marks (!) show strong feelings or an instruction: The dinosaur moved! Don't touch the bones! The writing task is a webpage about my school trip. The writing task is homework.","Story · The Smell and the Sound: look at the picture and guess; teach the new words (the Russian is in the vocabulary file); read aloud in turns; tell what happens in 5 sentences with the key words","Story: the kids close the book and retell it to a partner","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"],"story":[{"n":1,"title":"The Smell and the Sound","pic":"st5-01","paras":["In a small town, there lived a poor man. His name was Karim. He had no money, and he had very little food.","Every morning, Karim walked to work past a bread shop. The window of the shop was always open. Warm air came out of it, and with the warm air came the smell of fresh bread.","Karim could not buy the bread. So he stopped by the window for one minute. He closed his eyes and smelled the warm air. Then he ate his own dry piece of old bread and walked on. The smell made his old bread taste much better.","He did this every day for a month.","One morning, the baker came out and saw him. “Stop!” the baker shouted. “You are stealing from me!”","Karim was surprised. “I am not stealing,” he said. “I never touch your bread.”","“But you take the smell of my bread!” the baker said. “The smell is mine. I make it every morning. You must pay for it.”","“Nobody pays for a smell,” Karim said. “That is not fair.”","The baker was very angry. “We are going to the judge,” he said. “He will tell you that I am right.”","A crowd of people followed them to the judge’s house. Everybody wanted to hear this strange story.","The judge listened to the baker. Then he listened to Karim. He thought for a long moment. Then he asked, “Karim, do you have any money at all?”","Karim put his hand in his pocket and took out three small coins. It was everything he had.","The judge took the coins, closed his hand and shook it. The coins made a bright, happy sound. The room went quiet, and everybody listened.","“Baker,” the judge said, “can you hear that?”","“Yes,” the baker said. “That is the sound of money.”","“Good,” said the judge. He opened his hand and gave the three coins back to Karim. “This man has smelled your bread. You have heard his money. Now he has paid you.”","The crowd started to laugh. The baker’s face went red, and he walked home with nothing.","And Karim? He still stops by that window every morning."],"words":[["poor","puər","бедный","A poor person has very little money."],["smell","smel","запах; нюхать","A smell is something that you notice with your nose."],["shout","ʃaʊt","кричать","To shout is to say something in a very loud voice."],["angry","ˈæŋgri","сердитый","When you are angry, you feel bad and you want to shout."],["pay","peɪ","платить","To pay is to give money for something."],["coin","kɔɪn","монета","A coin is a small round piece of metal money."],["crowd","kraʊd","толпа","A crowd is a big group of people in one place."],["judge","dʒʌdʒ","судья","A judge is a person who decides who is right and who is wrong."],["shake","ʃeɪk","трясти","To shake something is to move it quickly up and down."],["fair","feə","справедливый","Something fair treats every person in the right way."]],"phrases":[],"retell":["poor","smell","shout","angry","pay","coin","crowd"]}]}}],"goal":"Unit 2B · Unit 3A · Unit 3B"},{"n":3,"title":"Week 3","icon":"Smartphone","lessons":[{"n":1,"subtopic":"Review 1 · Units 1–3","kd":{"kind":"review","label":"Review 1 · Units 1–3","goal":"No new topic: everything from Units 1–3. Mixed grammar practice on the big screen and Fluency Time.","tr":[["Мы обычно завтракаем в семь часов.","We usually have breakfast at seven o'clock."],["Сейчас она ест суп.","She's eating soup now."],["Можно мне сэндвич без лука?","Can I have a sandwich without onions?"],["Можно нам счёт, пожалуйста?","Can we have the bill, please?"],["У нас был концерт на прошлой неделе.","We had a concert last week."],["Все друзья были на концерте.","All our friends were at the concert."],["Вчера мы ходили в музей.","We went to the museum yesterday."],["Что ты там видел?","What did you see there?"],["Я не покупал открытку.","I didn't buy a postcard."],["Динозавры исчезли давно.","Dinosaurs disappeared a long time ago."]],"ch":[["Обычно мы едим дома, но сегодня мы ужинаем в ресторане, потому что вчера у нас был концерт.","We usually eat at home, but today we're having dinner in a restaurant because we had a concert yesterday."],["Вчера мы ходили в музей, где видели скелет динозавра, и все кричали.","Yesterday we went to a museum, where we saw a dinosaur skeleton, and everybody screamed."]],"us":[],"copy":[],"rwords":[],"retell":[],"rule":null,"hasBig":true,"big":[["c","My mom ___ coffee every morning.",["Always (present simple)","Now (present continuous)","Finished (past simple)"],0,"every morning → present simple"],["c","Look! The waiter ___ the menu.",["Always (present simple)","Now (present continuous)","Finished (past simple)"],1,"Look! → now"],["c","We ___ a concert last week.",["Always (present simple)","Now (present continuous)","Finished (past simple)"],2,"last week → past"],["c","They ___ to the museum yesterday.",["Always (present simple)","Now (present continuous)","Finished (past simple)"],2,"yesterday → past"],["c","I never ___ soup for breakfast.",["Always (present simple)","Now (present continuous)","Finished (past simple)"],0,"never → present simple"],["c","She ___ her homework at the moment.",["Always (present simple)","Now (present continuous)","Finished (past simple)"],1,"at the moment → now"],["c","I ___ the dinosaur skeleton two weeks ago.",["Always (present simple)","Now (present continuous)","Finished (past simple)"],2,"two weeks ago → past"],["r","Find the mistake: We didn't went to school.","We didn't go to school."],["r","Find the mistake: Did you saw the robot?","Did you see the robot?"],["r","Find the mistake: He always is hungry.","He is always hungry."],["r","Ask a waiter: some more juice","Can I have some more juice, please?"],["r","Say: sandwich / without onions","I'd like this sandwich without onions, please."]],"cb":[[26,"Fluency Time: Eating out"],[27,"Project"],[28,"Review 1"],[29,"Review 1"]],"wb":"Workbook pp. 26–27 and 28–29","steps":["Warm-up: the 3 earlier sentences from the last translation check","Mini test (file): 12 questions on Units 1–3","Speaking in pairs: the speaking questions (in the answers file)","Fluency Time (p. 26): Eating out. I'd like this sandwich with fries, please. / Can I have this salad without onions? / Can I have some more juice, please? / Can we have the bill, please?","Project: a café menu (or for homework)","Big screen: grammar practice (which rule is it?)","Review pages (pp. 28–29) together","Check the test; each kid fixes three mistakes","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Reading 1 · Fossils","kd":{"kind":"reading","label":"Reading 1 · Fossils","goal":"Read, learn the key words, and retell: What are fossils? · Girl's amazing fossil discovery.","tr":[["Окаменелости — это формы в камнях.","Fossils are shapes in rocks."],["Некоторым окаменелостям пятьсот миллионов лет.","Some fossils are 500 million years old."],["Окаменелости рассказывают нам о прошлом.","Fossils tell us about the past."],["Их можно найти в горах и в пустынях.","You can find them on mountains and in deserts."],["Окаменелости можно найти на пляже.","You can find fossils on a beach."],["В 2011 году учёные нашли скелеты китов в пустыне.","In 2011, scientists found whale skeletons in the desert."],["Эти окаменелости очень большие.","These fossils are very big."],["Дейзи гуляла по пляжу со своей семьёй.","Daisy walked on a beach with her family."],["Она увидела чёрные кости в песке.","She saw black bones in the sand."],["Это был летающий динозавр.","It was a flying dinosaur."]],"ch":[["Дейзи нашла окаменелость, когда ей было пять лет, а теперь ей десять.","Daisy found a fossil when she was five, and now she's ten."],["Учёные изучали её окаменелость пять лет, а потом назвали динозавра её именем.","Scientists studied her fossil for five years, and then they named the dinosaur after her."]],"us":[],"copy":["fossil","footprint","nest","geologist","discover","whale","desert","sand","proud","ground"],"rwords":["fossil","footprint","nest","geologist","discover","whale","desert","sand","proud","ground"],"retell":["fossil","ten thousand years old","beach","Daisy","black bones","flying dinosaur","museum"],"rule":null,"hasBig":true,"big":[["r","What is a fossil?","A fossil is a shape in a rock of an animal or plant that lived a long time ago."],["r","How old is a fossil? (at least)","At least ten thousand years old."],["r","Where can you find fossils?","On mountains, in deserts, in seas, on beaches, under the ground."],["r","What did scientists find in the desert in Chile?","They found the skeletons of 20 whales."],["r","How old was Daisy when she found the fossil?","She was five."],["r","What did Daisy find?","She found the bones of a flying dinosaur."],["r","How long did scientists study the fossil?","For five years."],["r","Where is Daisy's dinosaur now?","In the Natural History Museum in London."],["r","What does Daisy want to be?","A geologist."],["r","Retell the text in 5 sentences (use the key words).","Fossils are ... Daisy found ... Scientists ..."]],"cb":[[30,"Fossils (1)"],[31,"Fossils (2)"]],"wb":"No Workbook pages. Homework: write 5 sentences in the copybook (the retell).","steps":["Warm-up: the 3 earlier sentences from the last translation check","Pre-teach the key words: read the English and the Russian from the vocabulary file","Look at the pictures and guess: What is the text about?","Listen and read the first text (twice: once to listen, once in pairs); answer the questions","The same for the second text","Retell with these words: fossil, ten thousand years old, beach, Daisy, black bones, flying dinosaur, museum","Big screen: comprehension questions","Translation check: 10 sentences + 2 challenge"]}},{"n":3,"subtopic":"Unit 4A · Whose jacket is this?","kd":{"kind":"A","label":"Unit 4A · Whose jacket is this?","goal":"Sports words. Possessive pronouns (mine, yours, his, hers, ours, theirs) and the question Whose ...? Adverbs: slowly, quietly, happily, carefully, well, fast.","tr":[["Давай играть в футбол!","Let's play soccer!"],["Мы поиграем в две команды.","We're going to have two teams."],["Чья это куртка?","Whose jacket is this?"],["Эта куртка моя.","This jacket is mine."],["Эти кроссовки твои?","Are these sneakers yours?"],["Этот рюкзак её.","This backpack is hers."],["Эти кубки наши.","These trophies are ours."],["Рюкзак — их.","The backpack is theirs."],["Мы выиграли! Это наш кубок.","We won! It's our trophy."],["Она бежала медленно, а он бежал быстро.","She ran slowly, but he ran fast."]],"ch":[["Моя куртка слишком большая, а её — слишком маленькая, поэтому мы поменялись.","My jacket is too big and hers is too small, so we swapped."],["Они играли очень хорошо и тихо радовались, потому что выиграли.","They played really well, and they cheered quietly because they won."]],"us":[["football","soccer"],["Let's play football!","Let's play soccer!"],["trainers","sneakers"],["rucksack","backpack"],["Mum","Mom"],["favourite","favorite"],["I've got yours.","I have yours."]],"copy":["team","jacket","sneakers","trophy","player","kick","score a goal","racket","backpack","win (won)","match","coach","lose (lost)","ball","stadium","careful"],"rwords":[],"retell":[],"rule":{"title":"Possessive pronouns, Whose, and adverbs","lines":["my → mine · your → yours · his → his · her → hers · our → ours · their → theirs.   It's my jacket. = The jacket is mine.","After my / your / his / her / our / their we write a noun. After mine / yours / hers / ours / theirs there is NO noun: Whose jacket is this? It's mine.","Whose + noun = Whose jacket is it? (question about the owner).","Adverbs tell us HOW we do something. Add -ly to the adjective: slow → slowly · quiet → quietly · happy → happily · careful → carefully.   Two are special: good → WELL · fast → FAST.  He ran slowly. They played well."],"signal":"Whose ...? → the answer is mine / yours / his / hers / ours / theirs, or a name + 's (It's Amy's).  The verb + how? → adverb (-ly, well, fast).","ru":"In Russian «чей?» changes (чья куртка?). In English it's always WHOSE. Also: mine / yours / hers stay alone; do not add the noun after them. «Он играл хорошо» → He played WELL (not 'good').","oops":["This is mine jacket. → This is my jacket. / This jacket is mine.","Whose are these trainers? They're her. → They're hers.","He played good. → He played well.","She ran quick. → She ran quickly. (but fast: He ran fast.)"]},"hasBig":true,"big":[["c","This jacket is ___. (it is my jacket)",["my","mine"],1,"no noun after it → mine"],["c","These are ___ trainers. (they belong to us)",["our","ours"],0,"noun after → our"],["c","The red backpack is ___. (it belongs to her)",["her","hers"],1,"no noun → hers"],["c","Is this pen ___? (your)",["your","yours"],1,"no noun → yours"],["c","___ jacket is this?",["Who","Whose"],1,"owner → Whose"],["c","The trophy is ___. (they won)",["their","theirs"],1,"no noun → theirs"],["r","Find the mistake: This is mine ball.","This is my ball. / This ball is mine."],["r","Find the mistake: The trainers are her.","The sneakers are hers."],["c","He ran ___.",["slow","slowly"],1,"how? → slowly"],["c","She sang ___. (quiet)",["quiet","quietly"],1,"how? → quietly"],["c","They played ___. (good)",["good","well"],1,"good → well"],["r","Find the mistake: He played good.","He played well."],["r","Say about a boy and a girl: ran / fast / slowly","He ran fast, but she ran slowly."],["p","g-jacket","Whose jacket is this? (it's mine)","It's mine. It's my jacket."],["p","g-k-sneakers","Whose sneakers are these? (they're hers)","They're hers. They're her sneakers."],["p","trophy","Whose trophy is this? (it's ours)","It's ours. It's our trophy."],["p","g-k-racket","What is it?","It's a racket."]],"cb":[[32,"Words and story"],[33,"Grammar"],[34,"Grammar and song"]],"wb":"Workbook pp. 30–32 and Grammar Time p. 125","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 32): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 32): listen, read in roles, act it out","Grammar (p. 33): Possessive pronouns, Whose, and adverbs. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 34): Ask and answer about the pictures: Who is running slowly? (Adam.) Who is singing quietly? Then write: Joe ran fast, but Adam ran slowly.. Song: At break time","Grammar Time (Workbook p. 125): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}}],"goal":"Review 1 · Reading 1 · Unit 4A"},{"n":4,"title":"Week 4","icon":"Sun","lessons":[{"n":1,"subtopic":"Unit 4B · Whose jacket is this?","kd":{"kind":"B","label":"Unit 4B · Whose jacket is this?","goal":"ll endings and rr words. Read a history poster about tennis. Talk about favorite sports. It's or its.","tr":[["Что ты знаешь о теннисе?","What do you know about tennis?"],["Теннис — очень популярный вид спорта.","Tennis is a very popular sport."],["Болельщики смотрят Уимблдон каждый год.","Fans watch Wimbledon every year."],["Во Франции в двенадцатом веке играли в игру «поль».","In the 12th century, people in France played a game called Paume."],["Они били по мячу кожаной перчаткой.","They hit the ball with a leather glove."],["Позже люди стали использовать ракетки.","Later, people started to use rackets."],["Король Генрих Восьмой построил теннисный корт во дворце.","King Henry VIII built a tennis court at his palace."],["В тысяча восемьсот семьдесят третьем люди начали играть на улице.","In 1873, people started to play tennis outside."],["Первые теннисные мячи были деревянными!","The first tennis balls were wooden!"],["Венера и Серена Уильямс получили золотые медали.","Venus and Serena Williams won gold medals."]],"ch":[["Раньше женщины не играли на Уимблдоне, но в тысяча восемьсот восемьдесят четвёртом году они начали играть.","At first, women didn't play at Wimbledon, but in 1884 they started playing."],["Первым победителем был Спенсер Гор, а играли двадцать два человека.","The first winner was Spencer Gore, and 22 players played."]],"us":[["football","soccer"],["Let's play football!","Let's play soccer!"],["trainers","sneakers"],["rucksack","backpack"],["Mum","Mom"],["favourite","favorite"],["I've got yours.","I have yours."]],"copy":["fans","medal","championship","leather","court","hit","rules","glove"],"rwords":["fans","medal","championship","leather","court","hit","rules","glove"],"retell":["France","glove","racket","Tenez","Henry VIII","lawn tennis","Wimbledon","Williams sisters"],"rule":{"title":"Possessive pronouns, Whose, and adverbs","lines":["my → mine · your → yours · his → his · her → hers · our → ours · their → theirs.   It's my jacket. = The jacket is mine.","After my / your / his / her / our / their we write a noun. After mine / yours / hers / ours / theirs there is NO noun: Whose jacket is this? It's mine.","Whose + noun = Whose jacket is it? (question about the owner).","Adverbs tell us HOW we do something. Add -ly to the adjective: slow → slowly · quiet → quietly · happy → happily · careful → carefully.   Two are special: good → WELL · fast → FAST.  He ran slowly. They played well."],"signal":"Whose ...? → the answer is mine / yours / his / hers / ours / theirs, or a name + 's (It's Amy's).  The verb + how? → adverb (-ly, well, fast).","ru":"In Russian «чей?» changes (чья куртка?). In English it's always WHOSE. Also: mine / yours / hers stay alone; do not add the noun after them. «Он играл хорошо» → He played WELL (not 'good').","oops":["This is mine jacket. → This is my jacket. / This jacket is mine.","Whose are these trainers? They're her. → They're hers.","He played good. → He played well.","She ran quick. → She ran quickly. (but fast: He ran fast.)"]},"hasBig":true,"big":[["c","Which word has the sound ll?",["bell","bed"],0,"bell, smell, shell end in -ll"],["c","mi___or",["r","rr"],1,"mirror, carrot, cherry have rr"],["c","Its or It's? ___ new. (it is)",["It's","Its"],0,"It's = it is"],["c","Its or It's? ___ name is Star. (the horse)",["It's","Its"],1,"belonging → its (no apostrophe)"],["c","People played \"Paume\" in ___.",["France","Turkey"],0,"in France"],["c","The first tennis balls were ___.",["wooden","metal"],0,"wooden"],["c","Where do you ___ judo?",["play","do","go"],1,"do + judo / gymnastics / karate"],["c","I ___ swimming on Saturdays.",["play","do","go"],2,"go + swimming / skiing / running"],["c","We ___ basketball.",["play","do","go"],0,"play + ball games"],["r","Say which sport you do: karate / gymnastics","I do karate. / I do gymnastics."],["r","Ask a friend about a favorite sport.","What do you like doing? / Where do you play ...?"],["r","Who won the first World Tennis Championship?","Spencer Gore."],["r","Why did people call the game \"tennis\"?","Because the players shouted the French word \"Tenez!\" at the start of each game."],["r","Retell the poster in 5 sentences.","Tennis started in France ... glove ... rackets ... Tenez ... Wimbledon ..."]],"cb":[[35,"Phonics and spelling"],[36,"Skills time: reading"],[37,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 33–35 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 35): ll endings (smell, bell, shell) and rr words (mirror, carrot, cherry)","Reading words (p. 36): read the English and the Russian, say and repeat","Reading (p. 36): A history poster: Tennis: listen, read aloud in pairs, answer the questions","Retell with these words: France, glove, racket, Tenez, Henry VIII, lawn tennis, Wimbledon, Williams sisters","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 37): Listening: circle the sports the children like. Ask and answer: What do you like doing? Where do you play / do / go ...? Say: I play soccer, I do judo, I go swimming.","Writing preparation (p. 37): It's (= it is / it has) and its (= belonging to it): It's new. Its name is Star. The writing task is instructions for a sport. The writing task is homework.","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Unit 5A · Go back to the roundabout","kd":{"kind":"A","label":"Unit 5A · Go back to the roundabout","goal":"Direction words. have to / had to (something is necessary). Giving directions. Why? Because ...","tr":[["Мы заблудились.","We're lost."],["Мы должны вернуться к круговому перекрёстку.","We have to go back to the roundabout."],["Поверни налево у светофора.","Turn left at the traffic light."],["Иди прямо.","Go straight on."],["Нам надо поторопиться.","We have to hurry."],["Ей пришлось вернуться.","She had to go back."],["Почему мы на заправке? — Потому что мы заблудились.","Why are we at the gas station? — Because we're lost."],["Почему вы опоздали? — Потому что мы не прочитали карту.","Why were you late? — Because we didn't read the map."],["Театр рядом с вокзалом.","The theater is next to the train station."],["Парк за мостом.","The park is over the bridge."]],"ch":[["Нам пришлось вернуться, потому что мы заблудились, и теперь мы опоздаем.","We had to go back because we got lost, and now we're going to be late."],["Почему светофор красный? — Потому что мы должны ждать.","Why is the traffic light red? — Because we have to wait."]],"us":[["petrol station","gas station"],["theatre","theater"],["Mum","Mom"],["go straight on","go straight (on)"],["roundabout","traffic circle (in the USA); we use the book's word"],["We've got lost.","We got lost."]],"copy":["read a map","turn left","go back","traffic light","hurry","roundabout","get lost","turn right","go straight","gas station","bridge","corner","map","next to","in front of","behind"],"rwords":[],"retell":[],"rule":{"title":"have to / had to · giving directions · why / because","lines":["have to = it is necessary (we must): We have to hurry. He has to go back. Past: had to — We got lost, so we had to go with Uncle Tom.","No: don't have to (it is not necessary) · Question: Do we have to hurry? Did they have to wait?","Directions (imperatives, no 'you'): Turn left. Turn right. Go straight on at the roundabout. Go over the bridge. The park is next to the bus station.","WHY asks the reason; BECAUSE gives the reason: Why are we lost? Because we didn't read the map carefully."],"signal":"It is necessary → have to / has to. It was necessary (yesterday, last week) → had to. Why? → Because ...","ru":"In Russian «надо / нужно» does not change with the person. In English: I / you / we / they HAVE to, he / she / it HAS to, in the past HAD to for everybody.","oops":["He have to hurry. → He has to hurry.","We had to hurried. → We had to hurry.","Why are we late? Why we got lost. → Because we got lost.","Why you are lost? → Why are you lost?"]},"hasBig":true,"big":[["c","We ___ hurry. We are late!",["have to","has to"],0,"we → have to"],["c","She ___ go back. (now)",["have to","has to"],1,"she → has to"],["c","Yesterday I ___ wait for the bus.",["have to","had to"],1,"yesterday → had to"],["c","They got lost, so they ___ go back.",["have to","had to"],1,"past → had to"],["c","___ are we lost?",["Why","Because"],0,"question → Why"],["c","We are lost ___ we did not read the map.",["why","because"],1,"reason → because"],["r","Find the mistake: He have to go straight on.","He has to go straight on."],["r","Find the mistake: We had to hurried.","We had to hurry."],["r","Find the mistake: Why you are late?","Why are you late?"],["r","Say: the traffic light is red / we / wait","The traffic light is red, so we have to wait."],["r","Give directions: left at the roundabout","Turn left at the roundabout."],["r","Give directions: straight on, over the bridge","Go straight on. Go over the bridge."],["p","trafficlight","Where do you turn left?","Turn left at the traffic light."],["p","g-k-roundabout","Where do we have to go back to?","We have to go back to the roundabout."],["p","g-k-gas-station","Why are we here?","Because we're lost!"],["p","map","What is it?","It's a map."]],"cb":[[38,"Words and story"],[39,"Grammar"],[40,"Grammar and song"]],"wb":"Workbook pp. 36–38 and Grammar Time p. 126","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 38): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 38): listen, read in roles, act it out","Grammar (p. 39): have to / had to · giving directions · why / because. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 40): Tell why: Why were they late? Because they got lost. Why did they get lost? Because they couldn't read the map.. Song: Why are they lost?","Grammar Time (Workbook p. 126): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":3,"subtopic":"Unit 5B · Go back to the roundabout","kd":{"kind":"B","label":"Unit 5B · Go back to the roundabout","goal":"ck and c endings. Read about shadow puppet theater. Understand and give directions. Imperatives (instructions).","tr":[["Ты видел театр теней?","Have you seen a shadow puppet theater?"],["Театр теней начался в Китае тысячи лет назад.","Shadow puppet theaters first started in China thousands of years ago."],["Он до сих пор популярен во многих странах.","It's still popular in many parts of the world."],["Куклы рассказывают о важных событиях.","The puppets tell people about important events."],["Куклы обычно делают из кожи животных.","The puppets are usually made from animal skins."],["Верблюжья кожа — из Индонезии.","The camel skin puppets come from Indonesia."],["Чтобы двигать кукол, есть деревянные палки.","To move the puppets, there are wooden sticks."],["Яркий свет светит на кукол за экраном.","A bright light shines on the puppets behind a screen."],["Кукловод говорит всеми голосами.","The puppeteer does all the voices."],["Тени можно сделать руками на белой стене.","You can make shadows with your hands on a white wall."]],"ch":[["Тебе понадобятся белая стена и яркий свет.","You will need a white wall and a bright light."],["Подними большой палец, чтобы сделать ухо тигра, и двигай пальцами, чтобы рот тигра двигался.","Lift up your thumb to make the tiger's ear, and move your fingers to make the tiger's mouth move."]],"us":[["petrol station","gas station"],["theatre","theater"],["Mum","Mom"],["go straight on","go straight (on)"],["roundabout","traffic circle (in the USA); we use the book's word"],["We've got lost.","We got lost."]],"copy":["shadow","puppet","popular","event","stick","screen","voice","lift up","forest","afraid","hunt","roar","agree","turn","clever","hide","well","deep","reflection"],"rwords":["shadow","puppet","popular","event","stick","screen","voice","lift up"],"retell":["China","puppeteer","screen","shadows","light","hand shadows","tiger"],"rule":{"title":"have to / had to · giving directions · why / because","lines":["have to = it is necessary (we must): We have to hurry. He has to go back. Past: had to — We got lost, so we had to go with Uncle Tom.","No: don't have to (it is not necessary) · Question: Do we have to hurry? Did they have to wait?","Directions (imperatives, no 'you'): Turn left. Turn right. Go straight on at the roundabout. Go over the bridge. The park is next to the bus station.","WHY asks the reason; BECAUSE gives the reason: Why are we lost? Because we didn't read the map carefully."],"signal":"It is necessary → have to / has to. It was necessary (yesterday, last week) → had to. Why? → Because ...","ru":"In Russian «надо / нужно» does not change with the person. In English: I / you / we / they HAVE to, he / she / it HAS to, in the past HAD to for everybody.","oops":["He have to hurry. → He has to hurry.","We had to hurried. → We had to hurry.","Why are we late? Why we got lost. → Because we got lost.","Why you are lost? → Why are you lost?"]},"hasBig":true,"big":[["c","Which word ends in ck?",["duck","music"],0,"duck, clock, neck, rock"],["c","pla___",["stic","stick"],0,"plastic ends in c"],["c","pic___",["nic","nick"],0,"picnic ends in c"],["c","clo___",["c","ck"],1,"clock ends in ck"],["c","Which is an imperative (an instruction)?",["Take an empty bag.","He takes a bag."],0,"imperative = the verb at the start, no subject"],["c","Shadow puppet theaters first started in ___.",["China","Turkey"],0,"in China"],["c","The puppets are usually made from ___.",["plastic","animal skins"],1,"animal skins"],["r","Give directions to your classroom.","Go straight on. Go upstairs. It is the second door on the right."],["r","Ask: where is the school? (Where / is)","Where is the school?"],["r","What do you need for hand shadows?","A white wall and a bright light."],["r","Retell: the theater in 5 sentences.","It started in China ... puppets ... screen ... light ... the puppeteer ..."],["r","Put the words in order: the park / The / next to / bridge / is","The park is next to the bridge."]],"cb":[[41,"Phonics and spelling"],[42,"Skills time: reading"],[43,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 39–41 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 41): ck and c at the end of words (neck, duck, clock, rock / plastic, picnic, music, comic)","Reading words (p. 42): read the English and the Russian, say and repeat","Reading (p. 42): An informative webpage: Shadow puppet theater: listen, read aloud in pairs, answer the questions","Retell with these words: China, puppeteer, screen, shadows, light, hand shadows, tiger","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 43): Listening: point to the route and draw it to Leo's school. Speaking: give directions to a visitor at school: Go straight on. Go upstairs. It's the second door on the right.","Writing preparation (p. 43): Imperatives tell the reader to do something (Take an empty bag. Cut out ears.) and each new instruction starts on a new line. The writing task is an invitation. The writing task is homework.","Story · The Lion Who Met Another King: look at the picture and guess; teach the new words (the Russian is in the vocabulary file); read aloud in turns; tell what happens in 5 sentences with the key words","Story: the kids close the book and retell it to a partner","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"],"story":[{"n":2,"title":"The Lion Who Met Another King","pic":"st5-02","paras":["Long ago a lion lived in a big forest. Every animal there was afraid of him.","Every morning he came out of his cave and roared. The birds flew out of the trees. Then he went to hunt.","He did not hunt because he was hungry. He hunted because he could. Some days he caught five animals and ate only one.","One evening the animals met by the river. “In one year,” said the old bear, “this forest will be empty.” So they made a plan. In the morning they went to the lion together.","“King, stop hunting us,” said the bear. “Every day one animal will come to you. That animal will not run and will not hide. You will eat, and you will not touch the others.”","The lion thought about it. Hunting was hard work: running, waiting, lying in the wet grass. Food that walked to his door was easy food.","“And if one day nobody comes?” he asked. “Then you can eat all of us,” said the bear. The lion agreed, and both sides made a promise.","After that the animals took turns. The first day a big deer went. The second day a goat. The third day a young pig. Nobody ran, and nobody hid. Every animal knew its own day.","Then it was the turn of a rabbit. His name was Toshi. He was the smallest animal in the forest, and the most clever.","Toshi did not run away. He walked very slowly. He stopped at a little river and drank. For a moment he watched his own reflection in the water. Then he walked on.","The sun was high when he arrived. The lion was walking up and down, and his eyes were red. “You are late!” he roared. “And you are so small. Is this my dinner?”","“I am very sorry, King,” said Toshi. “Five rabbits left home this morning. On the road we met another lion. I have never seen an animal so big. He ate four of us. Then he said that he is the king of this forest now.”","The lion’s roar was so loud that the trees shook. “Where is he?” “He is hiding,” said Toshi. “Come with me.”","The rabbit took him to an old well in the forest. It was very deep. Far below there was cold black water. “He lives down there,” said Toshi quietly, “with my four brothers.”","The lion put his head over the well and looked down. A big lion looked straight up at him. He opened his mouth. The lion in the water opened his mouth too.","He roared. A roar came back out of the well — deep, angry, and just as loud as his own.","“Come out and fight me!” he shouted. The other king did not come out. He waited down there in the water. So the lion jumped.","There was one loud noise. Then the forest was very quiet. Toshi looked into the well for a long time. Then he went home and told everybody.","Nobody has seen that lion again. The old well is still there, and the animals still drink from it. And every young rabbit looks down into the water for a long, long time before he drinks."],"words":[["forest","ˈfɒrɪst","лес","A forest is a big place with very many trees."],["afraid","əˈfreɪd","испуганный, боящийся","When you are afraid, you think that something bad will happen."],["hunt","hʌnt","охотиться","To hunt is to follow an animal and catch it."],["roar","rɔː","рычать; рык","To roar is to make a very loud, deep sound, like a lion."],["agree","əˈgriː","соглашаться","To agree is to say yes to an idea."],["turn","tɜːn","очередь","Your turn is the time when you do something, after the other people."],["clever","ˈklevə","умный, хитрый","A clever person or animal thinks quickly and finds good ideas."],["hide","haɪd","прятаться, прятать","To hide is to go where other people cannot see you."],["well","wel","колодец","A well is a deep hole in the ground with water at the bottom."],["deep","diːp","глубокий","Something deep goes down a long way."],["reflection","rɪˈflekʃn","отражение","Your reflection is the picture of you that you see in water or in a mirror."]],"phrases":[["take turns","first one person, then the next one, then the next","The animals took turns and walked to the cave one by one."],["keep a promise","to do the thing that you said you would do","For many weeks the lion kept his promise."]],"retell":["forest","afraid","hunt","roar","agree","turn","clever"]}]}}],"goal":"Unit 4B · Unit 5A · Unit 5B"},{"n":5,"title":"Week 5","icon":"PawPrint","lessons":[{"n":1,"subtopic":"Unit 6A · The best bed!","kd":{"kind":"A","label":"Unit 6A · The best bed!","goal":"Describing words. Comparatives and superlatives of long adjectives (more comfortable than, the most expensive). Irregular: good, bad.","tr":[["Моя кровать сломалась.","My bed broke."],["Мы должны купить тебе новую.","We have to get you a new one."],["Эта металлическая кровать больше, чем твоя старая.","This metal bed is bigger than your old one."],["Моя старая кровать удобнее.","My old bed is more comfortable."],["Эта кровать мягче.","This bed is softer."],["Это самая дорогая кровать в магазине.","This is the most expensive bed in the store."],["Давай найдём что-нибудь менее дорогое.","Let's find something less expensive."],["Мы можем починить старую кровать.","We can repair the old bed."],["Моя старая кровать — самая лучшая.","My old bed is the best of all."],["Это дешевле, чем новая кровать.","It's cheaper than a new bed."]],"ch":[["Деревянная кровать менее дорогая, чем кровать-космический корабль, но более современная, чем металлическая.","The wooden bed is less expensive than the spaceship bed, but it's more modern than the metal one."],["Понедельник был плохим, вторник был хуже, а среда была самой плохой.","Monday was bad, Tuesday was worse, and Wednesday was the worst of all."]],"us":[["Mum","Mom"],["cheaper than a new bed","cheaper than a new bed (the same in US English)"],["£800","$800 (in the USA we count in dollars)"],["colour","color"],["In the shop","In the store"],["We've got a bed.","We have a bed."]],"copy":["break (broke)","repair","comfortable","hard","soft","expensive","cheap","wooden","metal","modern","beautiful","old","new","heavy","light","special"],"rwords":[],"retell":[],"rule":{"title":"Comparatives and superlatives: long adjectives and irregular","lines":["Long adjectives (2+ syllables): more / less + adjective + THAN:  My bed is more comfortable than this one. It's less expensive than a new bed.","Superlative: the most / the least + adjective:  This is the most expensive bed in the store. This is the least expensive one.","2-syllable adjectives ending in -y: -ier / -iest: happy → happier → the happiest.","Irregular: good → better → the best · bad → worse → the worst.   My old bed is better. My old bed is the best of all!","Short adjectives (Book 3): big → bigger than → the biggest."],"signal":"than → comparative (comparing 2).  the ... in the store / of all → superlative (3 or more).","ru":"In Russian one word can do it («удобнее»). In English long adjectives need MORE / LESS or THE MOST / THE LEAST. Never both: not 'more bigger'.","oops":["This bed is more good. → This bed is better.","It is the most cheapest bed. → It's the cheapest bed.","My bed is comfortabler. → My bed is more comfortable.","This is the worse bed. → This is the worst bed."]},"hasBig":true,"big":[["c","This bed is ___ than that one. (comfortable)",["more comfortable","comfortabler"],0,"long adjective → more ... than"],["c","The spaceship bed is the ___ bed in the store. (expensive)",["most expensive","expensivest"],0,"the most + long adjective"],["c","The wooden bed is ___ the spaceship bed. (less expensive)",["less expensive than","less expensive"],0,"than for comparing"],["c","My old bed is ___. (good)",["gooder","better"],1,"good → better"],["c","This one is the ___. (bad)",["baddest","worst"],1,"bad → the worst"],["c","Monday was bad, but Tuesday was ___.",["badder","worse"],1,"bad → worse"],["r","Find the mistake: This bed is more good.","This bed is better."],["r","Find the mistake: It is the most cheapest bed.","It's the cheapest bed."],["r","Find the mistake: My bed is comfortabler than yours.","My bed is more comfortable than yours."],["c","happy → ___ (comparative)",["more happy","happier"],1,"-y → -ier"],["r","Compare: a metal bed and a wooden bed (hard)","The metal bed is harder than the wooden bed."],["r","Say your best day.","Saturday was the best of all."],["v","g-k-wooden-bed","g-k-metal-bed","Compare: comfortable","The wooden bed is more comfortable than the metal bed."],["v","g-k-spaceship-bed","g-k-wooden-bed","Compare: expensive","The spaceship bed is more expensive than the wooden bed."],["v","g-k-spaceship-bed","g-k-metal-bed","Which is the most modern?","The spaceship bed is the most modern."]],"cb":[[44,"Words and story"],[45,"Grammar"],[46,"Grammar and song"]],"wb":"Workbook pp. 42–44 and Grammar Time p. 126","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 44): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 44): listen, read in roles, act it out","Grammar (p. 45): Comparatives and superlatives: long adjectives and irregular. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 46): Talk about the pictures: I think bike number one is the best. Bike number three is better than bike number two. Then write sentences.. Song: Saturday was the best of all!","Grammar Time (Workbook p. 126): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Unit 6B · The best bed!","kd":{"kind":"B","label":"Unit 6B · The best bed!","goal":"Soft c and soft g. Read a fable: The Ant and the Grasshopper. Order a story. Irregular plurals.","tr":[["Был прекрасный летний день.","It was a lovely summer day."],["Кузнечик играл на скрипке.","The grasshopper played his violin."],["Муравей нёс огромный кусок кукурузы.","The ant carried an enormous piece of corn."],["Кукуруза выглядит очень тяжёлой.","That corn looks really heavy."],["Это будет моя еда зимой, поэтому я должен готовиться сейчас.","This will be my food during winter, so I must prepare now."],["Зачем волноваться о зиме? Сейчас лето.","Why worry about winter? It's summer now."],["Скоро стало очень холодно, земля покрылась толстым снегом.","Soon the weather became very cold and the ground was covered with thick snow."],["Кузнечик пытался копать, но не нашёл еды.","The grasshopper tried to dig, but he couldn't find any food."],["Муравей был добрым и щедрым.","The ant was kind and generous."],["Тебе нельзя быть ленивым.","You mustn't be lazy."]],"ch":[["Муравей сказал: «В этот раз я тебе помогу, но в следующем году не буду».","The ant said, \"I will help you this time, but next year I will not help you.\""],["Мораль басни: всегда много работай и готовься к зиме.","The moral of the fable: always work hard and prepare for winter."]],"us":[["Mum","Mom"],["cheaper than a new bed","cheaper than a new bed (the same in US English)"],["£800","$800 (in the USA we count in dollars)"],["colour","color"],["In the shop","In the store"],["We've got a bed.","We have a bed."]],"copy":["enormous","prepare","worry","thick","dig","share","generous","lazy","traveller","stir","boil","taste","spoon","onion","lid","delicious","share","gather","magic"],"rwords":["enormous","prepare","worry","thick","dig","share","generous","lazy"],"retell":["summer","violin","corn","winter","snow","hungry","share","lazy","prepare"],"rule":{"title":"Comparatives and superlatives: long adjectives and irregular","lines":["Long adjectives (2+ syllables): more / less + adjective + THAN:  My bed is more comfortable than this one. It's less expensive than a new bed.","Superlative: the most / the least + adjective:  This is the most expensive bed in the store. This is the least expensive one.","2-syllable adjectives ending in -y: -ier / -iest: happy → happier → the happiest.","Irregular: good → better → the best · bad → worse → the worst.   My old bed is better. My old bed is the best of all!","Short adjectives (Book 3): big → bigger than → the biggest."],"signal":"than → comparative (comparing 2).  the ... in the store / of all → superlative (3 or more).","ru":"In Russian one word can do it («удобнее»). In English long adjectives need MORE / LESS or THE MOST / THE LEAST. Never both: not 'more bigger'.","oops":["This bed is more good. → This bed is better.","It is the most cheapest bed. → It's the cheapest bed.","My bed is comfortabler. → My bed is more comfortable.","This is the worse bed. → This is the worst bed."]},"hasBig":true,"big":[["c","Which word has the soft c (s)?",["city","cat"],0,"city = s"],["c","Which word has the soft g (j)?",["goal","giraffe"],1,"giraffe = j"],["c","ca___ (a house for a hamster)",["ge","je"],0,"cage"],["c","one foot, two ___",["foots","feet"],1,"irregular plural"],["c","one sheep, two ___",["sheep","sheeps"],0,"sheep stays the same"],["c","one person, two ___",["persons","people"],1,"people"],["c","The grasshopper didn't ___ for winter.",["prepare","prepared"],0,"didn't + base verb"],["c","The ant was ___ to the grasshopper.",["generous","lazy"],0,"generous = gave food"],["c","The grasshopper was ___.",["generous","lazy"],1,"lazy = did not work"],["r","What is the moral of the fable?","Always work hard and prepare for the future."],["r","Tell the story in 5 sentences (use: summer, corn, winter, hungry, share).","In summer the ant carried corn. The grasshopper played. In winter he was hungry. The ant shared. ..."],["r","One fish, two ...?","Two fish."]],"cb":[[47,"Phonics and spelling"],[48,"Skills time: reading"],[49,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 45–47 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 47): soft c = s (city, ice, dance, rice) and soft g = j (cage, page, giraffe, stage)","Reading words (p. 48): read the English and the Russian, say and repeat","Reading (p. 48): A fable: The Ant and the Grasshopper: listen, read aloud in pairs, answer the questions","Retell with these words: summer, violin, corn, winter, snow, hungry, share, lazy, prepare","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 49): Listening: put the pictures of a fable in order (The Boy Who Cried Wolf). Speaking: look at the pictures of a modern version and tell the story. Writing preparation: irregular plurals.","Writing preparation (p. 49): Plurals that stay the same (fish, sheep) and plurals that are different (foot → feet, tooth → teeth, person → people, woman → women). The writing task is to write a fable. The writing task is homework.","Story · The Stone That Fed a Village: look at the picture and guess; teach the new words (the Russian is in the vocabulary file); read aloud in turns; tell what happens in 5 sentences with the key words","Story: the kids close the book and retell it to a partner","Translation check: 10 sentences + 2 challenge"],"story":[{"n":3,"title":"The Stone That Fed a Village","pic":"st5-03","paras":["A traveller came into the village as the sun was going down. He had walked all day and his bag was empty. He knocked on the first door.","“I am hungry,” he said. “Please give me a little bread.”","“We have nothing,” the woman answered. “The winter was long.” Then she shut the door.","He knocked on ten more doors, and ten people said the same words, and not one of them told the truth. The traveller had a very good nose. Behind those doors he could smell onions, and meat, and warm bread.","He did not ask again. He walked down to the river and chose a small round stone. He washed it in the cold water, slowly and carefully, like something very important.","“A stone like this,” he said quietly, “is going to make dinner for a whole village.”","In the middle of the village he made a fire. He asked old Anvar for a big black pot. A pot is not food, so Anvar gave it with a smile. The traveller filled the pot with water, dropped the stone inside, and began to stir.","A boy came first. “What are you cooking?”","“Stone soup,” said the traveller. “Tomorrow this whole village will talk about it.”","The water boiled. A small crowd stood around the fire and watched. The traveller took a big wooden spoon, tasted the soup and closed his eyes.","“It is going to be good,” he said. “It will be very good. But a stone soup is always better with one onion.”","“I think I have an onion,” a woman said. She ran home and came back with three.","The traveller cut them in and tasted again. “Wonderful. A little salt will make it perfect.”","The salt arrived. Then a man whispered something to his wife, and two eggs arrived. Then some rice. Then a small piece of meat, from a family who had told the traveller, one hour before, that they had nothing at all.","Nobody wanted to be the one who gave nothing. One by one, the neighbours changed their minds.","The traveller put the lid on the pot. “Now we are going to wait,” he said. “In twenty minutes we will eat.”","They waited. The soup was delicious. The village shared it, and everybody gathered close to the fire, and somebody began to sing, and the children went to bed far too late.","“It is a magic stone,” the people said. The traveller only smiled.","In the morning he washed the stone again and put it in his bag. The boy was watching him.","“Will you tell me the secret?” the boy asked. “Is it really magic?”","The traveller put the stone into the boy’s hand. “It is not the stone,” he said. “But keep it. It works best in a village that says it has nothing.”","Then he walked away down the cold road."],"words":[["traveller","ˈtrævələ","путешественник, путник","A person who is going from one place to another place."],["stir","stɜː","мешать, размешивать","To move food or liquid around with a spoon."],["boil","bɔɪl","кипеть, варить","When water becomes very hot and makes bubbles."],["taste","teɪst","пробовать (на вкус)","To eat or drink a little, to find out how good something is."],["spoon","spuːn","ложка","You eat soup with it."],["onion","ˈʌnjən","лук (одна луковица)","A round vegetable with a very strong smell."],["lid","lɪd","крышка","The top part of a pot or a box, which you can take off."],["delicious","dɪˈlɪʃəs","очень вкусный","Very, very good to eat."],["share","ʃeə","делиться","To give a part of something to other people."],["gather","ˈɡæðə","собираться (вместе)","To come together in one place."],["magic","ˈmædʒɪk","волшебство; волшебный","A special power that can do impossible things."]],"phrases":[["tell the truth","говорить правду","Not one of the ten people told the truth."],["change your mind","передумать","She wanted to say no, but then she changed her mind."]],"retell":["traveller","stir","boil","taste","spoon","onion","lid"]}]}},{"n":3,"subtopic":"Review 2 · Units 4–6","kd":{"kind":"review","label":"Review 2 · Units 4–6","goal":"No new topic: everything from Units 4–6. Mixed grammar practice on the big screen and Fluency Time.","tr":[["Чья это куртка? — Это моя.","Whose jacket is this? — It's mine."],["Эти кроссовки её.","These sneakers are hers."],["Он играл очень хорошо.","He played really well."],["Поверни налево у светофора.","Turn left at the traffic light."],["Нам надо поторопиться.","We have to hurry."],["Почему вы опоздали? — Потому что мы заблудились.","Why were you late? — Because we got lost."],["Эта кровать мягче, чем та.","This bed is softer than that one."],["Это самая дорогая кровать в магазине.","It's the most expensive bed in the store."],["Моя старая кровать — самая лучшая.","My old bed is the best of all."],["Можно поговорить с Сарой?","Can I speak to Sara, please?"]],"ch":[["Мой рюкзак тяжелее, чем твой, но твой менее удобный, поэтому я хочу поменяться.","My backpack is heavier than yours, but yours is less comfortable, so I want to swap."],["Нам пришлось вернуться к круговому перекрёстку, потому что мы не прочитали карту внимательно.","We had to go back to the roundabout because we didn't read the map carefully."]],"us":[],"copy":[],"rwords":[],"retell":[],"rule":null,"hasBig":true,"big":[["c","The red bag is ___. (it belongs to us)",["our","ours"],1,"no noun → ours"],["c","She sang ___.",["quiet","quietly"],1,"how → quietly"],["c","We ___ go back. We are lost.",["have to","has to"],0,"we → have to"],["c","Yesterday we ___ walk home.",["have to","had to"],1,"yesterday → had to"],["c","This is ___ bed in the store. (expensive)",["more expensive","the most expensive"],1,"in the store → superlative"],["c","My old bed is ___ than this one. (good)",["gooder","better"],1,"good → better"],["r","Find the mistake: This is mine bag.","This is my bag. / This bag is mine."],["r","Find the mistake: He played good.","He played well."],["r","Find the mistake: Why we are late?","Why are we late?"],["r","Find the mistake: It is the most cheapest one.","It's the cheapest one."],["r","Answer: Why are we lost?","Because we didn't read the map."],["r","Phone: ask for Sara.","Can I speak to Sara, please?"]],"cb":[[50,"Fluency Time: Making phone calls"],[51,"Project"],[52,"Review 2"],[53,"Review 2"]],"wb":"Workbook pp. 48–49 and 50–51","steps":["Warm-up: the 3 earlier sentences from the last translation check","Mini test (file): 12 questions on Units 4–6","Speaking in pairs: the speaking questions (in the answers file)","Fluency Time (p. 50): Making phone calls. Hello. Can I speak to Sara, please? / Who's calling, please? / It's Anna here. / Hold on a minute, please. / Will isn't here at the moment. / Can you call again at seven o'clock?","Project: a telephone (or for homework)","Big screen: grammar practice (which rule is it?)","Review pages (pp. 52–53) together","Check the test; each kid fixes three mistakes","Translation check: 10 sentences + 2 challenge"]}}],"goal":"Unit 6A · Unit 6B · Review 2"},{"n":6,"title":"Week 6","icon":"Clock","lessons":[{"n":1,"subtopic":"Reading 2 · Sport","kd":{"kind":"reading","label":"Reading 2 · Sport","goal":"Read, learn the key words, and retell: American Football · The fastest man in the world.","tr":[["Американский футбол очень отличается от европейского.","American football is very different from European football."],["Это больше похоже на регби.","It's more like rugby."],["В каждой команде одиннадцать игроков.","There are eleven players in each team."],["Игроки носят шлемы, потому что игра опасная.","The players wear helmets because the game is dangerous."],["Самая важная игра называется Суперкубок.","The most important game is called the Super Bowl."],["Усэйн Болт родился на Ямайке.","Usain Bolt was born in Jamaica."],["В две тысячи восьмом году он выиграл три золотые медали.","In 2008, he won three gold medals."],["Он установил три мировых рекорда.","He broke three world records."],["Он выше большинства спортсменов, а ноги у него длиннее.","He's taller than most athletes, and his legs are longer."],["Его прозвали Молния Болт.","People call him Lightning Bolt."]],"ch":[["В девятнадцатом веке в Англии играли в футбол, а потом один игрок взял мяч в руки и побежал, и так появилось регби.","In the 19th century, people played football in England, and then one player picked up the ball and ran, so rugby started."],["Усэйн был амбициозным мальчиком, поэтому он тренировался и стал самым быстрым человеком в мире.","Usain was an ambitious boy, so he practiced and became the fastest man in the world."]],"us":[],"copy":["rugby","touchdown","helmet","dangerous","Olympic Games","gold medal","world record","athlete","ambitious","inspire"],"rwords":["rugby","touchdown","helmet","dangerous","Olympic Games","gold medal","world record","athlete","ambitious","inspire"],"retell":["19th century","rugby","eleven players","Super Bowl","Usain Bolt","Jamaica","gold medals","longer legs"],"rule":null,"hasBig":true,"big":[["r","What is the name of the biggest American football game?","The Super Bowl."],["r","How many players are there in each team?","Eleven."],["r","Why do the players wear helmets?","Because the game is more dangerous than rugby."],["r","Which two players does the text show?","Eli Manning and JJ Watt."],["r","Who is taller: JJ Watt (196 cm) or Eli Manning (193 cm)?","JJ Watt is taller than Eli Manning."],["r","Where was Usain Bolt born?","In Jamaica."],["r","How many gold medals did he win in 2008 and 2012?","Three in 2008 and three in 2012."],["r","Why is he so fast?","He is very tall and his legs are longer, so he takes fewer steps."],["r","Would you like to play American football? Why?","Yes, I would, because ... / No, I wouldn't, because ..."],["r","Retell the two texts in 5 sentences.","American football started ... Usain Bolt was born ..."]],"cb":[[54,"Sport (1)"],[55,"Sport (2)"]],"wb":"No Workbook pages. Homework: write 5 sentences in the copybook (the retell).","steps":["Warm-up: the 3 earlier sentences from the last translation check","Pre-teach the key words: read the English and the Russian from the vocabulary file","Look at the pictures and guess: What is the text about?","Listen and read the first text (twice: once to listen, once in pairs); answer the questions","The same for the second text","Retell with these words: 19th century, rugby, eleven players, Super Bowl, Usain Bolt, Jamaica, gold medals, longer legs","Big screen: comprehension questions","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Unit 7A · Will it really happen?","kd":{"kind":"A","label":"Unit 7A · Will it really happen?","goal":"Space words. The future with will / won't: statements, questions, short answers. Time words for the future: tomorrow, next week, in two weeks' time.","tr":[["В будущем люди будут путешествовать на супербыстрых самолётах.","In the future, people will travel in super-fast planes."],["Больше не будет долгих перелётов.","There won't be any more long plane journeys."],["Они вернутся в Австралию?","Will they go back to Australia?"],["Да, вернутся.","Yes, they will."],["Нет, не вернутся.","No, they won't."],["Они будут здесь ещё четыре месяца.","They'll be here for another four months."],["Люди полетят на Луну на каникулы?","Will people go to the moon for holidays?"],["Они не будут есть обычную еду.","They won't eat normal food."],["Завтра мы посмотрим на звёзды.","Tomorrow we'll look at the stars."],["Через две недели мы вернёмся на Землю.","In two weeks' time, we'll come back to Earth."]],"ch":[["Я думаю, что в будущем у нас будут роботы, но они не будут делать нашу домашнюю работу.","I think we will have robots in the future, but they won't do our homework."],["Космонавты полетят на ракете к далёкой планете, и это будет очень интересно.","The astronauts will fly in a rocket to a faraway planet, and it'll be really exciting."]],"us":[["Mum","Mom"],["aeroplane","airplane"],["holiday (two weeks' time)","vacation"],["on holiday","on vacation"],["programme","program"],["football","soccer"],["petrol","gas"]],"copy":["the future","travel","satellite","the moon","the sun","planets","rocket","astronaut","star","spaceship","space","Earth","robot","fly","maybe","amazing"],"rwords":[],"retell":[],"rule":{"title":"The future with will","lines":["Statement: will + the base verb. People will travel in super-fast planes. = They'll travel.   (I'll · you'll · he'll · she'll · it'll · we'll · they'll)","No: won't (= will not) + base verb: There won't be any more long plane journeys.","Question: Will + subject + base verb? Will they go back to Australia? Yes, they will. / No, they won't.","Time words for the future: tomorrow · soon · later · this evening · next week · on Monday · in two weeks' time · in a month's time. They go at the end (or at the start) of the sentence: We'll go on vacation in two weeks' time.","Use will for predictions (what I think will happen): I think robots will help us."],"signal":"tomorrow / next week / soon / in two weeks' time / in 100 years + I think ... → will + base verb.","ru":"In Russian the future is «буду + глагол» or one verb («поедем»). In English: WILL + the base verb. Not 'will goes', not 'will to go'.","oops":["They will goes to Mars. → They will go to Mars.","Will they to go? → Will they go?","He will not to come. → He won't come.","I think it will to rain. → I think it will rain."]},"hasBig":true,"big":[["c","Tomorrow we ___ the moon.",["visit","will visit"],1,"tomorrow → will + base verb"],["c","They ___ any more long journeys.",["won't have","won't to have"],0,"won't + base verb"],["c","___ people live on Mars?",["Will","Do"],0,"future question → Will"],["c","Will they go back? No, they ___.",["won't","don't"],0,"short answer → won't"],["c","Will it happen? Yes, it ___.",["will","does"],0,"short answer → will"],["c","I'll = ?",["I will","I would"],0,"I'll = I will"],["r","Find the mistake: They will goes to the moon.","They will go to the moon."],["r","Find the mistake: Will they to go to Mars?","Will they go to Mars?"],["r","Find the mistake: He won't to come.","He won't come."],["r","Say: next week / we / see / the stars","Next week we'll see the stars."],["r","Ask: robots / help us","Will robots help us?"],["r","Put the words in order: in / be home / We'll / two weeks' / time","We'll be home in two weeks' time."],["p","satellite","What is it?","It's a satellite."],["p","rocket","What is it?","It's a rocket."],["p","astronaut","What is it?","It's an astronaut."],["p","g-k-planets","What are they?","They're planets."],["p","g-k-spaceship","What will people travel in?","People will travel in spaceships."]],"cb":[[56,"Words and story"],[57,"Grammar"],[58,"Grammar and song"]],"wb":"Workbook pp. 52–54 and Grammar Time p. 127","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 56): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 56): listen, read in roles, act it out","Grammar (p. 57): The future with will. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 58): Look at the moon-trip calendar and ask: When will we look at the stars? (This evening.) Then write: On our trip to the moon, we will look at the stars this evening.. Song: A trip to the moon!","Grammar Time (Workbook p. 127): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":3,"subtopic":"Unit 7B · Will it really happen?","kd":{"kind":"B","label":"Unit 7B · Will it really happen?","goal":"au, aw and or spellings. Read a website forum: The Future. Say what life will be like in 100 years. Compound words.","tr":[["Как ты думаешь, каким будет будущее?","What do you think the future will be like?"],["Земли будет мало, поэтому будут большие города под водой.","There won't be much land, so there will be big cities underwater."],["Мы будем путешествовать на подводных лодках.","We'll travel in submarines."],["Некоторые дома будут под землёй.","Some houses will be underground."],["Загрязнение будет очень сильным.","Pollution will be very bad."],["Люди будут есть много вредной еды.","People will eat lots of junk food."],["Мир станет чище.","The world will be a cleaner place."],["Мы будем использовать энергию солнца.","We'll use energy from the sun."],["Компьютеры будут очень маленькими.","Computers will be very small."],["Мы будем управлять компьютерами голосом.","We'll use our voices to control computers."]],"ch":[["Я согласен с Робом, но Джим не согласен.","I agree with Rob, but Jim disagrees."],["Джасмин думает, что дети не будут ходить в школу, а будут учиться дома с виртуальной реальностью.","Jasmine thinks children won't go to school. They'll study at home with virtual reality."]],"us":[["Mum","Mom"],["aeroplane","airplane"],["holiday (two weeks' time)","vacation"],["on holiday","on vacation"],["programme","program"],["football","soccer"],["petrol","gas"]],"copy":["underwater","submarine","underground","control","energy","virtual reality","pills","power"],"rwords":["underwater","submarine","underground","control","energy","virtual reality","pills","power"],"retell":["underwater","submarine","junk food","energy","virtual reality","computers","robots"],"rule":{"title":"The future with will","lines":["Statement: will + the base verb. People will travel in super-fast planes. = They'll travel.   (I'll · you'll · he'll · she'll · it'll · we'll · they'll)","No: won't (= will not) + base verb: There won't be any more long plane journeys.","Question: Will + subject + base verb? Will they go back to Australia? Yes, they will. / No, they won't.","Time words for the future: tomorrow · soon · later · this evening · next week · on Monday · in two weeks' time · in a month's time. They go at the end (or at the start) of the sentence: We'll go on vacation in two weeks' time.","Use will for predictions (what I think will happen): I think robots will help us."],"signal":"tomorrow / next week / soon / in two weeks' time / in 100 years + I think ... → will + base verb.","ru":"In Russian the future is «буду + глагол» or one verb («поедем»). In English: WILL + the base verb. Not 'will goes', not 'will to go'.","oops":["They will goes to Mars. → They will go to Mars.","Will they to go? → Will they go?","He will not to come. → He won't come.","I think it will to rain. → I think it will rain."]},"hasBig":true,"big":[["c","Which word has the sound or?",["horse","sauce","paw"],0,"horse, sport, morning = or"],["c","ja___",["w","u"],0,"jigsaw ends in aw"],["c","a___tumn",["u","w"],0,"autumn = au (we say fall)"],["c","sun + flower = ___",["sunflower","sunfower"],0,"compound word"],["c","In the future, children ___ at home.",["study","will study"],1,"future → will study"],["c","Rob thinks there will be big cities ___.",["underwater","underground"],0,"cities underwater"],["c","Lara thinks people will eat lots of ___.",["junk food","fish"],0,"junk food and food pills"],["c","Jim thinks cars will use ___.",["energy from the sun","petrol"],0,"energy from the sun"],["c","Jasmine thinks she will use ___ to study.",["virtual reality","a book"],0,"virtual reality"],["r","What will school be like in 100 years?","I think we will study at home with virtual reality."],["r","Say what won't happen.","Robots won't do our homework."],["r","Retell the forum in 5 sentences.","Rob thinks ... Lara thinks ... Jim thinks ... Jasmine thinks ..."]],"cb":[[59,"Phonics and spelling"],[60,"Skills time: reading"],[61,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 55–57 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 59): au (sauce, August, autumn), aw (jigsaw, straw, paw), or (horse, sport, morning)","Reading words (p. 60): read the English and the Russian, say and repeat","Reading (p. 60): A website forum: The Future: listen, read aloud in pairs, answer the questions","Retell with these words: underwater, submarine, junk food, energy, virtual reality, computers, robots","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 61): Listening: circle the correct answers about life in the future. Speaking: What will life be like in 100 years' time? Talk about school, home, travel, robots, weather, food. I think we will ... I don't think robots will ...","Writing preparation (p. 61): Compound words (two words together make a new word): sun + flower = sunflower, pan + cake = pancake, house + work = homework, door + bell = doorbell. The writing task is to expand notes into a text. The writing task is homework.","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}}],"goal":"Reading 2 · Unit 7A · Unit 7B"},{"n":7,"title":"Week 7","icon":"Map","lessons":[{"n":1,"subtopic":"Unit 8A · How much time do we have?","kd":{"kind":"A","label":"Unit 8A · How much time do we have?","goal":"At the airport. How much / how many, lots of, some / any. American English: Do you have any ...? I don't have much ...","tr":[["Сколько у нас времени?","How much time do we have?"],["У нас ещё много времени.","We still have lots of time."],["У тебя много денег? — Нет, у меня только один фунт.","Do you have much money? — No, I only have one pound."],["Сколько у тебя карандашей?","How many pencils do you have?"],["У нас нет газет, но есть журналы.","We don't have any newspapers, but we have some magazines."],["У тебя есть мыло? — Нет, но у нас есть шампунь.","Do you have any soap? — No, but we have some shampoo."],["Сколько чемоданов едет в самолёте?","How many suitcases are going on the plane?"],["У неё немного багажа.","She doesn't have much luggage."],["Сколько пассажиров летит?","How many passengers are travelling?"],["Я купил подарок в магазине.","I bought a present in the store."]],"ch":[["У нас мало денег, поэтому мы сложим их вместе и купим одну хорошую вещь.","We don't have much money, so we'll put it together and buy one really nice thing."],["В аэропорту у нас было много времени, но не было ни одной газеты.","At the airport we had lots of time, but we didn't have any newspapers."]],"us":[["Have you got any soap?","Do you have any soap?"],["I haven't got much money.","I don't have much money."],["We've got lots of time.","We have lots of time."],["holiday","vacation"],["shop","store"],["aeroplane","airplane"],["postcode","zip code (in the USA)"],["pound","dollar"],["Mum","Mom"]],"copy":["money","passenger","arrivals","departures","luggage","passport","suitcase","magazine","newspaper","coin","airport","ticket","gate","pilot","flight","holiday (vacation)"],"rwords":[],"retell":[],"rule":{"title":"How much / how many · lots of · some / any","lines":["Countable (we can count: 1, 2, 3): pencils, suitcases, passengers, coins  →  How MANY pencils do you have? I don't have MANY pencils.","Uncountable (we cannot count): money, luggage, time, water, soap  →  How MUCH money do you have? I don't have MUCH money.","LOTS OF goes with both: We have lots of money. We have lots of pencils.","SOME in sentences with 'yes': We have some magazines.   ANY in questions and 'no' sentences: Do you have any newspapers? We don't have any newspapers.","American: Do you have ...? I don't have ... (the book says: Have you got ...? I haven't got ...)."],"signal":"Can you count it? yes → many (pencils) · no → much (money, time, luggage).  ?  or  not  → any.   Yes-sentence → some.","ru":"In Russian «сколько?» is one word. In English: how MANY (things you count) or how MUCH (things you do not count). Also «есть» = DO you have ...?","oops":["How much pencils do you have? → How many pencils do you have?","I don't have many money. → I don't have much money.","Do you have some soap? → Do you have any soap?","We don't have some magazines. → We don't have any magazines."]},"hasBig":true,"big":[["c","How ___ money do you have?",["many","much"],1,"money = uncountable → much"],["c","How ___ pencils do you have?",["many","much"],0,"pencils = countable → many"],["c","We have ___ of time.",["lots","many"],0,"lots of"],["c","Do you have ___ newspapers?",["some","any"],1,"question → any"],["c","We don't have ___ soap.",["some","any"],1,"not → any"],["c","But we have ___ shampoo.",["some","any"],0,"positive → some"],["r","Find the mistake: How much suitcases are there?","How many suitcases are there?"],["r","Find the mistake: I have not many money.","I don't have much money."],["r","Find the mistake: Do you have some passports?","Do you have any passports?"],["r","Ask about luggage (count or not?)","How much luggage do you have?"],["r","Ask about passengers","How many passengers are there?"],["r","Say: we / not / have / time","We don't have much time."],["p","g-passport","What is it?","It's a passport."],["p","g-suitcase","What is it?","It's a suitcase."],["p","g-k-newspaper","What is it?","It's a newspaper."],["p","g-k-coin","What is it?","It's a coin."],["p","g-k-magazine","What is it?","It's a magazine."]],"cb":[[62,"Words and story"],[63,"Grammar"],[64,"Grammar and song"]],"wb":"Workbook pp. 58–60 and Grammar Time p. 127","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 62): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 62): listen, read in roles, act it out","Grammar (p. 63): How much / how many · lots of · some / any. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 64): Shop dialog: Do you have any soap? Sorry, we don't have any soap. But we have some shampoo. Write what is in the shop: They have some ... But they don't have any .... Song: Do you have any toothpaste?","Grammar Time (Workbook p. 127): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Unit 8B · How much time do we have?","kd":{"kind":"B","label":"Unit 8B · How much time do we have?","goal":"-ed endings: t, id, d. Read a letter about a holiday. Talk about your vacation. Address an envelope.","tr":[["Дорогой Дэн, как дела?","Dear Dan, how are you?"],["У нас было необычное начало каникул.","We had a really unusual start to our summer vacation."],["Это была долгая поездка на поезде.","It was a long journey by train."],["Мы все заснули.","We all fell asleep."],["Вдруг мы услышали свисток поезда.","Suddenly, we heard the train's whistle."],["Мы пропустили нашу станцию.","We missed our station."],["Следующий поезд завтра утром.","The next train leaves tomorrow morning."],["Я был разочарован, потому что город казался маленьким.","I was disappointed because the town seemed small."],["В центре мы увидели фейерверк и ярмарку.","In the town center, we saw fireworks and a fair."],["Это было отличное начало каникул!","It was a brilliant start to our vacation!"]],"ch":[["Мы вышли на следующей станции, потому что мы пропустили нашу.","We got off at the next station because we missed ours."],["Напиши мне скоро и расскажи о своих каникулах.","Write soon and tell me about your vacation."]],"us":[["Have you got any soap?","Do you have any soap?"],["I haven't got much money.","I don't have much money."],["We've got lots of time.","We have lots of time."],["holiday","vacation"],["shop","store"],["aeroplane","airplane"],["postcode","zip code (in the USA)"],["pound","dollar"],["Mum","Mom"]],"copy":["unusual","journey","fall asleep","whistle","hotel","disappointed","fireworks","fair","field","branch","plant","seed","leaf","dig","beak","root","sweet","climb","deal"],"rwords":["unusual","journey","fall asleep","whistle","hotel","disappointed","fireworks","fair"],"retell":["unusual","train","fall asleep","missed","hotel","fireworks","fair","brilliant start"],"rule":{"title":"How much / how many · lots of · some / any","lines":["Countable (we can count: 1, 2, 3): pencils, suitcases, passengers, coins  →  How MANY pencils do you have? I don't have MANY pencils.","Uncountable (we cannot count): money, luggage, time, water, soap  →  How MUCH money do you have? I don't have MUCH money.","LOTS OF goes with both: We have lots of money. We have lots of pencils.","SOME in sentences with 'yes': We have some magazines.   ANY in questions and 'no' sentences: Do you have any newspapers? We don't have any newspapers.","American: Do you have ...? I don't have ... (the book says: Have you got ...? I haven't got ...)."],"signal":"Can you count it? yes → many (pencils) · no → much (money, time, luggage).  ?  or  not  → any.   Yes-sentence → some.","ru":"In Russian «сколько?» is one word. In English: how MANY (things you count) or how MUCH (things you do not count). Also «есть» = DO you have ...?","oops":["How much pencils do you have? → How many pencils do you have?","I don't have many money. → I don't have much money.","Do you have some soap? → Do you have any soap?","We don't have some magazines. → We don't have any magazines."]},"hasBig":true,"big":[["c","walked → ends with the sound ___",["t","id","d"],0,"walked = t"],["c","waited → ends with the sound ___",["t","id","d"],1,"waited = id (after t and d)"],["c","played → ends with the sound ___",["t","id","d"],2,"played = d"],["c","painted → ___",["t","id","d"],1,"painted = id"],["c","finished → ___",["t","id","d"],0,"finished = t"],["c","On an envelope, the stamp goes ___.",["top right","bottom left"],0,"at the top on the right"],["c","The zip code goes ___.",["at the end","first"],0,"last line"],["c","Finn missed his ___.",["station","hotel"],0,"his station"],["c","In the town center Finn saw ___.",["fireworks and a fair","a zoo"],0,"fireworks and a fair"],["r","Why was Finn disappointed?","Because the town seemed small and unexciting."],["r","Retell Finn's letter in 5 sentences.","Finn and his family were on the train. They fell asleep. They missed their station. ... "],["r","Ask a friend about their vacation.","Where did you go? What did you do?"]],"cb":[[65,"Phonics and spelling"],[66,"Skills time: reading"],[67,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 61–63 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 65): -ed endings: t (walked, finished, washed), id (waited, painted, tidied), d (showed, played, rained)","Reading words (p. 66): read the English and the Russian, say and repeat","Reading (p. 66): A letter about a holiday: listen, read aloud in pairs, answer the questions","Retell with these words: unusual, train, fall asleep, missed, hotel, fireworks, fair, brilliant start","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 67): Listening: who went where (Lucas, Nada, Ronny). Ask and answer: Did you go on vacation last summer? Where did you go? How did you travel there? What was the weather like? Did you eat any special food?","Writing preparation (p. 67): How to address an envelope: stamp at the top on the right, the name first, then the house number and the road, the town, and the zip code at the end. The writing task is a letter about my vacation. The writing task is homework.","Story · The Bear Who Chose First: look at the picture and guess; teach the new words (the Russian is in the vocabulary file); read aloud in turns; tell what happens in 5 sentences with the key words","Story: the kids close the book and retell it to a partner","Translation check: 10 sentences + 2 challenge"],"story":[{"n":4,"title":"The Bear Who Chose First","pic":"st5-04","paras":["A bear lived beside a wide field. He told every animal that the field was his. He never worked in it. But he was big, so nobody said no to him. Nobody but a crow.","“You cannot eat a field,” the crow said from a low branch. “Somebody must plant something first. And you do not know how.”","The bear thought about that for a long time. “Then we will work together,” he said. “You will do the work. We will take half each. But I am bigger, so I must choose my half first.”","“Very well,” the crow answered. “Let us make a deal. You may choose every spring. You will choose before I put the seed into the ground.”","The bear knew one thing about plants. Good things grow up, towards the sun. “Everything above the ground is mine,” he said. “You may keep the dirty part under it.”","All summer, green leaves grew across the field. The bear sat beside it and felt proud of himself.","Then the cold days came. The animals gathered to watch. The bear pulled up his half and took home a small mountain of leaves. They were hard and dry. They tasted of nothing at all. Then the crow dug into the soft ground with her feet and her beak. She pulled out the roots: long orange carrots, sweet and heavy and full of food.","That was how the bear found out where a carrot keeps its dinner.","“You made a mistake,” the crow said kindly. “The best part was below.”","The bear did not sleep well that winter. In spring he came back with his mind already made up.","“This year everything below the ground is mine,” he said. “Every root. You can have the green part on top.”","“Are you sure?” asked the crow. “You should think a little longer. You might want to choose again.”","“I have decided,” said the bear.","So the crow planted apple trees. That summer they climbed up over the bear’s head. At the end of summer every tree above him was heavy and red. The whole field smelled of apples.","The bear came with his big hands and dug all day. Under the trees he found nothing but hard, dry wood. Above him the crow sat in the leaves and ate.","“You could have asked me,” she said. “I would have told you. It would have cost you nothing.”","The bear still owns the field. But now, when somebody says he can choose first, he sits down. He looks at the sky for a while. He looks at the ground for a while. And he asks what is going to grow."],"words":[["field","fiːld","поле","A large piece of open ground where plants are grown."],["branch","brɑːntʃ","ветка","One of the parts of a tree that grows out from it."],["plant","plɑːnt","сажать","To put a seed or a young tree into the ground so that it grows."],["seed","siːd","семя, семечко","The small hard part of a plant that a new plant grows from."],["leaf","liːf","лист","The flat green part that grows on a tree or a plant."],["dig","dɪɡ","копать","To make a hole in the ground, or take something out of it."],["beak","biːk","клюв","The hard pointed mouth of a bird."],["root","ruːt","корень","The part of a plant that grows under the ground."],["sweet","swiːt","сладкий","Tasting like sugar or honey."],["climb","klaɪm","взбираться, расти вверх","To go up something, or to grow upwards."],["deal","diːl","сделка, договор","An agreement between two people about what each one will do."]],"phrases":[["make a deal","договориться, заключить сделку","They made a deal before they started the work."],["make a mistake","сделать ошибку","I made a mistake and took the wrong bag."],["find out","узнать, выяснить","He found out later that the answer was wrong."]],"retell":["field","branch","plant","seed","leaf","dig","beak"]}]}},{"n":3,"subtopic":"Unit 9A · Something new to watch!","kd":{"kind":"A","label":"Unit 9A · Something new to watch!","goal":"TV and media words. Infinitive of purpose (to + base verb): I turned on the TV to watch sports. How often ...? once, twice, three times a week.","tr":[["Я включил телевизор, чтобы посмотреть баскетбольный матч.","I turned on the TV to watch the basketball game."],["Он выключил его, чтобы поиграть в видеоигру.","He turned it off to play a video game."],["Дай мне пульт, пожалуйста.","Give me the remote control, please."],["Давай найдём что-нибудь новое посмотреть.","Let's find something new to watch."],["Мы поехали на лодке, чтобы увидеть дельфинов.","We went in the boat to see the dolphins."],["Я использую телефон, чтобы слушать музыку.","I use my cell phone to listen to music."],["Как часто ты смотришь телевизор?","How often do you watch TV?"],["Я смотрю документальный фильм раз в неделю.","I watch a documentary once a week."],["Он смотрит мультфильмы три раза в неделю.","He watches cartoons three times a week."],["Я никогда не смотрю новости.","I never watch the news."]],"ch":[["Я использую компьютер, чтобы писать письма, но я никогда не использую его, чтобы смотреть телевизор.","I use the computer to write emails, but I never use it to watch TV."],["Мы смотрим мультфильм дважды в неделю, чтобы отдохнуть после школы.","We watch a cartoon twice a week to relax after school."]],"us":[["advert","commercial (or ad)"],["mobile phone","cell phone"],["TV programme","TV program"],["programme","program"],["film","movie (film is also OK)"],["favourite","favorite"],["football","soccer"],["colourful","colorful"]],"copy":["cartoon","radio","camcorder","the news","documentary","channel","commercial","remote control","TV program","cell phone","watch","film (movie)","turn on","turn off","change","favorite"],"rwords":[],"retell":[],"rule":{"title":"Infinitive of purpose · How often ...?","lines":["Why do we do something? To + the base verb answers the question WHY: I turned on the TV to watch sports. We went in the boat to see the dolphins.","to + base verb = the infinitive. It does not change: I use my phone to take photos. She uses a computer to write emails.","How often ...? asks about frequency: How often do you watch TV?  — Every day. / Once a week. / Twice a month. / Three times a year. / Never.","1x = once · 2x = twice · 3x = three times · 4x = four times · 0x = never.   Put them at the end: I watch a documentary once a week."],"signal":"Why? / for what? → to + base verb.   How often? → every day, once / twice / three times a week, never.","ru":"In Russian we say «чтобы смотреть» or «смотреть». In English we use TO + base verb (not 'for watch', not 'for watching').","oops":["I turned on the TV for watch sports. → I turned on the TV to watch sports.","He uses a phone to takes photos. → He uses a phone to take photos.","I watch TV two times a week. → I watch TV twice a week.","How often you watch TV? → How often do you watch TV?"]},"hasBig":true,"big":[["c","I turned on the TV ___ the news.",["to watch","for watch"],0,"purpose → to + base verb"],["c","He uses a phone ___ photos.",["to take","to takes"],0,"to + base verb (no -s)"],["c","We went to the beach ___ swim.",["to","for"],0,"to + base verb"],["c","How ___ do you watch TV?",["often","many"],0,"how often"],["c","Two times = ___",["once","twice"],1,"twice"],["c","One time = ___",["once","twice"],0,"once"],["r","Find the mistake: I use a computer for write emails.","I use a computer to write emails."],["r","Find the mistake: I watch TV two times a week.","I watch TV twice a week."],["r","Find the mistake: How often you watch cartoons?","How often do you watch cartoons?"],["r","Say why: turn on the radio / music","I turned on the radio to listen to music."],["r","Say how often: 3 times a week / film","I watch a film three times a week."],["r","Say: never / news","I never watch the news."],["p","g-k-remote-control","What is it?","It's a remote control."],["p","g-k-camcorder","What is it?","It's a camcorder."],["p","radio","What is it?","It's a radio."],["p","g-k-cartoon","What is on TV?","A cartoon is on TV."]],"cb":[[68,"Words and story"],[69,"Grammar"],[70,"Grammar and song"]],"wb":"Workbook pp. 64–66 and Grammar Time p. 128","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 68): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 68): listen, read in roles, act it out","Grammar (p. 69): Infinitive of purpose · How often ...?. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 70): Ask and answer: How often do you watch a film? Once a week. How often do you use a camcorder? Then write: I watch a film once a week, but Andy watches a film three times a week.. Song: How often ...?","Grammar Time (Workbook p. 128): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}}],"goal":"Unit 8A · Unit 8B · Unit 9A"},{"n":8,"title":"Week 8","icon":"ShoppingBag","lessons":[{"n":1,"subtopic":"Unit 9B · Something new to watch!","kd":{"kind":"B","label":"Unit 9B · Something new to watch!","goal":"er and or endings. Read a TV guide: What's on TV? Talk about your favorite program. The prefix un-.","tr":[["Что идёт по телевизору?","What's on TV?"],["На первом канале фильм в половине пятого.","On Channel 1, there's a movie at 4:30."],["Гру хочет украсть луну.","Gru wants to steal the moon."],["Ему нужны три маленькие девочки, чтобы помочь с его планом.","He needs three little girls to help him with his plan."],["Лиза Симпсон очень умная девочка.","Lisa Simpson is a very clever girl."],["Барт — озорной мальчик, который подшучивает над людьми.","Bart is a naughty boy who plays tricks on people."],["Гомер любит пончики.","Homer loves doughnuts."],["Не пропустите сегодняшнюю большую игру!","Don't miss tonight's big game!"],["Игра начнётся в шесть двадцать на стадионе в Риме.","Kick-off is at 6:20 at the stadium in Rome."],["На Галапагосских островах живут гигантские черепахи.","Giant tortoises live on the Galapagos Islands."]],"ch":[["Моя любимая передача на втором канале, и она начинается в пять пятнадцать.","My favorite program is on Channel 2, and it starts at 5:15."],["Эта документальная передача рассказывает о необычных животных, поэтому я смотрю её каждую неделю.","This documentary is about unusual animals, so I watch it every week."]],"us":[["advert","commercial (or ad)"],["mobile phone","cell phone"],["TV programme","TV program"],["programme","program"],["film","movie (film is also OK)"],["favourite","favorite"],["football","soccer"],["colourful","colorful"]],"copy":["steal","doughnut","villain","kick-off","stadium","giant","get into trouble","play a trick on"],"rwords":["steal","doughnut","villain","kick-off","stadium","giant","get into trouble","play a trick on"],"retell":["film","cartoon","sport","documentary","channel","story","tonight","stadium"],"rule":{"title":"Infinitive of purpose · How often ...?","lines":["Why do we do something? To + the base verb answers the question WHY: I turned on the TV to watch sports. We went in the boat to see the dolphins.","to + base verb = the infinitive. It does not change: I use my phone to take photos. She uses a computer to write emails.","How often ...? asks about frequency: How often do you watch TV?  — Every day. / Once a week. / Twice a month. / Three times a year. / Never.","1x = once · 2x = twice · 3x = three times · 4x = four times · 0x = never.   Put them at the end: I watch a documentary once a week."],"signal":"Why? / for what? → to + base verb.   How often? → every day, once / twice / three times a week, never.","ru":"In Russian we say «чтобы смотреть» or «смотреть». In English we use TO + base verb (not 'for watch', not 'for watching').","oops":["I turned on the TV for watch sports. → I turned on the TV to watch sports.","He uses a phone to takes photos. → He uses a phone to take photos.","I watch TV two times a week. → I watch TV twice a week.","How often you watch TV? → How often do you watch TV?"]},"hasBig":true,"big":[["c","Which word ends in or?",["doctor","mother"],0,"doctor, visitor, actor = or"],["c","moth___",["er","or"],0,"mother = er"],["c","act___",["er","or"],1,"actor = or"],["c","happy → ___ (opposite)",["unhappy","dishappy"],0,"un-"],["c","safe → ___",["unsafe","nosafe"],0,"unsafe"],["c","Gru wants to ___ the moon.",["steal","buy"],0,"steal"],["c","Bart is a ___ boy.",["naughty","lazy"],0,"naughty"],["c","The Galapagos Islands are famous for giant ___.",["tortoises","dolphins"],0,"tortoises"],["r","Tell me about your favorite program.","My favorite program is ... It is on Channel ... It is about ..."],["r","When is the match on Channel 3?","Kick-off is at 6:20."],["r","Ask: what channel / is it on?","What channel is it on?"],["r","Retell the TV guide in 5 sentences.","On Channel 1 there is a film ... On Channel 2 ... On Channel 3 ... On Channel 4 ..."]],"cb":[[71,"Phonics and spelling"],[72,"Skills time: reading"],[73,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 67–69 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 71): er (mother, father, September) and or (visitor, doctor, actor)","Reading words (p. 72): read the English and the Russian, say and repeat","Reading (p. 72): A TV guide: What's on TV?: listen, read aloud in pairs, answer the questions","Retell with these words: film, cartoon, sport, documentary, channel, story, tonight, stadium","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 73): Listening: who watched what (Stacy, James, Emily, Kai). Speaking: Tell me about your favorite program. What channel is it on? When is it on? It's about ...","Writing preparation (p. 73): The prefix un- gives the opposite: happy → unhappy, friendly → unfriendly, well → unwell, safe → unsafe, clean → unclean, comfortable → uncomfortable. The writing task is a TV guide. The writing task is homework.","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Review 3 · Units 7–9","kd":{"kind":"review","label":"Review 3 · Units 7–9","goal":"No new topic: everything from Units 7–9. Mixed grammar practice on the big screen and Fluency Time.","tr":[["В будущем люди будут путешествовать на ракетах.","In the future, people will travel in rockets."],["Они не вернутся в Австралию.","They won't go back to Australia."],["Они будут здесь через две недели.","They'll be here in two weeks' time."],["Сколько у тебя денег?","How much money do you have?"],["Сколько у тебя карандашей?","How many pencils do you have?"],["У нас нет газет, но есть журналы.","We don't have any newspapers, but we have some magazines."],["Я включил телевизор, чтобы посмотреть новости.","I turned on the TV to watch the news."],["Мы поехали на лодке, чтобы увидеть дельфинов.","We went in the boat to see the dolphins."],["Как часто ты смотришь телевизор? — Дважды в неделю.","How often do you watch TV? — Twice a week."],["Я никогда не смотрю мультфильмы.","I never watch cartoons."]],"ch":[["В будущем у нас будут роботы, но они не будут делать нашу домашнюю работу, потому что мы будем делать её сами.","In the future we'll have robots, but they won't do our homework because we'll do it ourselves."],["У нас мало денег, поэтому мы не купим подарок, но мы нарисуем открытку, чтобы сказать «спасибо».","We don't have much money, so we won't buy a present, but we'll draw a card to say thank you."]],"us":[],"copy":[],"rwords":[],"retell":[],"rule":null,"hasBig":true,"big":[["c","Next week we ___ to the museum.",["Now (am / is / are + -ing)","Past (finished)","Future (will)"],2,"next week → will"],["c","Look! They ___ the news now.",["Now (am / is / are + -ing)","Past (finished)","Future (will)"],0,"Look! → now"],["c","Yesterday I ___ a film.",["Now (am / is / are + -ing)","Past (finished)","Future (will)"],1,"yesterday → past"],["c","In 100 years, people ___ on Mars.",["Now (am / is / are + -ing)","Past (finished)","Future (will)"],2,"in 100 years → will"],["c","How ___ coins do you have?",["much","many"],1,"coins = countable"],["c","I use my phone ___ photos.",["for take","to take"],1,"to + base verb"],["r","Find the mistake: Will they to go to Mars?","Will they go to Mars?"],["r","Find the mistake: I watch TV two times a week.","I watch TV twice a week."],["r","Find the mistake: Do you have some money?","Do you have any money?"],["r","Ask a friend: How often / use a computer?","How often do you use a computer?"],["r","Say what will happen: robots / help","Robots will help us."],["r","Say: we / not have / time","We don't have much time."]],"cb":[[74,"Fluency Time: Choosing TV programs"],[75,"Project"],[76,"Review 3"],[77,"Review 3"]],"wb":"Workbook pp. 70–71 and 72–73","steps":["Warm-up: the 3 earlier sentences from the last translation check","Mini test (file): 12 questions on Units 7–9","Speaking in pairs: the speaking questions (in the answers file)","Fluency Time (p. 74): Choosing TV programs. What's on TV? / I can't stand sport on TV. / Let's change the channel. / Pass me the remote control, please. / I love cartoons. So do I! / There are usually cartoons on Channel 7.","Project: my own TV (or for homework)","Big screen: grammar practice (which rule is it?)","Review pages (pp. 76–77) together","Check the test; each kid fixes three mistakes","Translation check: 10 sentences + 2 challenge"]}},{"n":3,"subtopic":"Reading 3 · Travel","kd":{"kind":"reading","label":"Reading 3 · Travel","goal":"Read, learn the key words, and retell: Family Activity Holiday · Gulliver's Travels.","tr":[["Хочешь отпуск, который понравится всей семье?","Do you want a vacation that the whole family can enjoy?"],["Мы предлагаем трёхдневный семейный активный отдых.","We offer a three-day family activity vacation."],["Инструкторы покажут вам, как носить страховку.","Our instructors will show you how to wear harnesses."],["Вы можете заняться скалолазанием и верховой ездой.","You can try rock climbing and horse riding."],["На озере вы научитесь ходить под парусом.","On the lake you can learn to sail."],["Гулливер поплыл на корабле на острова.","Gulliver sailed on a ship to some islands."],["Вдруг началась ужасная буря.","Suddenly there was a terrible storm."],["Он упал в воду и доплыл до острова.","He fell into the water and swam to an island."],["Он увидел крошечных людей, ростом пятнадцать сантиметров.","He saw tiny men, about 15 centimeters tall."],["Они не поняли его язык, но увидели, что он дружелюбный.","They didn't understand his language, but they saw that he was friendly."]],"ch":[["Церис написала, что это был лучший семейный отпуск, потому что инструкторы были дружелюбными и помогали.","Cerys wrote that it was her best family vacation because the instructors were friendly and helpful."],["Когда Гулливер проснулся, он не мог двигаться, потому что крошечные люди привязали его к земле.","When Gulliver woke up, he couldn't move because the tiny men had tied him to the ground."]],"us":[],"copy":["instructor","rope","climbing wall","kayak","pony","voyage","storm","tiny","frightened","language"],"rwords":["instructor","rope","climbing wall","kayak","pony","voyage","storm","tiny","frightened","language"],"retell":["activity holiday","rock climbing","kayaking","Gulliver","ship","storm","island","tiny men"],"rule":null,"hasBig":true,"big":[["r","How many days is the family activity holiday?","Three days."],["r","Can you sail on the lake?","Yes, you can."],["r","Will families be in large groups?","No, they will be in small groups."],["r","Has Cerys got a brother?","Yes, she has. His name is James."],["r","What did Gulliver do first?","He joined a ship and sailed to the islands of the South Pacific."],["r","What happened in the storm?","He fell into the water and swam to an island."],["r","What did he see when he woke up?","Lots of tiny men on his arms and legs."],["r","Why did Gulliver eat so much?","Because the food was very, very small."],["r","Would you like to travel by ship? Why?","Yes / No, because ..."],["r","Retell Gulliver's story in 5 sentences.","Gulliver sailed on a ship ... storm ... island ... tiny men ... the city ..."]],"cb":[[78,"Travel (1)"],[79,"Travel (2)"]],"wb":"No Workbook pages. Homework: write 5 sentences in the copybook (the retell).","steps":["Warm-up: the 3 earlier sentences from the last translation check","Pre-teach the key words: read the English and the Russian from the vocabulary file","Look at the pictures and guess: What is the text about?","Listen and read the first text (twice: once to listen, once in pairs); answer the questions","The same for the second text","Retell with these words: activity holiday, rock climbing, kayaking, Gulliver, ship, storm, island, tiny men","Big screen: comprehension questions","Translation check: 10 sentences + 2 challenge"]}}],"goal":"Unit 9B · Review 3 · Reading 3"},{"n":9,"title":"Week 9","icon":"Mountain","lessons":[{"n":1,"subtopic":"Unit 10A · I've printed my homework","kd":{"kind":"A","label":"Unit 10A · I've printed my homework","goal":"Computer words. Present perfect: affirmative (I've finished, he's made). The past participle: regular (-ed) and irregular.","tr":[["Мы закончили домашнюю работу. Можно нам теперь играть?","We've finished our homework. Can we play now?"],["Вы выключили компьютер и принтер?","Have you turned off the computer and the printer?"],["Нет, не выключили.","No, we haven't."],["Ты устроил беспорядок.","You've made a mess."],["Я распечатал домашнее задание.","I've printed my homework."],["Она сохранила свою работу на флешку.","She's saved her work on a memory stick."],["Макс убрал шкафы.","Max has tidied the cabinets."],["Ты видел мои новые колонки?","Have you seen my new speakers?"],["Нет, не видел. Покажи мне, пожалуйста.","No, I haven't. Please show me."],["Она ещё не сделала домашнее задание.","She hasn't done her homework yet."]],"ch":[["Я уже убрал свою комнату, но ещё не сделал домашнее задание, поэтому я не могу играть.","I've already tidied my room, but I haven't done my homework, so I can't play."],["Вчера мы весь вечер искали в интернете, а сегодня мы уже всё напечатали.","Yesterday we searched the Internet all evening, and today we've printed everything."]],"us":[["Mum","Mom"],["programme","program"],["Have you got ...?","Do you have ...?"],["tidy up the cupboards","tidy up the cabinets / closets"],["shelf","shelf (same)"],["flat","apartment"]],"copy":["printer","screen","mouse","log on","speakers","click on","save a document","memory stick","search the Internet","keyboard","computer","email","password","tidy up","mess","homework"],"rwords":[],"retell":[],"rule":{"title":"Present perfect: affirmative, questions and negatives","lines":["Form: have / has + the PAST PARTICIPLE.   We've finished our homework. He's made a mess. (I've · you've · we've · they've · he's · she's)","Regular past participle = verb + -ed (printed, saved, tidied, turned off). Irregular: make → made · put → put · see → seen · do → done · go → been / gone.   (list: Workbook p. 131)","Question: Have / Has + subject + participle? Have you seen my speakers? Yes, I have. / No, I haven't. Has she done her homework? Yes, she has.","Negative: haven't / hasn't + participle: She hasn't printed the document.","We use the present perfect for something that happened in the past, but it is still true NOW. I've tidied my room = my room is tidy now."],"signal":"Something finished, but the result is here now (I've lost my phone = I don't have it now). No exact time: NOT yesterday, NOT last week (that is past simple).","ru":"Russian has no present perfect: «Я убрал комнату» for both the past (yesterday) and the result (now it's clean). In English: I tidied my room yesterday (past simple) but I've tidied my room (present perfect: it's clean now).","oops":["I have tidied my room yesterday. → I tidied my room yesterday.","She has finish her homework. → She has finished her homework.","Have you saw my speakers? → Have you seen my speakers?","He haven't printed it. → He hasn't printed it."]},"hasBig":true,"big":[["c","We ___ our homework. (finish)",["'ve finished","finished yesterday"],0,"result now → have + participle"],["c","She ___ the document. (save)",["'s saved","'s save"],0,"has + -ed"],["c","He's ___ a mess. (make)",["maked","made"],1,"make → made"],["c","Have you ___ my speakers? (see)",["saw","seen"],1,"see → saw → seen"],["c","Has she ___ her homework? (do)",["did","done"],1,"do → did → done"],["c","Yes, she ___.",["has","did"],0,"Has she ...? → Yes, she has."],["r","Find the mistake: Have you saw my new speakers?","Have you seen my new speakers?"],["r","Find the mistake: I have tidied my room yesterday.","I tidied my room yesterday."],["r","Find the mistake: He haven't printed it.","He hasn't printed it."],["c","Which is the present perfect (the result is now)?",["I've lost my phone.","I lost my phone last week."],0,"no time word + result now"],["r","Ask: Max / tidy / his room","Has Max tidied his room?"],["r","Say: I / not / do / my homework","I haven't done my homework."],["p","g-k-printer","What is it?","It's a printer."],["p","g-k-computer-mouse","What is it?","It's a mouse."],["p","g-k-speakers","What are they?","They're speakers."],["p","g-k-memory-stick","What is it?","It's a memory stick."],["p","g-k-keyboard","What is it?","It's a keyboard."]],"cb":[[80,"Words and story"],[81,"Grammar"],[82,"Grammar and song"]],"wb":"Workbook pp. 74–76 and Grammar Time p. 128","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 80): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 80): listen, read in roles, act it out","Grammar (p. 81): Present perfect: affirmative, questions and negatives. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 82): Ryan's chores: tidy room ✓, do homework ✓, wash the dishes ✗, make lunch ✓, put clothes away ✗. Ask: Have you tidied your room? Yes, I have. Write: He has tidied his room and .... Song: I've really tried!","Grammar Time (Workbook p. 128): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Unit 10B · I've printed my homework","kd":{"kind":"B","label":"Unit 10B · I've printed my homework","goal":"ur and ir spellings. Read online instructions: What is an email? Talk about how often we use the computer. Subject, verb, object.","tr":[["Что такое электронное письмо?","What is an email?"],["Электронное письмо — это сообщение с одного компьютера на другой.","An email is a message sent from one computer to another."],["Сначала щёлкни мышью и введи адрес.","First, click with your mouse and type the email address."],["Потом напиши тему письма.","Then write what the email is about."],["Напиши сообщение на клавиатуре.","Type your message using the keyboard."],["Проверь орфографию.","Check your spelling."],["Можно прикрепить фото к письму.","You can attach a photo to the email."],["В конце нажми «Отправить».","Finally, click on Send."],["Моя подруга Люси прислала мне письмо.","My friend Lucy sent me an email."],["Мы идём на день рождения в боулинг.","We're going to a birthday party at the bowling alley."]],"ch":[["Если ты хочешь отправить письмо, сначала тебе нужен адрес электронной почты.","If you want to send an email, first you need an email address."],["Я проверил орфографию и прикрепил фотографию, а потом отправил сообщение.","I checked my spelling and attached a photo, and then I sent the message."]],"us":[["Mum","Mom"],["programme","program"],["Have you got ...?","Do you have ...?"],["tidy up the cupboards","tidy up the cabinets / closets"],["shelf","shelf (same)"],["flat","apartment"]],"copy":["type the email address","subject","spellchecker","attach a photo","website","send a message","merchant","cook","servant","silk","prove","thief","tent","pot","tail","steal","trick"],"rwords":["type the email address","subject","spellchecker","attach a photo","website","send a message"],"retell":["type","subject","keyboard","spellchecker","attach a photo","send a message"],"rule":{"title":"Present perfect: affirmative, questions and negatives","lines":["Form: have / has + the PAST PARTICIPLE.   We've finished our homework. He's made a mess. (I've · you've · we've · they've · he's · she's)","Regular past participle = verb + -ed (printed, saved, tidied, turned off). Irregular: make → made · put → put · see → seen · do → done · go → been / gone.   (list: Workbook p. 131)","Question: Have / Has + subject + participle? Have you seen my speakers? Yes, I have. / No, I haven't. Has she done her homework? Yes, she has.","Negative: haven't / hasn't + participle: She hasn't printed the document.","We use the present perfect for something that happened in the past, but it is still true NOW. I've tidied my room = my room is tidy now."],"signal":"Something finished, but the result is here now (I've lost my phone = I don't have it now). No exact time: NOT yesterday, NOT last week (that is past simple).","ru":"Russian has no present perfect: «Я убрал комнату» for both the past (yesterday) and the result (now it's clean). In English: I tidied my room yesterday (past simple) but I've tidied my room (present perfect: it's clean now).","oops":["I have tidied my room yesterday. → I tidied my room yesterday.","She has finish her homework. → She has finished her homework.","Have you saw my speakers? → Have you seen my speakers?","He haven't printed it. → He hasn't printed it."]},"hasBig":true,"big":[["c","Which word has ur?",["nurse","shirt"],0,"nurse, hurt, curtains"],["c","Which word has ir?",["Thursday","circle"],1,"circle, girl, shirt, bird"],["c","f___st",["ur","ir"],1,"first = ir"],["c","c___tains",["ur","ir"],0,"curtains = ur"],["c","She sends emails. \"emails\" is the ___",["subject","verb","object"],2,"the object receives the action"],["c","She sends emails. \"sends\" is the ___",["subject","verb","object"],1,"the verb is the action"],["c","The first step of sending an email:",["type the address","click on Send"],0,"address first"],["c","The spellchecker helps you ___.",["correct your spelling","send the email"],0,"correct your spelling"],["r","Say how often you use the computer.","I do my homework on the computer once a week."],["r","Name the 6 steps to send an email.","Address, subject, message, spellcheck, attach a photo, send."],["r","Ask a friend: how often / send emails","How often do you send emails?"],["r","Retell the text in 5 sentences.","An email is a message ... First ... Then ... Finally ..."]],"cb":[[83,"Phonics and spelling"],[84,"Skills time: reading"],[85,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 77–79 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 83): ur (hurt, Thursday, nurse, curtains) and ir (circle, girl, shirt, bird)","Reading words (p. 84): read the English and the Russian, say and repeat","Reading (p. 84): Online instructions: What is an email?: listen, read aloud in pairs, answer the questions","Retell with these words: type, subject, keyboard, spellchecker, attach a photo, send a message","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 85): Listening: number the computer screens, and say who does what (Rita, Dan, Beth). Speaking: How often do you ... on the computer? (do homework, listen to music, send emails, play games, watch DVDs, search the Internet) — Once a week.","Writing preparation (p. 85): Parts of a sentence: the subject does the action, the verb shows the action, the object receives it: She (S) sends (V) emails (O). The writing task is about how I use a computer. The writing task is homework.","Story · The Donkey That Knew the Thief: look at the picture and guess; teach the new words (the Russian is in the vocabulary file); read aloud in turns; tell what happens in 5 sentences with the key words","Story: the kids close the book and retell it to a partner","Translation check: 10 sentences + 2 challenge"],"story":[{"n":5,"title":"The Donkey That Knew the Thief","pic":"st5-05","paras":["A rich merchant named Rustam stopped for the night at a house on the mountain road. He had ten men with him: a cook, two drivers and seven servants. He also had a bag of gold and two pieces of silk.","In the morning the gold was gone.","Rustam was angry. “Somebody in this house has taken my gold,” he shouted, “and I know who it is. It is the boy.”","The boy was Karim. He carried the water and washed the pots, and he was the poorest person there. Everybody turned and looked at him.","“I did not take it,” Karim said quietly. “Then prove it,” Rustam said.","“I will do my best,” Karim said. He thought for a long time. “Wait until tonight. Tonight the thief will show himself to all of us.”","That evening Karim put a small tent in the yard, and he put the old donkey inside it. His name was Bobo, and he was the laziest animal on that road. Karim also took the black cooking pot off the fire and carried it into the tent. Then he closed the door.","“Bobo is a magic donkey,” Karim told the men. “You will all go in, one by one, in the dark. You will put your hand on his tail and say these words: I did not steal the gold. Bobo knows the truth about every man here. When the thief touches him, Bobo will cry out, and everybody in the yard will hear it.”","Some of the men laughed. Some of them did not laugh at all. “Nobody may run away,” Rustam said. “Every man goes in.”","One by one they walked into the dark tent, and one by one they came out again. Bobo ate his grass and made no sound.","Rustam smiled a cold smile. “Your magic does not work, boy. Now we will talk about you again.” “One moment,” Karim said. “Please show me your hands. All of you.”","Ten men held up their hands. Nine pairs of hands were black from the fingers to the arm. One pair was clean and white. They were the hands of the cook.","“He never touched Bobo,” Karim said. “He was the only man in this yard who believed me. The tail is black, because I put the bottom of that pot on it before you came.”","The cook looked at his clean hands for a long time. Then he told them where the gold was. Rustam gave Karim two silver coins and a piece of silk. “Do not tell this to other people,” he said. “Keep it a secret.”","Karim did not keep it a secret. He told it in every village on that road, so now the trick is finished and it will never work again. And Bobo is still standing in the same yard, eating the same grass, and he has never said one word about any of it."],"words":[["merchant","ˈmɜːtʃənt","торговец, купец","A person who buys things and sells them again."],["cook","kʊk","повар","A person whose job is to make food."],["servant","ˈsɜːvənt","слуга","A person who works in the house of a rich family."],["silk","sɪlk","шёлк","A soft and expensive cloth."],["prove","pruːv","доказать","To show that something is true."],["thief","θiːf","вор","A person who takes things that are not his."],["tent","tent","палатка","A small house made of cloth. You sleep in it outside."],["pot","pɒt","кастрюля, котелок","A deep round dish. You cook food in it over a fire."],["tail","teɪl","хвост","The long part at the back of an animal."],["steal","stiːl","красть, воровать","To take something that is not yours."],["trick","trɪk","хитрость, трюк","A clever thing that you do to win, or to find the truth."]],"phrases":[["do your best","сделать всё, что можешь","I cannot promise, but I will do my best."],["keep a secret","хранить секрет","Can you keep a secret? Do not tell anybody."],["run away","убежать","The little boy ran away when he saw the big dog."]],"retell":["merchant","cook","servant","silk","prove","thief","tent"]}]}},{"n":3,"subtopic":"Unit 11A · Have you ever been ...?","kd":{"kind":"A","label":"Unit 11A · Have you ever been ...?","goal":"Places words. Present perfect with ever and never: Have you ever been to ...? Yes, I have. / No, I haven't. I've never seen a volcano.","tr":[["Ты когда-нибудь был в космосе?","Have you ever been to space?"],["Нет, я никогда не был в космосе.","No, I've never been to space."],["Ты когда-нибудь лазил на вулкан?","Have you ever climbed a volcano?"],["Да, лазил. Это опасно.","Yes, I have. It's dangerous."],["Она никогда не была на дне океана.","She's never been to the bottom of the ocean."],["Он был в пустыне?","Has he ever been to a desert?"],["Нет, не был.","No, he hasn't."],["Мы никогда не падали с гор.","We've never fallen in the mountains."],["Я никогда не видел вулкан.","I've never seen a volcano."],["Они когда-нибудь были в тропическом лесу?","Have they ever been to a rainforest?"]],"ch":[["Я никогда не был в пустыне, но однажды я был в пещере, и это было страшно.","I've never been to a desert, but I went to a cave once, and it was scary."],["Она уже была в трёх столицах, но ещё никогда не плавала в океане.","She's been to three capital cities, but she has never swum in the ocean."]],"us":[["Have you got ...?","Do you have ...?"],["Mum","Mom"],["holiday","vacation"],["lorry","truck"],["The mountains I climb get hotter as you go up!","(a joke in the book: the 'special mountain' is a volcano)"],["favourite","favorite"]],"copy":["town","ocean","volcano","village","oasis","rainforest","capital city","desert","island","cave","mountain","climb","space","bottom","dangerous","explorer"],"rwords":[],"retell":[],"rule":{"title":"Present perfect with ever and never","lines":["Have you EVER been to space? = at any time in your life up to now.  Yes, I have. / No, I haven't.   Has he ever climbed a volcano? Yes, he has. / No, he hasn't.","NEVER = not at any time in my life: I've never seen a volcano. She's never been to the bottom of the ocean. (never already means 'not', so NO haven't!)","go → been (when you went and came back): Have you ever been to Egypt?   see → seen · fall → fallen · climb → climbed · eat → eaten · swim → swum.","Question: Have you ever + participle? Answer with short answers: Yes, I have. / No, I haven't. — not 'Yes, I did'.","Different from the past simple: Have you ever been to Egypt? (life experience, no time)  vs  Did you go to Egypt last year? (finished time)."],"signal":"ever / never / in your life / up to now → present perfect. last year / yesterday / in 2019 → past simple.","ru":"Russian says «Ты когда-нибудь был в Египте?» with the past «был». In English the question needs HAVE + been: Have you ever BEEN to Egypt? (not 'Did you ever be'; not 'Have you ever went').","oops":["Have you ever went to a desert? → Have you ever been to a desert?","I haven't never seen a volcano. → I've never seen a volcano.","Did you ever climb a volcano? → Have you ever climbed a volcano?","Yes, I did. (to 'Have you ever ...?') → Yes, I have."]},"hasBig":true,"big":[["c","___ you ever been to a desert?",["Have","Did"],0,"ever → Have"],["c","Have you ever ___ a volcano?",["climbed","climb"],0,"participle"],["c","Has he ever ___ to space?",["been","went"],0,"go → been"],["c","No, I ___.",["haven't","didn't"],0,"short answer → haven't"],["c","Yes, she ___.",["has","did"],0,"short answer → has"],["c","I've ___ seen a volcano.",["never","haven't"],0,"never = not"],["r","Find the mistake: Have you ever went to space?","Have you ever been to space?"],["r","Find the mistake: I haven't never been to Egypt.","I've never been to Egypt."],["r","Find the mistake: Did you ever climb a mountain?","Have you ever climbed a mountain?"],["c","Which is life experience (no time)?",["Have you ever been to Egypt?","Did you go to Egypt in 2020?"],0,"no time → present perfect"],["r","Ask a friend about a rainforest.","Have you ever been to a rainforest?"],["r","Say: never / see / a volcano","I've never seen a volcano."],["p","volcano","What is it?","It's a volcano."],["p","desert","What is it?","It's a desert."],["p","g-k-rainforest","What is it?","It's a rainforest."],["p","island","What is it?","It's an island."],["p","g-k-cave","What is it?","It's a cave."],["p","g-k-oasis","What is it?","It's an oasis."]],"cb":[[86,"Words and story"],[87,"Grammar"],[88,"Grammar and song"]],"wb":"Workbook pp. 80–82 and Grammar Time p. 129","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 86): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 86): listen, read in roles, act it out","Grammar (p. 87): Present perfect with ever and never. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 88): Dave, Alice, Dom and Libby: climbed a mountain, been to space, been to a desert, seen gorillas in a rainforest. Say: This person has climbed a mountain and been to a desert, but has never been to space. (It's Alice!). Song: One day soon","Grammar Time (Workbook p. 129): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}}],"goal":"Unit 10A · Unit 10B · Unit 11A"},{"n":10,"title":"Week 10","icon":"Leaf","lessons":[{"n":1,"subtopic":"Unit 11B · Have you ever been ...?","kd":{"kind":"B","label":"Unit 11B · Have you ever been ...?","goal":"ea and e spellings. Read about the Everest expedition. Interview an explorer. Topic sentences.","tr":[["Эверест — самая высокая гора в мире.","Mount Everest is the highest mountain in the world."],["Он назван в честь Джорджа Эвереста.","It is named after George Everest."],["Первыми, кто поднялся на вершину, были Эдмунд Хиллари и Тенцинг Норгей.","The first people to climb to the top were Edmund Hillary and Tenzing Norgay."],["Экспедиция началась в марте тысяча девятьсот пятьдесят третьего года.","The expedition started in March 1953."],["Некоторые альпинисты сдались, потому что снаряжение не работало.","Some climbers gave up because their equipment didn't work."],["Там дул сильный ветер и шёл снег.","There was heavy snow and freezing winds."],["Они спали в палатке рядом с вершиной.","They slept in a tent near the summit."],["Утром их ботинки замёрзли.","In the morning their boots were frozen."],["Они были на вершине всего пятнадцать минут, потому что там мало кислорода.","They only stayed on the summit for 15 minutes because there isn't much oxygen."],["Они закопали шоколад в снегу.","They buried some chocolates in the snow."]],"ch":[["С тех пор на Эверест поднялось много людей.","Since then, many people have climbed Mount Everest."],["Самому старому человеку на вершине было восемьдесят лет, а самому молодому — тринадцать.","The oldest person on the summit was 80, and the youngest was 13."]],"us":[["Have you got ...?","Do you have ...?"],["Mum","Mom"],["holiday","vacation"],["lorry","truck"],["The mountains I climb get hotter as you go up!","(a joke in the book: the 'special mountain' is a volcano)"],["favourite","favorite"]],"copy":["location","height","oxygen","expedition","summit","equipment","frozen","melt"],"rwords":["location","height","oxygen","expedition","summit","equipment","frozen","melt"],"retell":["Hillary","Tenzing","expedition","equipment","summit","oxygen","photos","chocolates"],"rule":{"title":"Present perfect with ever and never","lines":["Have you EVER been to space? = at any time in your life up to now.  Yes, I have. / No, I haven't.   Has he ever climbed a volcano? Yes, he has. / No, he hasn't.","NEVER = not at any time in my life: I've never seen a volcano. She's never been to the bottom of the ocean. (never already means 'not', so NO haven't!)","go → been (when you went and came back): Have you ever been to Egypt?   see → seen · fall → fallen · climb → climbed · eat → eaten · swim → swum.","Question: Have you ever + participle? Answer with short answers: Yes, I have. / No, I haven't. — not 'Yes, I did'.","Different from the past simple: Have you ever been to Egypt? (life experience, no time)  vs  Did you go to Egypt last year? (finished time)."],"signal":"ever / never / in your life / up to now → present perfect. last year / yesterday / in 2019 → past simple.","ru":"Russian says «Ты когда-нибудь был в Египте?» with the past «был». In English the question needs HAVE + been: Have you ever BEEN to Egypt? (not 'Did you ever be'; not 'Have you ever went').","oops":["Have you ever went to a desert? → Have you ever been to a desert?","I haven't never seen a volcano. → I've never seen a volcano.","Did you ever climb a volcano? → Have you ever climbed a volcano?","Yes, I did. (to 'Have you ever ...?') → Yes, I have."]},"hasBig":true,"big":[["c","bread: the sound of ea is ___",["short e","long e"],0,"bread = short e"],["c","Which word has the short e sound with the letter e?",["tent","team"],0,"tent"],["c","h___vy",["ea","e"],0,"heavy = ea"],["c","sp___d",["ea","e"],1,"spend = e"],["c","Mount Everest is named after ___.",["George Everest","Edmund Hillary"],0,"George Everest"],["c","The first people to climb it were ___.",["Hillary and Tenzing","Mat Jones"],0,"Hillary and Tenzing"],["c","They stayed at the summit for ___.",["15 minutes","two days"],0,"15 minutes"],["c","A topic sentence is ___.",["the first sentence of a paragraph","the last sentence"],0,"the first sentence"],["r","Why did they only stay for 15 minutes?","Because it was difficult to breathe; there isn't much oxygen."],["r","What did Hillary do at the top?","He took some photos and buried some chocolates in the snow."],["r","Interview: ask about the weather.","What was the weather like?"],["r","Retell the expedition in 5 sentences.","The expedition started in 1953 ... they slept in a tent ... they reached the summit on 29th May ..."]],"cb":[[89,"Phonics and spelling"],[90,"Skills time: reading"],[91,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 83–85 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 89): ea (feather, bread, head, heavy) and e (spend, tent, present, help) — both can say the short e sound","Reading words (p. 90): read the English and the Russian, say and repeat","Reading (p. 90): An account of an expedition: Everest Expeditions: listen, read aloud in pairs, answer the questions","Retell with these words: Hillary, Tenzing, expedition, equipment, summit, oxygen, photos, chocolates","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 91): Listening: number the pictures, then circle the answers about the Everest expedition (14 kilos, ice, an axe, soup). Speaking: interview Edmund Hillary or Tenzing Norgay: How many men took part? What did you eat? What was the weather like? Where did you sleep?","Writing preparation (p. 91): A topic sentence is the first sentence of a paragraph; it tells the reader what the paragraph is about (Mount Everest is the highest mountain in the world). The writing task is a blog entry. The writing task is homework.","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Unit 12A · What's the matter?","kd":{"kind":"A","label":"Unit 12A · What's the matter?","goal":"Illness words. should / shouldn't for advice. could / couldn't = the past of can / can't.","tr":[["Макс, что случилось?","Max, what's the matter?"],["У меня болит живот и голова.","I have a stomachache and a headache."],["Меня тошнит.","I feel sick."],["Тебе надо выпить воды и лечь в постель.","You should drink some water and go to bed."],["Тебе не надо есть много пирожных.","You shouldn't eat lots of cakes."],["Ты не мог съесть ужин, но мог съесть все эти пирожные!","You couldn't eat your dinner, but you could eat all those cakes!"],["У меня болит ухо.","I have an earache."],["Тебе надо принять лекарство.","You should take medicine."],["Когда мне было четыре года, я не умел читать.","When I was four, I couldn't read."],["Ты умел плавать, когда тебе было четыре?","Could you swim when you were four?"]],"ch":[["Если у тебя болит горло, тебе надо остаться дома и не надо есть мороженое.","If you have a sore throat, you should stay at home and you shouldn't eat ice cream."],["Когда я был маленьким, я не мог читать, но теперь я могу читать и писать по-английски.","When I was little, I couldn't read, but now I can read and write in English."]],"us":[["You've got a stomachache.","You have a stomachache."],["chips (crisps)","chips = potato chips; fries = French fries"],["sweets","candy"],["Mum","Mom"],["a lot of cakes","a lot of cupcakes (cake is also fine)"],["fizzy drinks","soda"]],"copy":["a headache","feel sick","feel dizzy","a cold","a cough","an earache","a stomachache","a sore throat","take medicine","get better","doctor","nurse","hospital","tired","exercise","diet"],"rwords":[],"retell":[],"rule":{"title":"should / shouldn't and could / couldn't","lines":["should = it is a good idea (advice): You should drink some water. You shouldn't eat lots of cakes.   Same for ALL people (no -s): He should go to bed.","Question: Should I take medicine? Yes, you should. / No, you shouldn't.","could = the past of can: Now: I can swim. When I was four: I could paint, but I couldn't read.  couldn't = the past of can't.","Question in the past: Could you swim when you were four? Yes, I could. / No, I couldn't.","After should / could: the BASE verb (no to, no -s, no -ing): You should drink. He couldn't eat."],"signal":"good / bad idea, advice, 'What's the matter?' → should / shouldn't.   when I was five / last year / many years ago + ability → could / couldn't.","ru":"Russian «тебе надо / следует» is one word. In English should never changes: I / he / they should. Never 'should to', never 'should goes'.","oops":["You should to drink water. → You should drink water.","He should goes to bed. → He should go to bed.","Yesterday I can't eat. → Yesterday I couldn't eat.","She could swam when she was four. → She could swim when she was four."]},"hasBig":true,"big":[["c","Max has a stomachache. He ___ drink water.",["should","shouldn't"],0,"good idea → should"],["c","He ___ eat chocolates.",["should","shouldn't"],1,"bad idea → shouldn't"],["c","You should ___ to bed.",["go","to go","goes"],0,"should + base verb"],["c","When I was four, I ___ read.",["can't","couldn't"],1,"past → couldn't"],["c","___ you swim when you were four?",["Can","Could"],1,"past question → Could"],["c","He ___ eat his dinner yesterday. (not able)",["can't","couldn't"],1,"yesterday → couldn't"],["r","Find the mistake: You should to see a doctor.","You should see a doctor."],["r","Find the mistake: She should goes to bed.","She should go to bed."],["r","Find the mistake: Yesterday I can swim.","Yesterday I could swim."],["r","Give advice: I have a sore throat.","You should take medicine. / You should stay at home."],["r","Give advice: I have a cold. (not)","You shouldn't go to school."],["r","Say: when I was five / read (not)","When I was five, I couldn't read."],["p","g-k-headache","What's the matter?","I have a headache. I should take a rest."],["p","g-k-stomachache","What's the matter?","I have a stomachache. I shouldn't eat cakes."],["p","g-k-earache","What's the matter?","I have an earache. I should see a doctor."],["p","g-k-sore-throat","What's the matter?","I have a sore throat. I should drink warm tea."],["p","g-k-cold","What's the matter?","I have a cold. I should stay in bed."]],"cb":[[92,"Words and story"],[93,"Grammar"],[94,"Grammar and song"]],"wb":"Workbook pp. 86–88 and Grammar Time p. 129","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 92): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 92): listen, read in roles, act it out","Grammar (p. 93): should / shouldn't and could / couldn't. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 94): Look at the pictures: I've got an earache. — You should see a doctor. I've got a sore throat. — You should take medicine. Max has a stomachache: He should drink water. He shouldn't eat chocolates.. Song: When I was a baby","Grammar Time (Workbook p. 129): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Translation check: 10 sentences + 2 challenge"]}},{"n":3,"subtopic":"Unit 12B · What's the matter?","kd":{"kind":"B","label":"Unit 12B · What's the matter?","goal":"le and al endings. Read an information leaflet: How to stay healthy. Say what you do to be healthy. because and so.","tr":[["Как остаться здоровым?","How to stay healthy?"],["Мы все хотим быть в форме и здоровыми.","We all want to be fit and healthy."],["Телевизор не сделает тебя сильным, а спорт сделает.","Watching TV won't make you fit, but playing sports will."],["Регулярные упражнения дают тебе больше энергии.","Regular exercise gives you more energy."],["Пей много воды и молока.","Drink lots of water and milk."],["В газировке много сахара.","Fizzy drinks contain lots of sugar."],["Молоко полезно, потому что в нём много кальция.","Milk is good because it contains lots of calcium."],["Кальций делает твои кости крепкими.","Calcium keeps your bones strong."],["В чипсах много соли, поэтому не надо есть их каждый день.","There is lots of salt in crisps, so you shouldn't eat them every day."],["Овощи и фрукты помогают оставаться здоровым.","Fruit and vegetables help you stay healthy."]],"ch":[["Ешь овощи с каждым приёмом пищи и много фруктов.","Eat vegetables with every meal and plenty of fruit."],["Я пью молоко, потому что хочу, чтобы мои кости были крепкими.","I drink milk because I want strong bones."]],"us":[["You've got a stomachache.","You have a stomachache."],["chips (crisps)","chips = potato chips; fries = French fries"],["sweets","candy"],["Mum","Mom"],["a lot of cakes","a lot of cupcakes (cake is also fine)"],["fizzy drinks","soda"]],"copy":["healthy","fit","energy","crisps (chips)","sugar","calcium","cabbage","sardine","race","cheer","tired","bet","prize","shell","whistle","dust","bush","hop","nap","rabbit"],"rwords":["healthy","fit","energy","crisps (chips)","sugar","calcium","cabbage","sardine"],"retell":["exercise","healthy diet","water and milk","sugar","calcium","fit","energy"],"rule":{"title":"should / shouldn't and could / couldn't","lines":["should = it is a good idea (advice): You should drink some water. You shouldn't eat lots of cakes.   Same for ALL people (no -s): He should go to bed.","Question: Should I take medicine? Yes, you should. / No, you shouldn't.","could = the past of can: Now: I can swim. When I was four: I could paint, but I couldn't read.  couldn't = the past of can't.","Question in the past: Could you swim when you were four? Yes, I could. / No, I couldn't.","After should / could: the BASE verb (no to, no -s, no -ing): You should drink. He couldn't eat."],"signal":"good / bad idea, advice, 'What's the matter?' → should / shouldn't.   when I was five / last year / many years ago + ability → could / couldn't.","ru":"Russian «тебе надо / следует» is one word. In English should never changes: I / he / they should. Never 'should to', never 'should goes'.","oops":["You should to drink water. → You should drink water.","He should goes to bed. → He should go to bed.","Yesterday I can't eat. → Yesterday I couldn't eat.","She could swam when she was four. → She could swim when she was four."]},"hasBig":true,"big":[["c","Which word ends in le?",["candle","sandal"],0,"candle, castle, table, people"],["c","Which word ends in al?",["animal","table"],0,"animal, hospital, cereal, sandal"],["c","cast___",["le","al"],0,"castle"],["c","hospit___",["le","al"],1,"hospital"],["c","Milk is good ___ it contains calcium.",["because","so"],0,"reason → because"],["c","There is lots of salt in crisps, ___ you shouldn't eat them every day.",["because","so"],1,"result → so"],["c","Calcium keeps your ___ strong.",["bones","hair"],0,"bones"],["c","Which is better for you?",["water","fizzy drinks"],0,"water"],["r","Say three ways to stay healthy.","Take lots of exercise. Eat a healthy diet. Drink lots of water and milk."],["r","What exercise do you do?","I ride my bike and I go swimming."],["r","Why is milk good?","Because it contains lots of calcium."],["r","Retell the leaflet in 5 sentences.","We all want to be healthy ... exercise ... healthy diet ... water and milk ... calcium ..."]],"cb":[[95,"Phonics and spelling"],[96,"Skills time: reading"],[97,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 89–91 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 95): le (candle, castle, table, people) and al (sandal, animal, hospital, cereal) endings","Reading words (p. 96): read the English and the Russian, say and repeat","Reading (p. 96): An information leaflet: How to stay healthy: listen, read aloud in pairs, answer the questions","Retell with these words: exercise, healthy diet, water and milk, sugar, calcium, fit, energy","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 97): Listening: number the pictures, and say true or false about Joe, Sarah, Ella, Pete. Speaking: What do you do to be healthy? What exercise do you do? What healthy food do you eat? How can you be more healthy?","Writing preparation (p. 97): Conjunctions join two sentences: BECAUSE shows the reason (Milk is good because it contains calcium); SO shows the result (There is lots of salt in crisps, so you shouldn't eat them every day). Put a comma before SO. The writing task is an information leaflet. The writing task is homework.","Story · The Fastest Rabbit in the Forest: look at the picture and guess; teach the new words (the Russian is in the vocabulary file); read aloud in turns; tell what happens in 5 sentences with the key words","Story: the kids close the book and retell it to a partner","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"],"story":[{"n":6,"title":"The Fastest Rabbit in the Forest","pic":"st5-06","paras":["Bim was a rabbit, and Bim was fast. Everybody in the forest knew it, because he told them every day. “I am the fastest animal here,” he said. “Nobody can beat me. Nobody has ever won a race against me.”","It was true. He had won against a dog, two birds and a young horse. After every race he sat down in the middle of the road and waited, and the animals had to cheer him. Then they went home and said nothing for a long time.","One morning an old turtle came out of the grass. His name was Momo, and he was the slowest animal in the forest. He came with his family, and nobody counted them.","“Bim,” he said, “I can beat you.”","The forest laughed. Bim laughed the loudest of all. “You are slower than the grass,” he said. “Go home before you get tired.”","“Then make a bet with me,” said Momo. “The prize is simple. The loser must take the winner across the whole forest on his back, in front of everybody.”","Bim looked at the old shell in the grass, and he thought about a very easy morning. “Tomorrow,” he said. “Pay attention, everybody. This will be the shortest race of my life.”","Every animal came. The old owl gave one long whistle, and Bim went like a stone from a hand. Momo put one foot in front of the other. The dust behind Bim was already far away.","In the middle of the forest Bim slowed down to have some fun. Then he saw something next to a bush. A shell. The same old shell, the same slow feet, walking quietly along the road in front of him.","Bim’s heart jumped. He ran. He ran harder than he had ever run in his life, and he went past Momo, and the trees turned into one green wall. Nobody could run like that. Nobody in the world.","Near the end of the road he could not run any more. He stopped and looked back. Far behind him, small and brown in the sun, Momo sat on the road. He did not move at all.","“He has given up,” said Bim. “I have won already.” The finish was ten hops away. He lay down under a tree for a short nap.","The noise woke him. It was a big noise, and it was the wrong kind of noise. The animals were shouting and jumping at the end of the road, and they were shouting a name, and the name was not his.","Bim hopped to the finish on shaking legs. Momo was sitting there in the grass with the whole forest around him, and every animal was cheering the slowest runner in the world.","“You cannot prove anything!” said Bim. “Nobody saw you go past me!” “Nobody saw me go past you,” Momo agreed.","So the fastest animal in the forest walked home very slowly, with a turtle on his back, past every animal he had ever beaten. Behind him, in the long grass, two more old shells were going quietly home to dinner."],"words":[["race","reɪs","гонка, забег","A competition to see who is the fastest."],["cheer","tʃɪə","кричать «ура», подбадривать","To shout because you are happy about somebody."],["tired","ˈtaɪəd","усталый","Needing to rest or to sleep."],["bet","bet","пари, спор","An agreement that the loser must give something to the winner."],["prize","praɪz","приз, награда","The thing that the winner gets."],["shell","ʃel","панцирь","The hard part on the outside of a turtle."],["whistle","ˈwɪsl","свист","A long high sound that you make with your mouth."],["dust","dʌst","пыль","Very small dry pieces of earth in the air."],["bush","bʊʃ","куст","A small low plant with many branches."],["hop","hɒp","прыгать, прыжок","To jump with two feet together."],["nap","næp","короткий сон","A short sleep in the day."],["rabbit","ˈræbɪt","кролик","A small animal with long ears that runs fast."]],"phrases":[["pay attention","обращать внимание","Pay attention, everybody. This will be the shortest race of my life."],["give up","сдаваться","He has given up. I have won already."]],"retell":["race","cheer","tired","bet","prize","shell","whistle"]}]}}],"goal":"Unit 11B · Unit 12A · Unit 12B"},{"n":11,"title":"Week 11","icon":"Landmark","lessons":[{"n":1,"subtopic":"Review 4 · Units 10–12","kd":{"kind":"review","label":"Review 4 · Units 10–12","goal":"No new topic: everything from Units 10–12. Mixed grammar practice on the big screen and Fluency Time.","tr":[["Я сохранил документ.","I've saved the document."],["Она ещё не сделала домашнее задание.","She hasn't done her homework yet."],["Ты видел мои колонки?","Have you seen my speakers?"],["Ты когда-нибудь был в космосе? — Нет, никогда.","Have you ever been to space? — No, I haven't."],["Я никогда не видел вулкан.","I've never seen a volcano."],["Он лазил на гору?","Has he climbed a mountain?"],["У меня болит живот. Мне надо лечь в постель.","I have a stomachache. I should go to bed."],["Тебе не надо есть пирожные.","You shouldn't eat cakes."],["Когда мне было четыре, я не умел читать.","When I was four, I couldn't read."],["Что случилось? — Я упал во дворе.","What's the matter? — I fell over in the playground."]],"ch":[["Мы уже напечатали домашнее задание, но мы ещё не убрали комнату, поэтому нам нельзя играть.","We've already printed our homework, but we haven't tidied our room, so we can't play."],["Он никогда не был в космосе, но он уже был в пустыне, и там он видел много необычных животных.","He's never been to space, but he's been to a desert, and he saw lots of unusual animals there."]],"us":[],"copy":[],"rwords":[],"retell":[],"rule":null,"hasBig":true,"big":[["c","I ___ my room yesterday.",["Past simple","Past continuous","Present perfect"],0,"yesterday → past simple"],["c","I've ___ my room. It's clean now.",["tidy","tidied"],1,"participle"],["c","Have you ___ been to a rainforest?",["ever","never"],0,"question → ever"],["c","I've ___ seen a volcano.",["ever","never"],1,"never = not ever"],["c","Max has a stomachache. He ___ eat chocolate.",["should","shouldn't"],1,"bad idea → shouldn't"],["c","When I was five I ___ swim.",["can't","couldn't"],1,"past → couldn't"],["r","Find the mistake: Have you saw my speakers?","Have you seen my speakers?"],["r","Find the mistake: Have you ever went to Egypt?","Have you ever been to Egypt?"],["r","Find the mistake: You should to see a doctor.","You should see a doctor."],["r","Find the mistake: I haven't never been to space.","I've never been to space."],["r","Say: I / not do / my homework","I haven't done my homework."],["r","Give advice: a headache","You should drink some water and go to bed."]],"cb":[[98,"Fluency Time: Describing accidents"],[99,"Project"],[100,"Review 4"],[101,"Review 4"]],"wb":"Workbook pp. 92–93 and 94–95","steps":["Warm-up: the 3 earlier sentences from the last translation check","Mini test (file): 12 questions on Units 10–12","Speaking in pairs: the speaking questions (in the answers file)","Fluency Time (p. 98): Describing accidents. What's the matter? / Where did it happen? / I fell over in the playground. / He's hurt his leg. / Take Tom to the school nurse, please. / Come on, Tom.","Project: a room cube (or for homework)","Big screen: grammar practice (which rule is it?)","Review pages (pp. 100–101) together","Check the test; each kid fixes three mistakes","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Reading 4 · Exciting places","kd":{"kind":"reading","label":"Reading 4 · Exciting places","goal":"Read, learn the key words, and retell: My life in the Arctic · Life in the Desert.","tr":[["Кирима живёт в деревне на Аляске.","Kirima lives in a village in Alaska."],["Зимой там очень холодно и всегда темно.","In winter it's very cold and dark all the time."],["Иногда мы видим красивые цвета в небе. Это северное сияние.","Sometimes we can see beautiful colors in the sky. This is the Northern lights."],["Мои друзья ходят в школу на лыжах.","My friends go to school on skis."],["Я езжу в школу на снегоходе.","I go to school by snowmobile."],["К нашей школе приходят белые медведи.","Polar bears come to our school."],["Летом снег тает, и никогда не бывает темно.","In the summer, the snow goes and it's never dark."],["Сахара — самая большая жаркая пустыня в мире.","The Sahara is the biggest hot desert in the world."],["Кактусы хранят воду в листьях.","Cacti keep water in their leaves."],["Многие животные спят днём и выходят ночью.","Many animals sleep during the day and come out at night."]],"ch":[["Зимой в Арктике температура около минус тридцати градусов, поэтому мы носим тёплую одежду и ездим на снегоходе.","In winter in the Arctic, the temperature is about minus 30 degrees, so we wear warm clothes and go by snowmobile."],["Верблюды могут пить очень много воды и потом долго не пить, поэтому они идеальны для пустыни.","Camels can drink lots of water and then not drink for a long time, so they're perfect for the desert."]],"us":[],"copy":["Arctic","snowmobile","polar bear","dog sled","Northern lights","temperature","desert","survive","cactus","nocturnal"],"rwords":["Arctic","snowmobile","polar bear","dog sled","Northern lights","temperature","desert","survive","cactus","nocturnal"],"retell":["Arctic","dark all the time","snowmobile","dog sled","summer","desert","cactus","nocturnal","camel"],"rule":null,"hasBig":true,"big":[["r","How does Kirima go to school?","By snowmobile."],["r","When is it dark all the time in the Arctic?","In winter."],["r","Who drives Kirima's dog sled?","Her father."],["r","Do Eskimo children go to school in the summer?","No, they don't. They travel with their parents to hunt and fish."],["r","What is the biggest hot desert?","The Sahara."],["r","What is the coldest place in the world?","Antarctica (it is a desert covered with snow and ice)."],["r","How do cacti survive?","They keep rain water in their leaves."],["r","What does \"nocturnal\" mean?","Sleeping in the day and coming out at night."],["r","Have you ever been to a desert?","Yes, I have. / No, I haven't."],["r","Retell one text in 5 sentences.","Kirima lives ... in winter ... in summer ... / A desert is ... plants ... animals ..."]],"cb":[[102,"Exciting places (1)"],[103,"Exciting places (2)"]],"wb":"No Workbook pages. Homework: write 5 sentences in the copybook (the retell).","steps":["Warm-up: the 3 earlier sentences from the last translation check","Pre-teach the key words: read the English and the Russian from the vocabulary file","Look at the pictures and guess: What is the text about?","Listen and read the first text (twice: once to listen, once in pairs); answer the questions","The same for the second text","Retell with these words: Arctic, dark all the time, snowmobile, dog sled, summer, desert, cactus, nocturnal, camel","Big screen: comprehension questions","Translation check: 10 sentences + 2 challenge"]}},{"n":3,"subtopic":"Unit 13A · Can you help me?","kd":{"kind":"A","label":"Unit 13A · Can you help me?","goal":"Kitchen words (making smoothies). Object pronouns (me, you, him, her, it, us, them). Relative pronouns who and which.","tr":[["Ты можешь помочь мне сделать смузи?","Can you help me make some smoothies?"],["Достань молоко из холодильника и налей его в блендер.","Get some milk from the fridge and pour it in the blender."],["Вот клубника. Нарежь её, пожалуйста.","Here are some strawberries. Chop them up, please."],["Я помогу ей.","I'll help her."],["Отдай их Лео, когда закончишь.","Give them to Leo when you've finished."],["Это мальчик, который не закрыл крышку.","This is the boy who didn't put the lid on."],["Это смузи, который был в блендере.","This is the smoothie which was in the blender."],["Мы видели их, а они видели нас.","We saw them, and they saw us."],["Я не могу найти её.","I can't find her."],["Прости! Я всё вытру.","Sorry! I'll clean it up."]],"ch":[["Это девочка, которая купила бананы, а это магазин, который их продаёт.","This is the girl who bought the bananas, and this is the store which sells them."],["Я не вижу брата, но я слышу его, поэтому позови его и попроси помочь нам.","I can't see my brother, but I can hear him, so call him and ask him to help us."]],"us":[["Mum","Mom"],["fireman","firefighter (we use both)"],["£136,000","$136,000 (dollars)"],["programme","program"],["lorry","truck"],["a petrol station","a gas station"]],"copy":["smoothie","milk","fridge","pour","blender","strawberry","chop","lid","mango","peel","banana","sugar","fruit","clean up","kitchen","help"],"rwords":[],"retell":[],"rule":{"title":"Object pronouns and relative pronouns (who / which)","lines":["Subject → object:  I → ME · you → YOU · he → HIM · she → HER · it → IT · we → US · they → THEM.   The object pronoun comes AFTER the verb or a preposition: Please help me. I can see him. Pour it in the blender. Chop them up.","Why use them? To avoid repeating the noun: Can you get some milk? Then pour IT in the blender. (it = milk)","WHO joins two sentences about PEOPLE: This is the boy who didn't put the lid on.   WHICH joins two sentences about THINGS: This is the smoothie which was in the blender.","who / which replace he / she / it / they, so do NOT say it twice: This is the boy who he made the smoothie. ✗"],"signal":"After a verb or 'to / with / for': me, you, him, her, it, us, them.  A person + more information → who.  A thing + more information → which.","ru":"In Russian the case changes the word (мне, ему, ей, им). In English only the pronoun changes: I → me, he → him. And «который» = WHO (person) or WHICH (thing).","oops":["Please help I. → Please help me.","I can see he. → I can see him.","Chop the strawberries and pour they in. → Chop the strawberries and pour them in.","This is the boy which made the smoothie. → This is the boy who made the smoothie."]},"hasBig":true,"big":[["c","Please help ___.",["I","me"],1,"object → me"],["c","I can see ___. (my brother)",["he","him"],1,"object → him"],["c","Pour ___ in the blender. (the milk)",["it","them"],0,"milk = it"],["c","Chop ___ up. (the strawberries)",["it","them"],1,"strawberries = them"],["c","This is the boy ___ made the smoothie.",["who","which"],0,"a person → who"],["c","This is the smoothie ___ was in the blender.",["who","which"],1,"a thing → which"],["r","Find the mistake: Please help I with my homework.","Please help me with my homework."],["r","Find the mistake: This is the boy which dropped the milk.","This is the boy who dropped the milk."],["r","Find the mistake: Chop the strawberries and pour they in.","Chop the strawberries and pour them in."],["r","Replace the noun: I can see Amy.","I can see her."],["r","Replace the noun: We saw the boys.","We saw them."],["r","Join: This is the dog. It drank the milk.","This is the dog which drank the milk."],["p","g-k-blender","What is it?","It's a blender."],["p","strawberry","What is it?","It's a strawberry."],["p","mango","What is it?","It's a mango."],["p","fridge","What is it?","It's a fridge."],["p","g-k-smoothie","What did the boy make?","This is the boy who made the smoothie."]],"cb":[[104,"Words and story"],[105,"Grammar"],[106,"Grammar and song"]],"wb":"Workbook pp. 96–98 and Grammar Time p. 130","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 104): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 104): listen, read in roles, act it out","Grammar (p. 105): Object pronouns and relative pronouns (who / which). Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 106): The story of a smoothie: This is the boy who made the smoothie. This is the mum who bought the bananas and milk. This is the supermarket which sold the bananas. This is the ship which carried the bananas.. Song: This is the boy ...","Grammar Time (Workbook p. 130): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}}],"goal":"Review 4 · Reading 4 · Unit 13A"},{"n":12,"title":"Week 12","icon":"Users","lessons":[{"n":1,"subtopic":"Unit 13B · Can you help me?","kd":{"kind":"B","label":"Unit 13B · Can you help me?","goal":"el and il endings. Read two true stories: Young Heroes. Talk about jobs. Sub clauses with who / which.","tr":[["Мальчик помогает пострадавшим от землетрясения.","A boy helps earthquake victims."],["Чарли смотрел новости по телевизору о землетрясении в Гаити.","Charlie watched the news on TV about an earthquake in Haiti."],["Он захотел помочь людям.","He wanted to help the people."],["Он решил проехать на велосипеде вокруг парка и собирать деньги.","He decided to do a sponsored bike ride around his local park to raise money."],["Многие люди дали ему деньги.","Lots of people sponsored him."],["Райану было шесть лет, когда учительница рассказала о большой проблеме.","Ryan was six years old when his teacher told his class about a big problem."],["Во многих местах Африки нет чистой воды.","Many places in Africa don't have clean water."],["Он делал домашние дела, чтобы заработать деньги.","He did chores to earn money."],["Он собрал две тысячи долларов, чтобы построить колодец.","He raised $2,000 to pay for a well."],["Потом он создал благотворительный фонд.","Then he started a charity."]],"ch":[["Чарли было всего семь лет, но он хотел помочь людям, которых он никогда не видел.","Charlie was only seven, but he wanted to help people he had never seen."],["Райан — мальчик, который начал сбор денег, и его фонд собрал миллионы долларов.","Ryan is the boy who started a charity, and his foundation has raised millions of dollars."]],"us":[["Mum","Mom"],["fireman","firefighter (we use both)"],["£136,000","$136,000 (dollars)"],["programme","program"],["lorry","truck"],["a petrol station","a gas station"]],"copy":["hero","earthquake","sponsored","bike ride","raise money","charity","well","chores"],"rwords":["hero","earthquake","sponsored","bike ride","raise money","charity","well","chores"],"retell":["earthquake","bike ride","charity","raise money","well","chores","clean water"],"rule":{"title":"Object pronouns and relative pronouns (who / which)","lines":["Subject → object:  I → ME · you → YOU · he → HIM · she → HER · it → IT · we → US · they → THEM.   The object pronoun comes AFTER the verb or a preposition: Please help me. I can see him. Pour it in the blender. Chop them up.","Why use them? To avoid repeating the noun: Can you get some milk? Then pour IT in the blender. (it = milk)","WHO joins two sentences about PEOPLE: This is the boy who didn't put the lid on.   WHICH joins two sentences about THINGS: This is the smoothie which was in the blender.","who / which replace he / she / it / they, so do NOT say it twice: This is the boy who he made the smoothie. ✗"],"signal":"After a verb or 'to / with / for': me, you, him, her, it, us, them.  A person + more information → who.  A thing + more information → which.","ru":"In Russian the case changes the word (мне, ему, ей, им). In English only the pronoun changes: I → me, he → him. And «который» = WHO (person) or WHICH (thing).","oops":["Please help I. → Please help me.","I can see he. → I can see him.","Chop the strawberries and pour they in. → Chop the strawberries and pour them in.","This is the boy which made the smoothie. → This is the boy who made the smoothie."]},"hasBig":true,"big":[["c","Which word ends in el?",["camel","pencil"],0,"camel, tunnel, towel, travel"],["c","Which word ends in il?",["towel","April"],1,"pencil, pupil, April, lentils"],["c","pup___",["el","il"],1,"pupil"],["c","tunn___",["el","il"],0,"tunnel"],["c","A sub clause gives ___.",["more information","the title"],0,"more information"],["c","The fireman ___ has a dangerous job rescues people.",["who","which"],0,"a person → who"],["c","The earthquake, ___ was very strong, happened in Haiti.",["who","which"],1,"a thing → which"],["c","Charlie raised money for ___.",["UNICEF","a well"],0,"UNICEF"],["c","Ryan raised money for ___.",["a well in Uganda","a school in Haiti"],0,"a well near a school in Uganda"],["r","Why do these boys are heroes?","They helped other people. Charlie raised money for earthquake victims and Ryan made clean water."],["r","Think of a job: Does he wear a uniform?","Does he wear a uniform? Yes, he does. / No, he doesn't."],["r","Retell the text in 5 sentences.","Charlie ... earthquake ... bike ride ... Ryan ... well ... charity ..."]],"cb":[[107,"Phonics and spelling"],[108,"Skills time: reading"],[109,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 99–101 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 107): el (tunnel, camel, towel, travel) and il (lentils, pencil, April, pupil) endings","Reading words (p. 108): read the English and the Russian, say and repeat","Reading (p. 108): Two factual accounts: Young Heroes: listen, read aloud in pairs, answer the questions","Retell with these words: earthquake, bike ride, charity, raise money, well, chores, clean water","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 109): Listening: number the places (fire station, police station, hospital, school) and match the jobs. Speaking: think of a job. Does he work with a computer / people? Does he wear a uniform / hat? (nurse, teacher, fireman, pilot, farmer, actor, singer, waiter)","Writing preparation (p. 109): A sub clause gives more information: This doctor, who works in a hospital, helps children. We use WHICH for things and WHO for people, and put two commas around the new information. The writing task is an interview. The writing task is homework.","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Unit 14A · We were fishing","kd":{"kind":"A","label":"Unit 14A · We were fishing","goal":"Family words (in-laws, wife, husband, son, daughter, niece, nephew). Past continuous: What were you doing? I was looking at photos. Dates: the twenty-second of June. I was born in ...","tr":[["Почему ты плачешь, Холли?","Why are you crying, Holly?"],["Потому что вы все уезжаете в Австралию через две недели.","Because you're all going back to Australia in two weeks' time."],["Давай посмотрим фотоальбом.","Let's look at the photo album."],["Мой смешной сын не делал смузи, он устраивал беспорядок.","My funny son wasn't making a smoothie. He was making a mess."],["Мы ловили рыбу вместе.","We were fishing together."],["Что вы делали вчера в три часа?","What were you doing at three o'clock yesterday?"],["Я смотрел фотографии.","I was looking at photos."],["Они навещали друга в больнице.","They were visiting a friend in the hospital."],["Они не шли в кино.","They weren't going to the movies."],["Мой папа родился в тысяча девятьсот семьдесят первом году.","My dad was born in 1971."]],"ch":[["Вчера в три часа я читал новую книгу, а моя сестра делала фотоальбом на компьютере.","Yesterday at three o'clock I was reading a new book, and my sister was making a photo album on the computer."],["Мой дедушка родился девятого июля тысяча девятьсот сорок пятого года, а моя мама — в марте.","My grandpa was born on July 9th, 1945, and my mom was born in March."]],"us":[["Mum","Mom"],["Dad was born on 9th July","Dad was born on July 9th (in the USA we say: July ninth)"],["22nd June 1997","June 22nd, 1997 (American dates start with the month)"],["the twenty-second of June","June twenty-second"],["theatre","theater"],["favourite","favorite"]],"copy":["mother-in-law","father-in-law","wife","husband","son","daughter","niece","nephew","photo album","memory","born","date","birthday","happy","sad","together"],"rwords":[],"retell":[],"rule":{"title":"Past continuous · dates · I was born ...","lines":["Past continuous = was / were + verb-ing: an action in progress at a certain time in the past.  What were you doing at 3 o'clock yesterday? I was looking at photos. They were visiting a friend.","No: wasn't / weren't + -ing. He wasn't making a smoothie. He was making a mess.   Question: Was he making a smoothie? Yes, he was. / No, he wasn't.  Were they going to the theater? No, they weren't.","Present continuous (now): am / is / are + -ing.  Past continuous (then): was / were + -ing.","Dates in American English: we SAY 'July ninth, nineteen seventy-one', we write July 9th, 1971 (the book also uses: the ninth of July). I was born IN 1971 (a year / a month) but ON July 9th (a date)."],"signal":"at 3 o'clock yesterday / at that moment / when I came in → past continuous (the action was in progress).","ru":"In Russian «я смотрел фотографии» shows an action in progress without any special form. In English you need WAS / WERE + -ing (I was looking). Do not forget was / were.","oops":["I looking at photos yesterday. → I was looking at photos yesterday.","They was fishing. → They were fishing.","What you were doing? → What were you doing?","I was born at 1971. → I was born in 1971."]},"hasBig":true,"big":[["c","At 3 o'clock yesterday I ___ at photos.",["looked","was looking"],1,"in progress at a time → was looking"],["c","They ___ fishing.",["was","were"],1,"they → were"],["c","He ___ making a smoothie. (not)",["wasn't","weren't"],0,"he → wasn't"],["c","___ you going to the theater?",["Was","Were"],1,"you → Were"],["c","Yes, they ___.",["was","were"],1,"short answer → were"],["c","What ___ you doing?",["was","were"],1,"you → were"],["r","Find the mistake: I looking at photos yesterday.","I was looking at photos yesterday."],["r","Find the mistake: They was fishing.","They were fishing."],["r","Find the mistake: I was born at 1971.","I was born in 1971."],["r","Say: Amy / make a photo album (yesterday at 3)","Amy was making a photo album at three o'clock yesterday."],["r","Say your birthday in American English.","My birthday is on June twenty-second."],["r","Ask: Max / read a book?","Was Max reading a book?"],["p","g-k-photo-album","What are they looking at?","They are looking at a photo album."],["p","g-k-husband-and-wife","Who are they?","They are a husband and a wife."],["p","g-k-toddler","Who is he? How old is he?","He's a toddler. He's two."]],"cb":[[110,"Words and story"],[111,"Grammar"],[112,"Grammar and song"]],"wb":"Workbook pp. 102–104 and Grammar Time p. 130","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 110): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 110): listen, read in roles, act it out","Grammar (p. 111): Past continuous · dates · I was born .... Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 112): Read the dates and ask: When was Paul born? He was born on the third of March, 1999. Then write when you and your family were born. Sing: What was Jim doing when Sally was born? He was playing.. Song: When Sally was born","Grammar Time (Workbook p. 130): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":3,"subtopic":"Unit 14B · We were fishing","kd":{"kind":"B","label":"Unit 14B · We were fishing","goal":"tion and shion endings. Read a poem: My relatives are coming! Talk about happy memories. Verses and rhymes.","tr":[["Мои родственники приезжают!","My relatives are coming!"],["Мы готовимся к особенному дню.","We're getting ready for a really special day."],["Тётя, дядя и двоюродные брат с сестрой приедут на неделю.","My aunt, my uncle, and my cousins will be here for a week."],["Двоюродному брату Биллу только что исполнилось два года.","My cousin Bill has just turned two."],["Он любит кричать, как все малыши.","He likes to scream and shout, like normal toddlers."],["Он очень милый и учится вести себя хорошо.","He's really fun and cute, and he's learning to be good."],["Наш дом довольно маленький, поэтому будет тесно.","Our house is quite small, so it will be a squeeze."],["Будут очереди в ванную.","There will be queues for the bathroom."],["Дом будет таким шумным!","The house will be so noisy!"],["Когда они уедут, я буду так скучать по ним!","When they go home, I'll miss them all so much!"]],"ch":[["Мы останемся на связи, потому что мне нравится говорить с ними.","We'll stay in touch because I like to talk to them."],["Дом будет таким тихим, когда они уедут, и я буду очень скучать.","The house will be so quiet when they go, and I'll miss them very much."]],"us":[["Mum","Mom"],["Dad was born on 9th July","Dad was born on July 9th (in the USA we say: July ninth)"],["22nd June 1997","June 22nd, 1997 (American dates start with the month)"],["the twenty-second of June","June twenty-second"],["theatre","theater"],["favourite","favorite"]],"copy":["relatives","toddler","normal","cute","squeeze","queue","stay in touch","miss someone","mirror","palace","basket","tailor","cloth","gold","needle","sew","wave","point","silent","coat"],"rwords":["relatives","toddler","normal","cute","squeeze","queue","stay in touch","miss someone"],"retell":["relatives","toddler","squeeze","queue","noisy","stay in touch","miss"],"rule":{"title":"Past continuous · dates · I was born ...","lines":["Past continuous = was / were + verb-ing: an action in progress at a certain time in the past.  What were you doing at 3 o'clock yesterday? I was looking at photos. They were visiting a friend.","No: wasn't / weren't + -ing. He wasn't making a smoothie. He was making a mess.   Question: Was he making a smoothie? Yes, he was. / No, he wasn't.  Were they going to the theater? No, they weren't.","Present continuous (now): am / is / are + -ing.  Past continuous (then): was / were + -ing.","Dates in American English: we SAY 'July ninth, nineteen seventy-one', we write July 9th, 1971 (the book also uses: the ninth of July). I was born IN 1971 (a year / a month) but ON July 9th (a date)."],"signal":"at 3 o'clock yesterday / at that moment / when I came in → past continuous (the action was in progress).","ru":"In Russian «я смотрел фотографии» shows an action in progress without any special form. In English you need WAS / WERE + -ing (I was looking). Do not forget was / were.","oops":["I looking at photos yesterday. → I was looking at photos yesterday.","They was fishing. → They were fishing.","What you were doing? → What were you doing?","I was born at 1971. → I was born in 1971."]},"hasBig":true,"big":[["c","Which word ends in tion?",["addition","fashion"],0,"addition, subtraction, invitation"],["c","Which word ends in shion?",["cushion","invitation"],0,"fashion, cushion"],["c","inv___",["itation","itashion"],0,"invitation"],["c","fa___",["tion","shion"],1,"fashion"],["c","A poem has lines in different parts. These parts are called ___.",["verses","chapters"],0,"verses"],["c","Which two words rhyme?",["small / all","small / big"],0,"small / all"],["c","Bill is a ___.",["toddler","baby"],0,"a toddler (two years old)"],["c","Many people in the house = ___",["a squeeze","a queue"],0,"a squeeze (little space)"],["r","What is your happiest memory?","It's when I got my new bike ..."],["r","Who was born on 3rd March 1999?","Paul."],["r","Ask a friend about a happy memory.","What is your happiest memory? When was it?"],["r","Retell the poem in 5 sentences.","The relatives are coming ... Bill is a toddler ... The house will be noisy ... They will go home ... I will miss them."]],"cb":[[113,"Phonics and spelling"],[114,"Skills time: reading"],[115,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 105–107 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 113): tion (addition, subtraction, invitation) and shion (fashion, cushion) endings","Reading words (p. 114): read the English and the Russian, say and repeat","Reading (p. 114): A poem: My relatives are coming!: listen, read aloud in pairs, answer the questions","Retell with these words: relatives, toddler, squeeze, queue, noisy, stay in touch, miss","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 115): Listening: number the pictures and say who: helped look after animals / a child, went to a new country, had a party, had a brother, went surfing. Speaking: What is your happiest memory? When was it? Describe what happened. How did you feel?","Writing preparation (p. 115): A poem is divided into verses; some poems rhyme (the last words of the lines sound the same: all / small). The writing task is to complete a poem. The writing task is homework.","Story · The King Who Loved Clothes: look at the picture and guess; teach the new words (the Russian is in the vocabulary file); read aloud in turns; tell what happens in 5 sentences with the key words","Story: the kids close the book and retell it to a partner","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"],"story":[{"n":7,"title":"The King Who Loved Clothes","pic":"st5-07","paras":["The king of Turon loved clothes more than anything in the world. He had one room for his coats and one room for his hats. He changed his clothes six times every day. Every time he stood in front of the big mirror for an hour.","One winter two strangers came to the palace. They had an empty basket. “We are tailors,” they said. “We make a very special cloth. It is light and it is beautiful. And it has one strange thing about it.”","“What thing?” asked the king. “If a man is clever, he will see the cloth. If a man is stupid, he will see nothing.”","The king sat up in his chair. If he wore that cloth, he would find every stupid man in his palace in one day. “Start today,” he said. “Take everything you need.”","They took gold. They took ten long needles. They took a big room, and they locked the door. Every morning the two men came back and worked all day. Nobody could go in.","After a week the king sent his oldest servant to look. The old man went into the room. The table was empty. The two tailors were moving their hands over the empty table, and they were smiling.","“Look at these flowers,” said one man. “Look at this silk! Take care of it.”","The old servant looked and looked. He saw nothing at all. Then he thought about his house, and his family, and his forty years of work.","“Beautiful,” he said. “The flowers are very beautiful.”","Then more men came, one by one. Every man stood in the empty room. Every man saw nothing. And every man said the same thing, because nobody wanted to be the stupid one.","On the last night the two tailors sewed nothing with their empty needles.","In the morning they dressed the king. The king stood in front of the mirror with no clothes on, and he looked at himself for a long time. “Well,” he said. “It is lighter than I thought.”","Then he walked out into the street. The whole city was waiting for him. Men waved their hats. Women shouted, “Look at the gold flowers on his new coat!”","A small boy was sitting on his father’s shoulders. He looked at the king for a long time. Then he pointed at him. “He has no clothes on,” said the boy.","The street went silent. Then one man laughed. Then another man laughed. Soon the whole street was laughing at the king.","And behind the people, two strangers were walking out of the city with a very heavy basket.","The king did not stop. He walked to the end of the road with his head high, because if he stopped now, the boy was right."],"words":[["mirror","ˈmɪrə","зеркало","Glass that shows you your own face."],["palace","ˈpælɪs","дворец","The big house where a king lives."],["basket","ˈbɑːskɪt","корзина","A thing made of thin wood that you carry things in."],["tailor","ˈteɪlə","портной","A person who makes clothes."],["cloth","klɒθ","ткань","The material that clothes are made of."],["gold","ɡəʊld","золото","A very expensive yellow metal."],["needle","ˈniːdl","игла","A thin sharp thing that you sew with."],["sew","səʊ","шить","To make or join clothes with a needle."],["wave","weɪv","махать","To move your hand or a thing in the air."],["point","pɔɪnt","показывать пальцем","To show something with your finger."],["silent","ˈsaɪlənt","тихий, безмолвный","With no sound at all."],["coat","kəʊt","пальто","Clothes that you wear over everything else."]],"phrases":[["take care of","заботиться о","Look at this silk. Take care of it."],["one by one","по одному","Then more men came, one by one."]],"retell":["mirror","palace","basket","tailor","cloth","gold","needle"]}]}}],"goal":"Unit 13B · Unit 14A · Unit 14B"},{"n":13,"title":"Week 13","icon":"BookOpen","lessons":[{"n":1,"subtopic":"Unit 15A · Good news, bad news","kd":{"kind":"A","label":"Unit 15A · Good news, bad news","goal":"Jobs and workplaces. Past simple and past continuous together: When I was working, the phone rang. Comma after When at the start.","tr":[["У твоего папы важная новость.","Your dad has something important to tell you."],["Когда я работал сегодня утром, зазвонил телефон.","When I was working this morning, the phone rang."],["Они улыбались, когда я вошёл.","They were smiling when I went in."],["У меня новая работа в Австралии.","I have a new job in Australia."],["Вам придётся сменить школу.","You'll have to change schools."],["Я ждал в библиотеке, когда вошёл писатель.","I was waiting in the library when the author came in."],["Секретарь печатала, когда позвонил её начальник.","The secretary was typing when her boss phoned."],["Футболист бежал, когда упал.","The soccer player was running when he fell."],["Механик чинил машину, когда пришёл клиент.","The mechanic was repairing the car when the customer arrived."],["Они едут к своим двоюродным братьям.","They're going to see their cousins."]],"ch":[["Когда мы смотрели телевизор, зазвонил телефон, и мы все побежали к нему.","When we were watching TV, the phone rang, and we all ran to it."],["Мы собирали вещи, когда папа сказал, что он получил новую работу, и мы очень обрадовались.","We were packing when Dad said he had a new job, and we were very happy."]],"us":[["Mum","Mom"],["a better job in Australia","a better job in Australia (same)"],["football","soccer"],["phone (verb)","call"],["the phone rang","the phone rang (same)"],["favourite","favorite"]],"copy":["boss","office","builder","vet","journalist","secretary","dentist","receptionist","mechanic","author","job","news","phone","wish","fish","angry"],"rwords":[],"retell":[],"rule":{"title":"Past simple and past continuous (when) · there / they're / their","lines":["Past continuous = the LONGER action in progress (was / were + -ing). Past simple = the SHORT action that happened in the middle. When I was working, the phone rang. They were smiling when I went in.","WHEN can go at the beginning or in the middle: I was eating when he arrived. = When I was eating, he arrived.  After a beginning WHEN-part, put a comma.","WAS / WERE + -ing for the long action; the SHORT action is in the past simple (rang, fell, came in).","THERE (a place; there is / there are) · THEY'RE (= they are) · THEIR (belonging to them). They sound the same but are spelled differently: There is some good news. They're very happy. They will be with their cousins.","Also: see / sea · hear / here · wear / where · write / right."],"signal":"when + a short event (the phone rang) → past simple;   the longer action at that time (I was working) → past continuous.","ru":"In Russian «когда я работал, зазвонил телефон» uses the same past for both. In English: long action = was working, short action = rang.","oops":["When I worked, the phone was ringing. → When I was working, the phone rang.","I was wait at the library when the author came in. → I was waiting at the library when the author came in.","Their going to see there cousins. → They're going to see their cousins.","Where do you see? (to look) → Where ... / What can you see?"]},"hasBig":true,"big":[["c","When I ___, the phone rang.",["was working","worked"],0,"the long action → was working"],["c","When I was working, the phone ___.",["rang","was ringing"],0,"the short action → rang"],["c","They ___ smiling when I went in.",["was","were"],1,"they → were"],["c","I was eating ___ he arrived.",["when","then"],0,"when"],["c","They sound the same: There / They're / Their. \"___ going to see their cousins.\"",["They're","Their","There"],0,"They are → They're"],["c","They will be with ___ cousins.",["they're","their","there"],1,"belonging → their"],["r","Find the mistake: I was wait at the library when the author came in.","I was waiting at the library when the author came in."],["r","Find the mistake: Their going to see there cousins.","They're going to see their cousins."],["r","Find the mistake: When I was working the phone rang.","When I was working, the phone rang."],["r","Say: the secretary / type / the boss phoned","The secretary was typing when her boss phoned."],["r","Say with When at the beginning: I was waiting at the library when the author came in.","When I was waiting at the library, the author came in."],["r","Ask: what / you / do / at 5 yesterday","What were you doing at five o'clock yesterday?"],["p","vet","What is it?","It's a vet."],["p","dentist","What is it?","It's a dentist."],["p","mechanic","What is it?","It's a mechanic."],["p","builder","What is it?","It's a builder."],["p","g-k-journalist","What is it?","It's a journalist."],["p","g-k-receptionist","What is it?","It's a receptionist."]],"cb":[[116,"Words and story"],[117,"Grammar"],[118,"Grammar and song"]],"wb":"Workbook pp. 108–110 and Grammar Time p. 131","steps":["Warm-up: the 3 earlier sentences from the last translation check","Words (p. 116): read the English and the Russian from the vocabulary file, say and repeat","Story (p. 116): listen, read in roles, act it out","Grammar (p. 117): Past simple and past continuous (when) · there / they're / their. Teach it with the rule card: the formula, the signal words, the Russian comparison, the common mistakes","Big screen: practice the rule (choose the form, find the mistake, say it)","Grammar 2 and song (p. 118): Match and say: I was waiting at the library when the author came in. The secretary was typing when her boss phoned. Then write the sentences with When at the beginning: When I was waiting at the library, the author came in.. Song: They're nearly there!","Grammar Time (Workbook p. 131): do the exercises for this unit","Copybook: the kids write today's words and 3 sentences with the rule","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Unit 15B · Good news, bad news","kd":{"kind":"B","label":"Unit 15B · Good news, bad news","goal":"Homophones: there / they're / their; see / sea, hear / here, wear / where, write / right. Read a traditional story: Three Wishes. Say what you wish for. Speech marks.","tr":[["Давным-давно жил бедный рыбак.","Once upon a time, there was a poor fisherman."],["Его жена часто сердилась, потому что он ловил мало рыбы.","His wife was often angry because he didn't catch many fish."],["Однажды маленькая рыбка прыгнула в его сеть.","One day, a little fish jumped into his net."],["Рыбка заговорила: «Брось меня обратно в море, и я исполню три желания».","The fish spoke: \"Throw me back in the sea, and I will give you three wishes.\""],["Рыбак был очень удивлён.","The fisherman was very surprised."],["«Жаль, что у нас нет колбасы вместо хлеба и воды», — сказал он.","\"I wish we had sausages instead of bread and water,\" he said."],["Вдруг на тарелке появились три вкусные сосиски.","Suddenly, three delicious sausages appeared on his plate."],["Жена закричала: «Глупый! Я бы хотела, чтобы сосиски были на конце твоего носа!»","His wife shouted, \"You silly man! I wish those sausages were on the end of your nose!\""],["Она тянула и тянула, но не смогла их снять.","She pulled and pulled, but she couldn't get them off."],["Последнее желание: чтобы сосиски исчезли.","The last wish was for the sausages to go away."]],"ch":[["Рыбак больше никогда не видел эту рыбку, потому что у него не осталось желаний.","The fisherman never saw the fish again because he had no more wishes."],["Мораль сказки: думай, о чём ты просишь, и не сердись на людей.","The moral of the story: think about what you wish for, and don't be angry with people."]],"us":[["Mum","Mom"],["a better job in Australia","a better job in Australia (same)"],["football","soccer"],["phone (verb)","call"],["the phone rang","the phone rang (same)"],["favourite","favorite"]],"copy":["fisherman","speak (spoke)","silly","surprised","sausage","delicious","wish for","pull","cage","tiger","goat","jackal","buffalo","thirsty","hungry","stick","shade","shut","lock","corner"],"rwords":["fisherman","speak (spoke)","silly","surprised","sausage","delicious","wish for","pull"],"retell":["fisherman","wife","three wishes","sausages","nose","silly","last wish","disappear"],"rule":{"title":"Past simple and past continuous (when) · there / they're / their","lines":["Past continuous = the LONGER action in progress (was / were + -ing). Past simple = the SHORT action that happened in the middle. When I was working, the phone rang. They were smiling when I went in.","WHEN can go at the beginning or in the middle: I was eating when he arrived. = When I was eating, he arrived.  After a beginning WHEN-part, put a comma.","WAS / WERE + -ing for the long action; the SHORT action is in the past simple (rang, fell, came in).","THERE (a place; there is / there are) · THEY'RE (= they are) · THEIR (belonging to them). They sound the same but are spelled differently: There is some good news. They're very happy. They will be with their cousins.","Also: see / sea · hear / here · wear / where · write / right."],"signal":"when + a short event (the phone rang) → past simple;   the longer action at that time (I was working) → past continuous.","ru":"In Russian «когда я работал, зазвонил телефон» uses the same past for both. In English: long action = was working, short action = rang.","oops":["When I worked, the phone was ringing. → When I was working, the phone rang.","I was wait at the library when the author came in. → I was waiting at the library when the author came in.","Their going to see there cousins. → They're going to see their cousins.","Where do you see? (to look) → Where ... / What can you see?"]},"hasBig":true,"big":[["c","see / sea: \"I can ___ a boat.\"",["see","sea"],0,"see = look"],["c","see / sea: \"We swam in the ___.\"",["see","sea"],1,"sea = the water"],["c","hear / here: \"Come ___!\"",["hear","here"],1,"here = in this place"],["c","wear / where: \"___ is the bus station?\"",["Wear","Where"],1,"where = question about a place"],["c","write / right: \"I write with my ___ hand.\"",["write","right"],1,"right hand"],["c","Speech marks: the comma goes ___.",["inside the speech marks","outside"],0,"inside"],["c","The fisherman's first wish was for ___.",["sausages","money"],0,"sausages"],["c","The last wish was for the sausages ___.",["to go away","to grow"],0,"to go away"],["r","Say your three wishes.","My first wish is for a computer because ... My second wish is to visit a rainforest because ..."],["r","Why did the wife shout?","Because the fisherman wished for sausages, not money or gold."],["r","Retell Three Wishes in 5 sentences.","A poor fisherman caught a fish ... three wishes ... sausages ... nose ... the last wish ..."],["r","Which word: there, they're or their? \"(...) happy.\"","They're happy."]],"cb":[[119,"Phonics and spelling"],[120,"Skills time: reading"],[121,"Listening, speaking, writing preparation"]],"wb":"Workbook pp. 111–113 (the writing task is the last page)","steps":["Warm-up: five quick big-screen questions on the last rule","Phonics (p. 119): vocabulary homophones: see / sea · hear / here · wear / where · write / right (the same sound, different spelling)","Reading words (p. 120): read the English and the Russian, say and repeat","Reading (p. 120): A traditional story: Three Wishes: listen, read aloud in pairs, answer the questions","Retell with these words: fisherman, wife, three wishes, sausages, nose, silly, last wish, disappear","Big screen: practice the rule (mixed with the old rules)","Listening and speaking (p. 121): Listening: what do Lucas, Rosy and Akram wish for? Speaking: Imagine a fish gives you three wishes. My first wish is for ... because ... My second wish is to ... because ... My third wish is for ...","Writing preparation (p. 121): Speech marks \"...\" show that someone is speaking, and a comma or question mark goes INSIDE: \"Please throw me back,\" said the fish. The writing task is the end of a story. The writing task is homework.","Story · The Tiger Who Showed How It Happened: look at the picture and guess; teach the new words (the Russian is in the vocabulary file); read aloud in turns; tell what happens in 5 sentences with the key words","Story: the kids close the book and retell it to a partner","Baamboozle in two teams","Translation check: 10 sentences + 2 challenge"],"story":[{"n":8,"title":"The Tiger Who Showed How It Happened","pic":"st5-08","paras":["A man made a deep hole in the road and put a cage at the bottom of it. In the morning there was a tiger in the cage, and his name was Sher.","Sher pushed the door and hit the door, but the door did not open. He was thirsty and he was very hungry, and he was going to stay in that hole for ever.","Then an old goat called Boz came along the road. “Brother Boz!” called Sher. “Open this door! I will die in here!” “You will eat me,” said Boz.","“Eat you? I have never eaten a goat in my life. I eat grass! Open the door, and I promise I will never touch you.”","Boz was not clever, but he had a good heart, so he pulled the door open with a long stick. Sher walked out into the sun and looked at the old goat for a long time.","“Now,” he said, “I am going to eat you.” “But you made a promise!” said Boz. “I was in a cage. Nobody keeps a promise in a cage.”","“Then we must ask somebody first,” said Boz. “We will ask three of them. If all three say you can eat me, I will not run away.”","Sher laughed and agreed, because he was hungry and he liked games.","First they asked the old buffalo in the field. “Men worked me for twenty years,” the buffalo said. “Now I am old and they give me nothing. Eat him.”","Then they asked the big tree by the water. “I give shade to everybody all day long,” said the tree, “and they cut my branches. Eat him.”","Then they asked the road. “Everybody walks on me and nobody says thank you,” said the road. “Eat him.”","Boz sat down and closed his eyes. Then a thin little jackal came round the corner with a very sad face. “Wait!” said Boz. “We must ask him too!”","So Sher told him the whole story. The jackal listened with his head on one side. “I am sorry,” he said. “I am a stupid animal. Who was in the hole? The goat?”","“No! I was in the hole!” “Oh, I see. And the goat was in the cage.” “The goat was on the road! I was in the cage! In the cage!”","“Please do not shout at me,” said the jackal. “I only understand a thing when I can see it with my eyes. Where was this cage?”","Sher ran back to the hole, and the other two looked down at him from the road.","“Here!” he shouted. He jumped inside and turned round. “I was standing here, like this, and the door was here, and the door was shut!”","“Shut?” said the jackal. “Like this?” He pushed the door with his nose, and it locked.","“Now I understand everything,” he said. “Come on, brother Boz. We are going the same way.”","Boz still tells this story to everybody. And the jackal still says that he is the stupidest animal in the forest, and now nobody believes him."],"words":[["cage","keɪdʒ","клетка","A box of metal bars that keeps an animal inside."],["tiger","ˈtaɪɡə","тигр","A big wild cat with black lines on it."],["goat","ɡəʊt","коза, козёл","A farm animal that eats grass and climbs well."],["jackal","ˈdʒækɔːl","шакал","A wild animal like a small thin dog."],["buffalo","ˈbʌfələʊ","буйвол","A big strong animal that works on a farm."],["thirsty","ˈθɜːsti","испытывающий жажду","Needing to drink."],["hungry","ˈhʌŋɡri","голодный","Needing to eat."],["stick","stɪk","палка","A long thin piece of wood."],["shade","ʃeɪd","тень","A cool dark place out of the sun."],["shut","ʃʌt","закрытый, закрывать","Closed, so nobody can go in or out."],["lock","lɒk","запирать","To close something so that nobody can open it."],["corner","ˈkɔːnə","угол, поворот","The place where two walls or two roads meet."]],"phrases":[["make a promise","дать обещание","But you made a promise!"],["have a good heart","быть добрым","Boz was not clever, but he had a good heart."]],"retell":["cage","tiger","goat","jackal","buffalo","thirsty","hungry"]}]}},{"n":3,"subtopic":"Review 5 · Units 13–15","kd":{"kind":"review","label":"Review 5 · Units 13–15","goal":"No new topic: everything from Units 13–15. Mixed grammar practice on the big screen and Fluency Time.","tr":[["Помоги мне, пожалуйста.","Please help me."],["Я вижу его, но не вижу её.","I can see him, but I can't see her."],["Это мальчик, который сделал смузи.","This is the boy who made the smoothie."],["Это магазин, в котором продают бананы.","This is the store which sells bananas."],["Вчера в три часа я читал книгу.","At three o'clock yesterday I was reading a book."],["Они не шли в кино.","They weren't going to the movies."],["Я родился в две тысячи тринадцатом году.","I was born in 2013."],["Когда я работал, зазвонил телефон.","When I was working, the phone rang."],["Они едут навестить своих двоюродных братьев.","They're going to see their cousins."],["Мы хотим играть с вами.","We want to play with you."]],"ch":[["Это девочка, которая помогла мне, и я хочу поблагодарить её, потому что она не знала меня.","This is the girl who helped me, and I want to thank her because she didn't know me."],["Мы смотрели телевизор, когда папа сказал, что у него новая работа, и мы все закричали от радости.","We were watching TV when Dad said he had a new job, and we all screamed with joy."]],"us":[],"copy":[],"rwords":[],"retell":[],"rule":null,"hasBig":true,"big":[["c","Can you help ___?",["I","me"],1,"object → me"],["c","I can see ___. (the girls)",["they","them"],1,"object → them"],["c","This is the dog ___ drank the milk.",["who","which"],1,"a thing → which"],["c","At five o'clock yesterday I ___ my homework.",["Past simple","Past continuous","Present perfect"],1,"in progress at a time → was doing"],["c","When the phone rang, I ___ a book.",["read","was reading"],1,"long action → was reading"],["c","Which one? \"___ going to see ___ cousins.\"",["They're / their","There / they're"],0,"They're + their"],["c","I ___ my room. It is clean now.",["Past simple","Past continuous","Present perfect"],2,"result now → present perfect"],["r","Find the mistake: Please help I.","Please help me."],["r","Find the mistake: This is the boy which dropped the milk.","This is the boy who dropped the milk."],["r","Find the mistake: They was fishing.","They were fishing."],["r","Find the mistake: I was born at 2013.","I was born in 2013."],["r","Say: yesterday / 3 o'clock / watch TV","At three o'clock yesterday I was watching TV."]],"cb":[[122,"Fluency Time: In the playground"],[123,"Project"],[124,"Review 5"],[125,"Review 5"]],"wb":"Workbook pp. 114–115 and 116–117","steps":["Warm-up: the 3 earlier sentences from the last translation check","Mini test (file): 12 questions on Units 13–15","Speaking in pairs: the speaking questions (in the answers file)","Fluency Time (p. 122): In the playground. Are you on your own? / You can play with us. / Do you want to play chess? / Thanks. That's great. / How about playing basketball? / That sounds fun.","Project: a mini book (or for homework)","Big screen: grammar practice (which rule is it?)","Review pages (pp. 124–125) together","Check the test; each kid fixes three mistakes","Translation check: 10 sentences + 2 challenge"]}}],"goal":"Unit 15A · Unit 15B · Review 5"},{"n":14,"title":"Week 14","icon":"School","lessons":[{"n":1,"subtopic":"Reading 5 · Gold","kd":{"kind":"reading","label":"Reading 5 · Gold","goal":"Read, learn the key words, and retell: The Gold Rush · King Midas and the Golden Touch.","tr":[["Калифорния — один из самых известных штатов США.","California is one of the most famous states in the USA."],["До тысяча восемьсот сорок восьмого года Сан-Франциско был маленькой деревней.","Until 1848, San Francisco was only a tiny village."],["Люди нашли золото в реке.","People found gold in the river."],["Триста тысяч человек поехали в Калифорнию искать золото.","300,000 people travelled to California to look for gold."],["Их называли золотоискателями.","The people who looked for gold were called prospectors."],["Работа была очень тяжёлой.","Looking for gold was very hard work."],["Царь Мидас был очень богатым и очень жадным.","King Midas was very rich and very greedy."],["Он захотел, чтобы всё, чего он касается, превращалось в золото.","He wished that everything he touched became gold."],["Его хлеб и вода тоже превратились в золото.","His bread and water also turned to gold."],["Он больше никогда не просил золото.","He never asked for more gold again."]],"ch":[["Когда золота в реках стало мало, большинство золотоискателей остались бедными и уехали в другие места.","When there was little gold in the rivers, most of the prospectors stayed poor and went somewhere else."],["Мидас пожелал, чтобы его дочь вернулась, и все золото исчезло, потому что он понял, что еда и семья важнее.","Midas wished for his daughter to come back, and all the gold went away, because he learned that food and family are more important."]],"us":[],"copy":["gold","prospector","pan","camp","rich","poor","palace","greedy","touch","lesson"],"rwords":["gold","prospector","pan","camp","rich","poor","palace","greedy","touch","lesson"],"retell":["California","James Marshall","gold","prospectors","San Francisco","King Midas","wish","touch","daughter","lesson"],"rule":null,"hasBig":true,"big":[["r","What did James Marshall find in the river?","Little pieces of shiny yellow metal: gold."],["r","When was the Gold Rush?","Between 1848 and 1855."],["r","How did prospectors find gold?","By 'panning for gold' with a big pan."],["r","Did all the prospectors become rich?","No, most of them found very little gold and were very poor."],["r","What did King Midas wish for?","That everything he touched became gold."],["r","What happened to his bread and water?","They turned to gold, so he could not eat or drink."],["r","What happened to his daughter?","She touched his hand and became gold."],["r","What was his second wish?","To have his daughter back and to not have any more gold."],["r","What is the moral of the story?","Do not be greedy. Family and food are more important than gold."],["r","What is your favorite story from your country?","My favorite story is ..."]],"cb":[[126,"Gold (1)"],[127,"Gold (2)"]],"wb":"No Workbook pages. Homework: write 5 sentences in the copybook (the retell).","steps":["Warm-up: the 3 earlier sentences from the last translation check","Pre-teach the key words: read the English and the Russian from the vocabulary file","Look at the pictures and guess: What is the text about?","Listen and read the first text (twice: once to listen, once in pairs); answer the questions","The same for the second text","Retell with these words: California, James Marshall, gold, prospectors, San Francisco, King Midas, wish, touch, daughter, lesson","Big screen: comprehension questions","Translation check: 10 sentences + 2 challenge"]}},{"n":2,"subtopic":"Culture · Shopping, wildlife, Australia","kd":{"kind":"culture","label":"Culture · Shopping, wildlife, Australia","goal":"Talk about shopping in London, wildlife parks and Australia. Compare with our country.","tr":[["Многие британцы любят ходить по магазинам.","Lots of British people love shopping."],["Хэмлис — самый большой магазин игрушек в Великобритании.","Hamleys is the biggest toy store in the UK."],["В этом магазине много игрушек.","There are lots of toys in this store."],["Здесь почти нет больших магазинов.","There are hardly any big stores here."],["Там есть несколько уличных артистов.","There are a few street entertainers there."],["Я был в аквариуме всю ночь.","I've been at the aquarium for the whole night."],["Зоопарк открыт с тысяча девятьсот тридцать первого года.","The zoo has been open since 1931."],["В Австралии больше кенгуру, чем людей.","There are more kangaroos than people in Australia."],["Если мы поедем в Сидней, мы увидим Оперный театр.","If we go to Sydney, we'll visit the Opera House."],["Столица Австралии — Канберра.","The capital of Australia is Canberra."]],"ch":[["Если мы поедем в Австралию в январе, мы увидим парады и фейерверки в День Австралии.","If we go to Australia in January, we'll see parades and fireworks on Australia Day."],["Джемма была в зоопарке с семи часов утра, и она уже видела слонов, носорогов и верблюдов.","Jemma has been at the zoo since seven o'clock in the morning, and she's already seen the elephants, rhinos and camels."]],"us":[["shop","store"],["shopping centre","shopping center / mall"],["harbour","harbor"],["favourite","favorite"],["trainers","sneakers"],["colours","colors"]],"copy":["shopping mall","department store","street entertainer","aquarium","zoo","keeper","shark","Outback","kangaroo","harbor"],"rwords":[],"retell":[],"rule":null,"hasBig":true,"big":[["r","What is the biggest toy store in the UK?","Hamleys."],["r","When is Brick Lane Market open?","On Sundays."],["r","Where is the National Marine Aquarium?","In Plymouth."],["r","Where did Finn sleep?","In the aquarium, in front of a huge fish tank."],["r","What is the biggest zoo in the UK?","Whipsnade Zoo."],["r","What is the capital of Australia?","Canberra (not Sydney)."],["r","Say a sentence with If about Australia.","If we go to Sydney, we'll visit the Opera House."],["r","Say something about shopping in your country.","There are lots of ... in my city."]],"cb":[[130,"Shopping"],[131,"Shopping"],[132,"Watching wildlife"],[133,"Watching wildlife"],[134,"Australia"],[135,"Australia"]],"wb":"Homework: write 5 sentences about a place in your country in the copybook.","steps":["Warm-up: the 3 earlier sentences from the last translation check","Shopping (pp. 130–131): read, say which child says what","Watching wildlife (pp. 132–133): read, true / false","Australia (pp. 134–135): read, find the sentences with If","Talk: how is it the same or different in our country?","Big screen: quick questions","Translation check: 10 sentences + 2 challenge"]}},{"n":3,"subtopic":"Final test","kd":{"kind":"final","label":"Final test","goal":"Show what you learned in Family and Friends 4.","tr":[["Мы обычно едим пасту, но сейчас мы едим пиццу.","We usually have pasta, but now we're having pizza."],["У нас был концерт на прошлой неделе.","We had a concert last week."],["Мы не ходили в школу, мы ходили в музей.","We didn't go to school. We went to a museum."],["Эта куртка моя.","This jacket is mine."],["Нам надо поторопиться, потому что мы заблудились.","We have to hurry because we're lost."],["Эта кровать мягче, чем та.","This bed is softer than that one."],["В будущем люди будут летать на ракетах.","In the future, people will fly in rockets."],["Сколько у тебя денег?","How much money do you have?"],["Ты когда-нибудь был в пустыне?","Have you ever been to a desert?"],["Когда я работал, зазвонил телефон.","When I was working, the phone rang."]],"ch":[["Вчера в три часа мы смотрели фильм, потому что на прошлой неделе мы не успели его посмотреть.","Yesterday at three o'clock we were watching a movie because we didn't have time to watch it last week."],["Он никогда не был в космосе, но если он будет много учиться, он станет космонавтом.","He's never been to space, but if he studies a lot, he'll be an astronaut."]],"us":[],"copy":[],"rwords":[],"retell":[],"rule":null,"hasBig":true,"big":[["c","I ___ soccer every Saturday.",["play","am playing","played"],0,"every Saturday → present simple"],["c","Look! I ___ soccer now.",["play","am playing","played"],1,"Look! → present continuous"],["c","I ___ soccer yesterday.",["play","am playing","played"],2,"yesterday → past simple"],["c","Tomorrow I ___ soccer.",["play","will play","played"],1,"tomorrow → will"],["c","I ___ my room. It's clean now.",["tidied yesterday","'ve tidied","was tidying"],1,"result now → present perfect"],["c","At five o'clock yesterday I ___ TV.",["watched","was watching","watch"],1,"in progress at a time → was watching"],["r","Find the mistake: Have you ever went to Egypt?","Have you ever been to Egypt?"],["r","Find the mistake: They was at the concert.","They were at the concert."],["r","Find the mistake: How much pencils do you have?","How many pencils do you have?"],["r","Find the mistake: Please help I.","Please help me."]],"cb":[],"wb":"No homework","steps":["Written test (file): 20 questions on the whole book","Speaking test: 8 questions, one kid at a time (in the answers file)","Big screen: which tense is it?","Check the test together","Translation check: 10 sentences + 2 challenge"]}}],"goal":"Reading 5 · Culture · Final test"}]}];
